// Cyrus data pack studio: what differs per Minecraft version, and the vanilla id lists (pure, server + build service).
//
// Every format difference below was VERIFIED on the real jars (2026-10-10, node-2): the vanilla data generator of
// each pinned server jar (`--reports --server`) dumped the vanilla data pack, and the same recipe / loot table /
// advancement / enchantment files were compared across versions (see docs "Cyrus data pack studio (R2)"), then
// cross-checked against vanilla-mcdoc (MIT, pinned commit in data/mcdoc-subset.json). Version strings compare
// numerically (1.21.11 > 1.21.4; 26.x > 1.21.x).
import idsData from "./data/vanilla-ids.json";
import { getVersion } from "../versions/registry";

export type McVersion = string;

/** -1 / 0 / 1 like a comparator. "1.21.2" vs "1.21.11": 2 < 11. Missing parts count as 0 (26.1 == 26.1.0). */
export function compareMc(a: string, b: string): number {
  const pa = a.split(".").map(Number), pb = b.split(".").map(Number);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const x = pa[i] ?? 0, y = pb[i] ?? 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}
export const atLeast = (v: string, min: string) => compareMc(v, min) >= 0;

/** Versions the studio can emit for: the ones whose vanilla ids were generated from the real jar. */
export const DATAPACK_VERSIONS: readonly string[] = (idsData as { versions: string[] }).versions;

export type DataPackFeatures = {
  version: string;
  format: { major: number; minor: number };
  /** <1.21.9: `pack_format` (+ no minor); >=1.21.9: `min_format` / `max_format` as [major, minor]. */
  mcmeta: "pack_format" | "min_max";
  /** <=1.21.1: ingredients are objects ({"item": id} / {"tag": id}); >=1.21.2: strings ("id" / "#tag"). */
  ingredient: "object" | "string";
  /** <=1.21.4: text-valued item components (item_name, lore) are JSON strings; >=1.21.5: text component objects. */
  componentText: "json-string" | "object";
  /** <1.21.5: advancement backgrounds are texture paths (minecraft:textures/gui/.../stone.png); >=1.21.5: ids (minecraft:gui/.../stone). */
  background: "texture-path" | "id";
  /** <26.2: entity predicates use plain keys ({"type": ...}); >=26.2: namespaced sub-predicates ({"minecraft:entity_type": ...}). */
  entityPredicate: "plain" | "sub-map";
  /** <26.1: smelting-family results are a single item (no count); >=26.1: an item stack template (count allowed). */
  cookingResultCount: boolean;
  /** smithing_transform takes `group` only before 26.1 (vanilla-mcdoc). */
  smithingGroup: boolean;
  /** <26.1 vanilla writes `count: 1` in advancement icons; 26.1+ omits it (both read the same; we mirror vanilla). */
  iconCount: boolean;
};

export type FeaturesResult = { ok: true; features: DataPackFeatures } | { ok: false; error: string };

/** Fails closed: unknown version, no verified data pack format, or no generated vanilla ids for it. */
export function dataPackFeatures(version: string): FeaturesResult {
  const row = getVersion(version);
  if (!row) return { ok: false, error: `Minecraft ${version} is not in the version registry` };
  if (!row.dataPack) return { ok: false, error: `the data pack format of Minecraft ${version} is not verified yet` };
  if (!DATAPACK_VERSIONS.includes(version)) return { ok: false, error: `Cyrus has no vanilla id list for Minecraft ${version} yet (needs a pinned server jar on the build host)` };
  return {
    ok: true,
    features: {
      version,
      format: row.dataPack,
      mcmeta: atLeast(version, "1.21.9") ? "min_max" : "pack_format",
      ingredient: atLeast(version, "1.21.2") ? "string" : "object",
      componentText: atLeast(version, "1.21.5") ? "object" : "json-string",
      background: atLeast(version, "1.21.5") ? "id" : "texture-path",
      entityPredicate: atLeast(version, "26.2") ? "sub-map" : "plain",
      cookingResultCount: atLeast(version, "26.1"),
      smithingGroup: !atLeast(version, "26.1"),
      iconCount: !atLeast(version, "26.1"),
    },
  };
}

// ---------------------------------------------------------------------------------------------------------------
// Vanilla ids (names only, generated from Mojang's data generator; see data/vanilla-ids.json "source")
// ---------------------------------------------------------------------------------------------------------------
export type IdKind =
  | "item" | "block" | "entity_type" | "enchantment" | "loot_table" | "advancement" | "recipe" | "mob_effect" | "attribute"
  | "tag/item" | "tag/block" | "tag/entity_type" | "tag/enchantment"
  | "loot_function_type" | "loot_condition_type" | "loot_pool_entry_type" | "trigger_type" | "recipe_serializer"
  | "enchantment_effect_component_type" | "enchantment_value_effect_type" | "command" | "execute_sub" | "gamerule";

type IdsFile = { versions: string[]; ids: Record<string, Record<string, string[]>> };
const IDS = idsData as unknown as IdsFile;
const cache = new Map<string, Set<string>>();

/** The set of vanilla names (without "minecraft:") of one kind in one version. Empty for an unknown version. */
export function vanillaIds(kind: IdKind, version: string): Set<string> {
  const key = `${kind}@${version}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const bit = IDS.versions.indexOf(version);
  const out = new Set<string>();
  if (bit >= 0) for (const [mask, names] of Object.entries(IDS.ids[kind] ?? {})) if ((Number(mask) >> bit) & 1) for (const n of names) out.add(n);
  cache.set(key, out);
  return out;
}

/** Is `id` ("minecraft:x", "x" or "#minecraft:x" for tags) a vanilla id of this kind in this version? */
export function isVanilla(kind: IdKind, id: string, version: string): boolean {
  const bare = id.replace(/^#/, "").replace(/^minecraft:/, "");
  return vanillaIds(kind, version).has(bare);
}

/** The generated versions where a vanilla id exists (for a helpful error: "needs 1.21.4+" / "removed in 1.21.11"). */
export function versionsWith(kind: IdKind, id: string): string[] {
  return IDS.versions.filter((v) => isVanilla(kind, id, v));
}

/** Why a vanilla id is missing in `version`, in words. */
export function missingIdReason(kind: IdKind, id: string, version: string): string {
  const what = kind.startsWith("tag/") ? `${kind.slice(4)} tag` : kind.replace(/_/g, " ");
  const has = versionsWith(kind, id);
  if (!has.length) return `${id} is not a vanilla ${what} in any supported Minecraft version`;
  if (has.every((x) => compareMc(x, version) > 0)) return `${id} needs Minecraft ${has[0]} or newer (this pack targets ${version})`;
  if (has.every((x) => compareMc(x, version) < 0)) return `${id} was removed after Minecraft ${has[has.length - 1]} (this pack targets ${version})`;
  return `${id} is not a vanilla ${what} in Minecraft ${version} (it exists in ${has.join(", ")})`;
}

export const VANILLA_IDS_SOURCE = (idsData as unknown as { source: unknown }).source;
// Static validator for data pack FILES (what the emitters wrote, or raw JSON from an imported pack), per version:
//   mcmeta         pack.mcmeta shape (pack_format before 1.21.9, min_format/max_format after) and the registry's number
//   mcdoc_fields   top-level keys of recipes / loot tables / pools / entries / functions / conditions / advancements /
//                  criteria / enchantments against the vanilla-mcdoc field tables (./mcdoc.ts)
//   value_shapes   the format changes that break packs silently: ingredient shape (1.21.2), text in item components
//                  (1.21.5), advancement background (1.21.5), entity predicates (26.2), cooking result count (26.1)
//   vanilla_ids    recipe types, loot function / condition types, triggers, items in results and ingredients exist
//   function_safety the .mcfunction allowlist (./functions.ts)
//   not_checked    resources outside the studio's subset (worldgen, predicates, ...): listed, kept, never judged
// Pure: works on { path, text } pairs. A check that found nothing to look at is "pass" with an empty list.
import { checkFunctions } from "./functions";
import { checkKeys, dispatchFields, structFields } from "./mcdoc";
import type { CheckStatus, DpCheck } from "./spec";
import { dataPackFeatures, isVanilla, vanillaIds, type DataPackFeatures, type IdKind } from "./versions";

export const FILE_CHECKS = ["mcmeta", "mcdoc_fields", "value_shapes", "vanilla_ids", "function_safety", "not_checked"] as const;
export type PackFile = { path: string; text: string };
export type FileReport = { ok: boolean; version: string; checks: DpCheck[]; errors: string[]; warnings: string[]; notChecked: string[] };

const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);
const COOKING = ["minecraft:smelting", "minecraft:blasting", "minecraft:smoking", "minecraft:campfire_cooking"];

/** data/<ns>/<type>/<path>.<ext> -> parts (singular folders only: the studio's floor is 1.21.1). */
export function dataPath(p: string): { ns: string; type: string; id: string; ext: string } | null {
  const m = /^data\/([a-z0-9_.-]+)\/((?:tags\/[a-z_]+)|[a-z_]+)\/([a-z0-9_./-]+)\.(json|mcfunction)$/.exec(p);
  if (!m) return null;
  return { ns: m[1], type: m[2], id: `${m[1]}:${m[3]}`, ext: m[4] };
}

export function validatePackFiles(files: PackFile[], version: string): FileReport {
  const items = new Map<string, string[]>(FILE_CHECKS.map((c) => [c, []]));
  const failed = new Set<string>();
  const errors: string[] = [], warnings: string[] = [], notChecked: string[] = [];
  const fail = (c: string, m: string) => { failed.add(c); items.get(c)!.push(m); errors.push(m); };
  const warn = (c: string, m: string) => { items.get(c)!.push(`warn ${m}`); warnings.push(m); };
  const fr = dataPackFeatures(version);
  const finish = (): FileReport => ({
    ok: errors.length === 0, version, errors, warnings, notChecked,
    checks: FILE_CHECKS.map((id) => ({ id, status: (failed.has(id) ? "fail" : items.get(id)!.length ? (id === "not_checked" ? "warn" : "warn") : "pass") as CheckStatus, items: items.get(id)!.slice(0, 20) })),
  });
  if (!fr.ok) { fail("mcmeta", fr.error); return finish(); }
  const fe = fr.features;

  const mc = files.find((f) => f.path === "pack.mcmeta");
  if (!mc) fail("mcmeta", "pack.mcmeta is missing (Minecraft ignores the pack)");
  else checkMcmeta(mc.text, fe, (m) => fail("mcmeta", m));

  const fnFiles: { id: string; commands: string[] }[] = [];
  const fnTags = new Map<string, string[]>();
  const nsSet = new Set<string>();
  for (const f of [...files].sort((a, b) => (a.path < b.path ? -1 : 1))) {
    if (f.path === "pack.mcmeta" || f.path === "pack.png") continue;
    const d = dataPath(f.path);
    if (!d) { notChecked.push(f.path); continue; }
    nsSet.add(d.ns);
    if (d.ext === "mcfunction") { if (d.type === "function") fnFiles.push({ id: d.id, commands: f.text.split(/\r?\n/) }); else notChecked.push(f.path); continue; }
    let j: unknown;
    try { j = JSON.parse(f.text.replace(/^\uFEFF/, "")); } catch (e) { fail("mcdoc_fields", `${f.path}: not valid JSON (${(e as Error).message.slice(0, 80)})`); continue; }
    const ctx: Ctx = { at: f.path, fe, v: version, fail, warn };
    if (d.type === "recipe") checkRecipe(j, ctx);
    else if (d.type === "loot_table") checkLoot(j, ctx);
    else if (d.type === "advancement") checkAdvancement(j, ctx);
    else if (d.type === "enchantment") checkEnchantment(j, ctx);
    else if (d.type.startsWith("tags/")) {
      checkTag(j, ctx);
      if (d.type === "tags/function" && isObj(j) && Array.isArray(j.values)) fnTags.set(`#${d.id}`, j.values.filter((x): x is string => typeof x === "string" && !x.startsWith("#")));
    }
    else notChecked.push(f.path);
  }
  // functions per namespace (the allowlist does not depend on the namespace; calls must stay inside it)
  for (const ns of [...nsSet].sort()) {
    const mine = fnFiles.filter((x) => x.id.startsWith(`${ns}:`));
    if (!mine.length) continue;
    const r = checkFunctions(mine.map((x) => ({ id: x.id.slice(ns.length + 1), commands: x.commands })), {
      namespace: ns, versionCommands: vanillaIds("command", version), versionGamerules: vanillaIds("gamerule", version), functionTags: fnTags,
      tickFunctions: fnTags.get("#minecraft:tick") ?? [], loadFunctions: fnTags.get("#minecraft:load") ?? [],
    });
    for (const x of r.findings) (x.severity === "error" ? (m: string) => fail("function_safety", m) : (m: string) => warn("function_safety", m))(`${x.at}: ${x.message}`);
  }
  for (const p of notChecked) items.get("not_checked")!.push(p);
  return finish();
}

type Ctx = { at: string; fe: DataPackFeatures; v: string; fail: (c: string, m: string) => void; warn: (c: string, m: string) => void };

function checkMcmeta(text: string, fe: DataPackFeatures, fail: (m: string) => void) {
  let j: unknown;
  try { j = JSON.parse(text); } catch { return fail("pack.mcmeta is not valid JSON"); }
  const p = isObj(j) ? j.pack : null;
  if (!isObj(p)) return fail("pack.mcmeta has no pack object");
  if (p.description === undefined) fail("pack.mcmeta needs a description");
  const { major, minor } = fe.format;
  if (fe.mcmeta === "pack_format") {
    if (p.pack_format !== major) fail(`pack.mcmeta pack_format must be ${major} for Minecraft ${fe.version} (is ${JSON.stringify(p.pack_format)})`);
    if ("min_format" in p || "max_format" in p) fail("min_format / max_format only exist from 1.21.9");
  } else {
    const ok = (x: unknown) => Array.isArray(x) && x[0] === major && (x[1] ?? 0) === minor || x === major && minor === 0;
    if (!ok(p.min_format) || !ok(p.max_format)) fail(`pack.mcmeta needs min_format and max_format [${major}, ${minor}] for Minecraft ${fe.version}`);
    if ("supported_formats" in p) fail("supported_formats must not be used with min_format (1.21.9+)");
  }
}

function keys(ctx: Ctx, where: string, obj: Record<string, unknown>, t: ReturnType<typeof structFields>, ignore: string[] = []) {
  const r = checkKeys(obj, t, ignore);
  for (const k of r.unknown) ctx.fail("mcdoc_fields", `${ctx.at}: ${where} has the key "${k}", which Minecraft ${ctx.v} does not know`);
  for (const k of r.missing) ctx.fail("mcdoc_fields", `${ctx.at}: ${where} is missing the required key "${k}" for Minecraft ${ctx.v}`);
}
function vid(ctx: Ctx, kind: IdKind, id: unknown, what: string) {
  if (typeof id !== "string") return ctx.fail("value_shapes", `${ctx.at}: ${what} must be an id string`);
  if (id.replace(/^#/, "").startsWith("minecraft:") || !id.includes(":")) {
    if (!isVanilla(kind, id, ctx.v)) ctx.fail("vanilla_ids", `${ctx.at}: ${what} ${id} does not exist in Minecraft ${ctx.v}`);
  }
}

function checkIngredient(ctx: Ctx, x: unknown, where: string) {
  const one = (y: unknown, inList: boolean) => {
    if (ctx.fe.ingredient === "string") {
      if (typeof y !== "string") return ctx.fail("value_shapes", `${ctx.at}: ${where} must be an item id or #tag string on Minecraft ${ctx.v} (1.21.2+), not ${JSON.stringify(y).slice(0, 60)}`);
      if (inList && y.startsWith("#")) return ctx.fail("value_shapes", `${ctx.at}: ${where}: a list of alternatives may only hold item ids on ${ctx.v} (use one #tag instead)`);
      vid(ctx, y.startsWith("#") ? "tag/item" : "item", y, where);
    } else {
      if (!isObj(y) || (typeof y.item !== "string" && typeof y.tag !== "string")) return ctx.fail("value_shapes", `${ctx.at}: ${where} must be {"item": id} or {"tag": id} on Minecraft ${ctx.v}`);
      if (typeof y.item === "string") vid(ctx, "item", y.item, where); else vid(ctx, "tag/item", y.tag, where);
    }
  };
  if (Array.isArray(x)) { if (!x.length) ctx.fail("value_shapes", `${ctx.at}: ${where} is an empty list`); x.forEach((y) => one(y, true)); } else one(x, false);
}

function checkStack(ctx: Ctx, r: unknown, where: string, cooking: boolean) {
  if (!isObj(r) || typeof r.id !== "string") return ctx.fail("value_shapes", `${ctx.at}: ${where} must be {"id": item, ...}`);
  vid(ctx, "item", r.id, `${where}.id`);
  if (cooking && !ctx.fe.cookingResultCount && ("count" in r || "components" in r)) ctx.fail("value_shapes", `${ctx.at}: ${where}: cooking results take only "id" before Minecraft 26.1`);
  if (isObj(r.components)) for (const k of ["minecraft:item_name", "minecraft:custom_name"]) if (k in r.components) textShape(ctx, r.components[k], `${where}.components.${k}`);
  if (isObj(r.components) && Array.isArray(r.components["minecraft:lore"])) (r.components["minecraft:lore"] as unknown[]).forEach((l, i) => textShape(ctx, l, `${where}.components.minecraft:lore[${i}]`));
}
function textShape(ctx: Ctx, t: unknown, where: string) {
  if (ctx.fe.componentText === "json-string") {
    if (typeof t !== "string") return ctx.fail("value_shapes", `${ctx.at}: ${where}: text in item components must be a JSON string on Minecraft ${ctx.v} (before 1.21.5)`);
    try { JSON.parse(t); } catch { ctx.fail("value_shapes", `${ctx.at}: ${where}: not a JSON text component`); }
  } else if (typeof t === "string" && /^\s*[{[]/.test(t)) ctx.fail("value_shapes", `${ctx.at}: ${where}: from 1.21.5 text components are objects, not JSON strings`);
}

function checkRecipe(j: unknown, ctx: Ctx) {
  if (!isObj(j) || typeof j.type !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: a recipe needs a "type"`);
  vid(ctx, "recipe_serializer", j.type, "recipe type");
  const t = dispatchFields(`recipe_serializer/${j.type.replace(/^minecraft:/, "")}`, ctx.v);
  if (!t) return; // a type outside the subset: id checked, fields not judged
  keys(ctx, "the recipe", j, t, ["type"]);
  const cooking = COOKING.includes(j.type);
  for (const k of ["ingredient", "template", "base", "addition"]) if (k in j) checkIngredient(ctx, j[k], k);
  if (Array.isArray(j.ingredients)) j.ingredients.forEach((x, i) => checkIngredient(ctx, x, `ingredients[${i}]`));
  if (isObj(j.key)) for (const [k, x] of Object.entries(j.key)) checkIngredient(ctx, x, `key.${k}`);
  if ("result" in j) checkStack(ctx, j.result, "result", cooking);
}

function checkConditions(ctx: Ctx, cs: unknown, where: string) {
  if (cs === undefined) return;
  if (!Array.isArray(cs)) return ctx.fail("value_shapes", `${ctx.at}: ${where} must be a list`);
  cs.forEach((c, i) => {
    if (!isObj(c) || typeof c.condition !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: ${where}[${i}] needs "condition"`);
    vid(ctx, "loot_condition_type", c.condition, `${where}[${i}] condition`);
    keys(ctx, `${where}[${i}] (${c.condition})`, c, dispatchFields(`loot_condition/${c.condition.replace(/^minecraft:/, "")}`, ctx.v), ["condition"]);
  });
}
function checkFunctionsJson(ctx: Ctx, fs: unknown, where: string) {
  if (fs === undefined) return;
  if (!Array.isArray(fs)) return ctx.fail("value_shapes", `${ctx.at}: ${where} must be a list`);
  fs.forEach((f, i) => {
    if (!isObj(f) || typeof f.function !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: ${where}[${i}] needs "function"`);
    vid(ctx, "loot_function_type", f.function, `${where}[${i}] function`);
    keys(ctx, `${where}[${i}] (${f.function})`, f, dispatchFields(`loot_function/${f.function.replace(/^minecraft:/, "")}`, ctx.v), ["function"]);
    checkConditions(ctx, f.conditions, `${where}[${i}].conditions`);
  });
}
function checkLoot(j: unknown, ctx: Ctx) {
  if (!isObj(j)) return ctx.fail("mcdoc_fields", `${ctx.at}: a loot table must be an object`);
  keys(ctx, "the loot table", j, dispatchFields("resource/loot_table", ctx.v));
  checkFunctionsJson(ctx, j.functions, "functions");
  if (j.pools !== undefined && !Array.isArray(j.pools)) return ctx.fail("value_shapes", `${ctx.at}: pools must be a list`);
  ((j.pools as unknown[]) ?? []).forEach((p, i) => {
    if (!isObj(p)) return ctx.fail("value_shapes", `${ctx.at}: pools[${i}] must be an object`);
    keys(ctx, `pools[${i}]`, p, structFields("LootPool", ctx.v));
    checkConditions(ctx, p.conditions, `pools[${i}].conditions`); checkFunctionsJson(ctx, p.functions, `pools[${i}].functions`);
    ((Array.isArray(p.entries) ? p.entries : []) as unknown[]).forEach((e, k) => {
      const w = `pools[${i}].entries[${k}]`;
      if (!isObj(e) || typeof e.type !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: ${w} needs "type"`);
      vid(ctx, "loot_pool_entry_type", e.type, `${w} type`);
      keys(ctx, w, e, dispatchFields(`loot_pool_entry/${e.type.replace(/^minecraft:/, "")}`, ctx.v), ["type"]);
      if (e.type === "minecraft:item") vid(ctx, "item", e.name, `${w}.name`);
      checkConditions(ctx, e.conditions, `${w}.conditions`); checkFunctionsJson(ctx, e.functions, `${w}.functions`);
    });
  });
}
function checkAdvancement(j: unknown, ctx: Ctx) {
  if (!isObj(j)) return ctx.fail("mcdoc_fields", `${ctx.at}: an advancement must be an object`);
  keys(ctx, "the advancement", j, dispatchFields("resource/advancement", ctx.v));
  if (isObj(j.display)) {
    keys(ctx, "display", j.display, structFields(j.parent ? "AdvancementDisplay" : "RootAdvancementDisplay", ctx.v));
    const bg = j.display.background;
    if (typeof bg === "string") {
      const pathStyle = /^minecraft:textures\/.*\.png$/.test(bg);
      if (ctx.fe.background === "id" && pathStyle) ctx.fail("value_shapes", `${ctx.at}: display.background is a texture path; from 1.21.5 it is an id like minecraft:gui/advancements/backgrounds/stone`);
      if (ctx.fe.background === "texture-path" && !pathStyle) ctx.fail("value_shapes", `${ctx.at}: display.background must be a texture path (minecraft:textures/....png) before 1.21.5`);
    }
    if (isObj(j.display.icon)) vid(ctx, "item", j.display.icon.id, "display.icon.id");
  }
  if (!isObj(j.criteria) || !Object.keys(j.criteria).length) return ctx.fail("mcdoc_fields", `${ctx.at}: an advancement needs criteria`);
  for (const [n, c] of Object.entries(j.criteria)) {
    if (!isObj(c) || typeof c.trigger !== "string") { ctx.fail("mcdoc_fields", `${ctx.at}: criterion ${n} needs a trigger`); continue; }
    vid(ctx, "trigger_type", c.trigger, `criterion ${n} trigger`);
    keys(ctx, `criterion ${n}`, c, structFields("AdvancementCriterion", ctx.v), ["conditions"]);
    const trig = dispatchFields(`trigger/${c.trigger.replace(/^minecraft:/, "")}`, ctx.v);
    if (trig && isObj(c.conditions)) keys(ctx, `criterion ${n} conditions`, c.conditions, trig);
    const ent = isObj(c.conditions) ? c.conditions.entity : undefined;
    for (const pred of entityPredicates(ent)) {
      const hasPlain = "type" in pred || "flags" in pred || "equipment" in pred, hasSub = Object.keys(pred).some((k) => k.startsWith("minecraft:"));
      if (ctx.fe.entityPredicate === "sub-map" && hasPlain) ctx.fail("value_shapes", `${ctx.at}: criterion ${n}: from 26.2 entity predicates use namespaced keys ("minecraft:entity_type"), not "type"`);
      if (ctx.fe.entityPredicate === "plain" && hasSub) ctx.fail("value_shapes", `${ctx.at}: criterion ${n}: namespaced entity predicates ("minecraft:entity_type") only exist from 26.2`);
    }
  }
}
function entityPredicates(ent: unknown): Record<string, unknown>[] {
  if (Array.isArray(ent)) return ent.filter(isObj).map((c) => c.predicate).filter(isObj);
  return isObj(ent) ? [ent] : [];
}
function checkEnchantment(j: unknown, ctx: Ctx) {
  if (!isObj(j)) return ctx.fail("mcdoc_fields", `${ctx.at}: an enchantment must be an object`);
  keys(ctx, "the enchantment", j, dispatchFields("resource/enchantment", ctx.v));
  if (isObj(j.effects)) for (const k of Object.keys(j.effects)) vid(ctx, "enchantment_effect_component_type", k, "effect component");
}
function checkTag(j: unknown, ctx: Ctx) {
  if (!isObj(j) || !Array.isArray(j.values)) return ctx.fail("mcdoc_fields", `${ctx.at}: a tag needs a values list`);
  for (const k of Object.keys(j)) if (k !== "values" && k !== "replace") ctx.fail("mcdoc_fields", `${ctx.at}: a tag has only "replace" and "values" (found "${k}")`);
  if (j.replace === true) ctx.warn("mcdoc_fields", `${ctx.at}: replace: true wipes whatever other packs put in this tag`);
}
// Field tables derived from vanilla-mcdoc (SpyglassMC, MIT; commit in data/mcdoc-subset.json "source"), resolved per
// Minecraft version: which top-level keys a recipe / loot function / pool / trigger may have, and which are required.
// `since` is inclusive and `until` exclusive, as in mcdoc. Only the subset the emitters write is in the data file
// (scripts/cyrus/datapack-derive.py); anything else resolves to null ("not checked"), never to "fine".
import subset from "./data/mcdoc-subset.json";
import { atLeast, compareMc } from "./versions";

type Field = { n?: string; opt?: boolean; since?: string; until?: string; spread?: string | Field[]; dynamic?: string };
type Dispatch = { since?: string; until?: string; alts: { since?: string; until?: string; fields: Field[] }[] };
const DATA = subset as unknown as { source: Record<string, string>; dispatch: Record<string, Dispatch>; structs: Record<string, Field[]> };

export const MCDOC_SOURCE = DATA.source;
const inRange = (v: string, x: { since?: string; until?: string }) => (!x.since || atLeast(v, x.since)) && (!x.until || compareMc(v, x.until) < 0);

export type FieldTable = { fields: Map<string, { required: boolean }>; open: boolean };

function collect(fields: Field[], v: string, out: FieldTable, depth: number): void {
  if (depth > 12) { out.open = true; return; }
  for (const f of fields) {
    if (!inRange(v, f)) continue;
    if (f.dynamic) { out.open = true; continue; }
    if (f.spread) {
      if (Array.isArray(f.spread)) collect(f.spread, v, out, depth + 1);
      else if (DATA.structs[f.spread]) collect(DATA.structs[f.spread], v, out, depth + 1);
      else out.open = true; // a spread we did not derive: cannot judge extra keys
      continue;
    }
    if (!f.n) continue;
    if (f.n === "*") { out.open = true; continue; }
    const prev = out.fields.get(f.n);
    out.fields.set(f.n, { required: !f.opt || !!prev?.required });
  }
}

/** Fields of `registry/key` (e.g. "loot_function/set_count") in version v; null = not in the subset or not in this version. */
export function dispatchFields(key: string, v: string): FieldTable | null {
  const d = DATA.dispatch[key];
  if (!d || !inRange(v, d)) return null;
  const out: FieldTable = { fields: new Map(), open: false };
  const alts = d.alts.filter((a) => inRange(v, a));
  if (!alts.length) return null;
  for (const a of alts) collect(a.fields, v, out, 0);
  return out;
}

export function structFields(name: string, v: string): FieldTable | null {
  const s = DATA.structs[name];
  if (!s) return null;
  const out: FieldTable = { fields: new Map(), open: false };
  collect(s, v, out, 0);
  return out;
}

/** Keys not allowed / required keys missing, for one JSON object. `ignore` = keys checked elsewhere (e.g. "type"). */
export function checkKeys(obj: Record<string, unknown>, t: FieldTable | null, ignore: string[] = []): { unknown: string[]; missing: string[] } {
  if (!t) return { unknown: [], missing: [] };
  const unknown = t.open ? [] : Object.keys(obj).filter((k) => !t.fields.has(k) && !ignore.includes(k));
  const missing = [...t.fields].filter(([k, f]) => f.required && !(k in obj) && !ignore.includes(k)).map(([k]) => k);
  return { unknown, missing };
}

const REF = /^#?[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const Path = z.string().max(64).regex(PATH, "lowercase letters, digits, _ and / (max 6 segments)");
const RecipePath = z.string().regex(/^[a-z0-9_]{1,48}$/, "lowercase letters, digits, _ (max 48)");
const Ref = z.string().max(120).regex(REF, "a namespaced id like minecraft:diamond or #minecraft:planks");
const Int = (min: number, max: number) => z.number().int().min(min).max(max);

export const TEXT_COLORS = ["black", "dark_blue", "dark_green", "dark_aqua", "dark_red", "dark_purple", "gold", "gray", "dark_gray", "blue", "green", "aqua", "red", "light_purple", "yellow", "white"] as const;
/** Text: a plain string or one styled run. Emitted as a text component (JSON object, or a JSON string where the version needs it). */
export const TextSchema = z.union([
  z.string().min(1).max(200),
  z.strictObject({
    text: z.string().min(1).max(200),
    color: z.union([z.enum(TEXT_COLORS), z.string().regex(/^#[0-9a-fA-F]{6}$/)]).optional(),
    bold: z.boolean().optional(), italic: z.boolean().optional(), underlined: z.boolean().optional(), strikethrough: z.boolean().optional(),
  }),
]);
export type DpText = z.infer<typeof TextSchema>;

/** A number, a uniform range { min, max } or a binomial { n, p }. */
export const NumSchema = z.union([z.number().min(-1000).max(1000), z.strictObject({ min: z.number().min(-1000).max(1000), max: z.number().min(-1000).max(1000) }), z.strictObject({ n: Int(0, 100), p: z.number().min(0).max(1) })]);
export type DpNum = z.infer<typeof NumSchema>;

/** An ingredient: an item id, an item tag (#...), or a list of alternatives. */
export const IngredientSchema = z.union([Ref, z.array(Ref).min(1).max(16)]);
export type DpIngredient = z.infer<typeof IngredientSchema>;

export const ResultSchema = z.strictObject({
  item: Ref, count: Int(1, 99).optional(),
  /** Shown instead of the item's normal name (minecraft:item_name; not italic). Not on cooking results. */
  name: TextSchema.optional(),
  lore: z.array(TextSchema).max(8).optional(),
});
export type DpResult = z.infer<typeof ResultSchema>;

const CraftCategory = z.enum(["building", "redstone", "equipment", "misc"]);
const CookCategory = z.enum(["food", "blocks", "misc"]);
const Group = z.string().regex(/^[a-z0-9_]{1,32}$/);
export const RecipeSchema = z.discriminatedUnion("kind", [
  z.strictObject({ kind: z.literal("shaped"), pattern: z.array(z.string().min(1).max(3)).min(1).max(3), key: z.record(z.string().regex(/^[^ ]$/, "one character (not space)"), IngredientSchema), result: ResultSchema, category: CraftCategory.optional(), group: Group.optional() }),
  z.strictObject({ kind: z.literal("shapeless"), ingredients: z.array(IngredientSchema).min(1).max(9), result: ResultSchema, category: CraftCategory.optional(), group: Group.optional() }),
  z.strictObject({ kind: z.enum(["smelting", "blasting", "smoking", "campfire_cooking"]), ingredient: IngredientSchema, result: ResultSchema, experience: z.number().min(0).max(100).optional(), cookingTime: Int(1, 32767).optional(), category: CookCategory.optional(), group: Group.optional() }),
  z.strictObject({ kind: z.literal("stonecutting"), ingredient: IngredientSchema, result: ResultSchema }),
  z.strictObject({ kind: z.literal("smithing_transform"), template: IngredientSchema, base: IngredientSchema, addition: IngredientSchema, result: ResultSchema }),
]);
export type DpRecipe = z.infer<typeof RecipeSchema>;

export const LootConditionSchema = z.discriminatedUnion("cond", [
  z.strictObject({ cond: z.literal("random_chance"), chance: z.number().min(0).max(1) }),
  z.strictObject({ cond: z.literal("killed_by_player") }),
  z.strictObject({ cond: z.literal("survives_explosion") }),
  /** The tool used (block loot) is one of these items / in this tag. */
  z.strictObject({ cond: z.literal("match_tool"), items: z.union([Ref, z.array(Ref).min(1).max(16)]) }),
  z.strictObject({ cond: z.literal("weather"), raining: z.boolean().optional(), thundering: z.boolean().optional() }),
]);
export type DpCondition = z.infer<typeof LootConditionSchema>;
const Conds = z.array(LootConditionSchema).max(8).optional();
const EnchantOptions = z.union([Ref, z.array(Ref).min(1).max(32)]);
export const LootFunctionSchema = z.discriminatedUnion("fn", [
  z.strictObject({ fn: z.literal("set_count"), count: NumSchema, add: z.boolean().optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_damage"), damage: NumSchema, conditions: Conds }),
  z.strictObject({ fn: z.literal("enchant_randomly"), options: EnchantOptions.optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("enchant_with_levels"), levels: NumSchema, options: EnchantOptions.optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_name"), name: TextSchema, target: z.enum(["custom_name", "item_name"]).optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_lore"), lore: z.array(TextSchema).min(1).max(8), mode: z.enum(["append", "replace_all"]).optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_enchantments"), enchantments: z.record(Ref, Int(1, 255)), add: z.boolean().optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("explosion_decay"), conditions: Conds }),
  z.strictObject({ fn: z.literal("furnace_smelt"), conditions: Conds }),
  /** Extra items per Looting level (vanilla enchanted_count_increase with minecraft:looting). */
  z.strictObject({ fn: z.literal("looting_bonus"), count: NumSchema, conditions: Conds }),
]);
export type DpFunction = z.infer<typeof LootFunctionSchema>;
const Fns = z.array(LootFunctionSchema).max(12).optional();
const Weight = { weight: Int(1, 1000).optional(), quality: Int(-100, 100).optional() };
export const LootEntrySchema = z.discriminatedUnion("kind", [
  z.strictObject({ kind: z.literal("item"), item: Ref, ...Weight, conditions: Conds, functions: Fns }),
  /** expand true: pick ONE item of the tag (each with the entry's weight); false (default): drop every item of the tag. */
  z.strictObject({ kind: z.literal("tag"), tag: Ref, expand: z.boolean().optional(), ...Weight, conditions: Conds, functions: Fns }),
  z.strictObject({ kind: z.literal("loot_table"), table: Ref, ...Weight, conditions: Conds, functions: Fns }),
  z.strictObject({ kind: z.literal("empty"), weight: Int(1, 1000).optional() }),
]);
export type DpEntry = z.infer<typeof LootEntrySchema>;
export const LootPoolSchema = z.strictObject({ rolls: NumSchema, bonusRolls: z.number().min(0).max(100).optional(), entries: z.array(LootEntrySchema).min(1).max(32), conditions: Conds, functions: Fns });
export const LootTableSchema = z.strictObject({
  kind: z.enum(["generic", "chest", "entity", "block", "fishing", "gift"]).default("generic"),
  pools: z.array(LootPoolSchema).min(1).max(16),
  functions: Fns,
});
export type DpLootTable = z.infer<typeof LootTableSchema>;

export const CriterionSchema = z.discriminatedUnion("trigger", [
  z.strictObject({ trigger: z.literal("impossible") }),
  z.strictObject({ trigger: z.literal("tick") }),
  z.strictObject({ trigger: z.literal("inventory_changed"), items: z.array(Ref).min(1).max(9) }),
  z.strictObject({ trigger: z.literal("consume_item"), item: Ref }),
  z.strictObject({ trigger: z.literal("player_killed_entity"), entity: Ref }),
  z.strictObject({ trigger: z.literal("recipe_unlocked"), recipe: Ref }),
  z.strictObject({ trigger: z.literal("recipe_crafted"), recipe: Ref }),
]);
export type DpCriterion = z.infer<typeof CriterionSchema>;
export const ADVANCEMENT_BACKGROUNDS = ["stone", "adventure", "end", "husbandry", "nether"] as const;
export const AdvancementSchema = z.strictObject({
  /** Own (nx_x:...) or vanilla (minecraft:story/root). Without a parent the advancement starts its own tab (needs display.background). */
  parent: Ref.optional(),
  display: z.strictObject({
    icon: Ref, title: TextSchema, description: TextSchema,
    frame: z.enum(["task", "goal", "challenge"]).optional(),
    background: z.enum(ADVANCEMENT_BACKGROUNDS).optional(),
    showToast: z.boolean().optional(), announceToChat: z.boolean().optional(), hidden: z.boolean().optional(),
  }).optional(),
  criteria: z.record(z.string().regex(/^[a-z0-9_]{1,32}$/), CriterionSchema),
  /** all (default): every criterion; any: one of them. */
  requirements: z.enum(["all", "any"]).optional(),
  rewards: z.strictObject({ experience: Int(0, 10000).optional(), loot: z.array(Ref).max(8).optional(), recipes: z.array(Ref).max(16).optional(), function: Ref.optional() }).optional(),
});
export type DpAdvancement = z.infer<typeof AdvancementSchema>;

export const ENCHANTMENT_SLOTS = ["any", "hand", "mainhand", "offhand", "armor", "feet", "legs", "chest", "head", "body"] as const;
/** Value-effect components the emitter supports (each a list of { effect } in vanilla). Must exist in the target version. */
export const ENCHANTMENT_EFFECTS = ["damage", "damage_protection", "knockback", "armor_effectiveness", "item_damage", "mob_experience", "block_experience", "repair_with_xp", "smash_damage_per_fallen_block"] as const;
const Cost = z.strictObject({ base: Int(0, 1000), perLevelAboveFirst: Int(0, 1000) });
const ItemSet = z.union([Ref, z.array(Ref).min(1).max(32)]);
export const EnchantmentSchema = z.strictObject({
  description: TextSchema,
  /** Items it can be applied to: an item tag (#minecraft:enchantable/sword) or item ids. */
  supportedItems: ItemSet,
  primaryItems: ItemSet.optional(),
  exclusiveSet: z.union([Ref, z.array(Ref).min(1).max(32)]).optional(),
  weight: Int(1, 1024), maxLevel: Int(1, 255), minCost: Cost, maxCost: Cost, anvilCost: Int(0, 255),
  slots: z.array(z.enum(ENCHANTMENT_SLOTS)).min(1).max(4),
  effects: z.array(z.strictObject({ component: z.enum(ENCHANTMENT_EFFECTS), op: z.enum(["add", "multiply", "set"]), base: z.number().min(-1000).max(1000), perLevelAboveFirst: z.number().min(-1000).max(1000).optional() })).max(8).optional(),
});
export type DpEnchantment = z.infer<typeof EnchantmentSchema>;

export const TAG_REGISTRIES = ["item", "block", "entity_type", "function", "enchantment"] as const;
export type TagRegistry = (typeof TAG_REGISTRIES)[number];

export const ResourceSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("recipe"), id: RecipePath, recipe: RecipeSchema }),
  z.strictObject({ type: z.literal("loot_table"), id: Path, table: LootTableSchema }),
  z.strictObject({ type: z.literal("advancement"), id: Path, advancement: AdvancementSchema }),
  /**
   * Own tag (`id` = path) or an addition to a vanilla tag (`id` = "minecraft:<existing tag>", replace stays false).
   * Function tags: own, or minecraft:load / minecraft:tick (prefer `runOn` on the function).
   */
  z.strictObject({ type: z.literal("tag"), registry: z.enum(TAG_REGISTRIES), id: z.string().max(80).regex(/^(minecraft:)?[a-z0-9_]+(\/[a-z0-9_]+){0,5}$/), replace: z.boolean().optional(), values: z.array(Ref).min(1).max(256) }),
  /** One command per entry, no leading slash. runOn adds it to #minecraft:load or #minecraft:tick. */
  z.strictObject({ type: z.literal("function"), id: Path, commands: z.array(z.string().max(2000)).min(1).max(256), runOn: z.enum(["load", "tick"]).optional() }),
  z.strictObject({ type: z.literal("enchantment"), id: z.string().regex(/^[a-z0-9_]{1,48}$/), enchantment: EnchantmentSchema }),
]);
export type DpResource = z.infer<typeof ResourceSchema>;
export type DpResourceType = DpResource["type"];

export const DataPackSpecV1Schema = z.strictObject({
  schemaVersion: z.literal(DATAPACK_SPEC_VERSION),
  /** File name (assets/datapack/<name>.json) and pack folder name. */
  name: z.string().regex(/^[a-z][a-z0-9_]{1,31}$/),
  /** pack.mcmeta description. */
  description: z.string().min(1).max(200),
  resources: z.array(ResourceSchema).min(1).max(DATAPACK_LIMITS.maxResources),
});
export type DataPackSpec = z.infer<typeof DataPackSpecV1Schema>;

export function dataPackJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(DataPackSpecV1Schema, { io: "input", reused: "ref" }) as Record<string, unknown>;
}

// ---------------------------------------------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------------------------------------------
export type DpIssue = { path: string; code: string; message: string };
export type CheckStatus = "pass" | "warn" | "fail" | "not_run";
export type DpCheck = { id: string; status: CheckStatus; items: string[] };
export type DpValidation =
  | { ok: true; spec: DataPackSpec; errors: []; warnings: DpIssue[]; checks: DpCheck[]; features: DataPackFeatures }
  | { ok: false; errors: DpIssue[]; warnings: DpIssue[]; checks: DpCheck[] };

export type DpContext = { version: string; namespace: string };

/** Check ids in the order they appear in reports (stable; also used by the service copy). */
export const SPEC_CHECKS = ["schema", "namespace", "vanilla_ids", "references", "version_features", "limits", "function_safety"] as const;

const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");

/** The vanilla-id kind a reference must exist as, per place it is used. */
type RefUse = { at: string; ref: string; kind: IdKind; own?: DpResourceType | "tag:item" | "tag:block" | "tag:entity_type" | "tag:function" | "tag:enchantment" | "function"; tagKind?: IdKind };

export function validateDataPackSpec(input: unknown, ctx: DpContext): DpValidation {
  const errors: DpIssue[] = [];
  const warnings: DpIssue[] = [];
  const bucket = new Map<string, string[]>(SPEC_CHECKS.map((c) => [c, []]));
  const failed = new Set<string>();
  const fail = (check: string, path: string, code: string, message: string) => { errors.push({ path, code, message }); failed.add(check); bucket.get(check)!.push(`${path}: ${message}`); };
  const warn = (check: string, path: string, code: string, message: string) => { warnings.push({ path, code, message }); bucket.get(check)!.push(`warn ${path}: ${message}`); };
  const checksOf = (ran: Set<string>): DpCheck[] => SPEC_CHECKS.map((id) => {
    const items = bucket.get(id)!;
    const status: CheckStatus = !ran.has(id) ? "not_run" : failed.has(id) ? "fail" : items.length ? "warn" : "pass";
    return { id, status, items: items.slice(0, 20) };
  });
  const ran = new Set<string>(["schema"]);

  if (!NAMESPACE_RE.test(ctx.namespace)) { fail("namespace", "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); ran.add("namespace"); return { ok: false, errors, warnings, checks: checksOf(ran) }; }
  const fe = dataPackFeatures(ctx.version);
  ran.add("version_features");
  if (!fe.ok) { fail("version_features", "version", "unsupported_version", fe.error); return { ok: false, errors, warnings, checks: checksOf(ran) }; }
  const v = ctx.version;
  if (input && typeof input === "object" && !Array.isArray(input) && (input as { schemaVersion?: unknown }).schemaVersion !== undefined && (input as { schemaVersion?: unknown }).schemaVersion !== DATAPACK_SPEC_VERSION) {
    fail("schema", "schemaVersion", "schema_version", `schemaVersion must be ${DATAPACK_SPEC_VERSION}`);
    return { ok: false, errors, warnings, checks: checksOf(ran) };
  }
  const parsed = DataPackSpecV1Schema.safeParse(input);
  if (!parsed.success) {
    for (const i of parsed.error.issues.slice(0, 30)) fail("schema", issuePath(i.path) || "(root)", "schema", i.message);
    return { ok: false, errors, warnings, checks: checksOf(ran) };
  }
  const spec = parsed.data;
  for (const c of ["namespace", "vanilla_ids", "references", "limits", "function_safety"]) ran.add(c);
  const ns = ctx.namespace;

  // duplicates + own resource index
  const own = new Map<string, Set<string>>(); // kind -> full ids
  const addOwn = (k: string, id: string) => { if (!own.has(k)) own.set(k, new Set()); own.get(k)!.add(id); };
  const seen = new Set<string>();
  spec.resources.forEach((r, i) => {
    const key = r.type === "tag" ? `tag/${r.registry}:${r.id}` : `${r.type}:${r.id}`;
    if (seen.has(key)) fail("references", `resources[${i}]`, "duplicate_resource", `${r.type} ${r.id} is defined twice`);
    seen.add(key);
    if (r.type === "tag") { if (!r.id.startsWith("minecraft:")) addOwn(`tag:${r.registry}`, `${ns}:${r.id}`); }
    else addOwn(r.type, `${ns}:${r.id}`);
    const kind = r.type === "recipe" ? "recipe" : "resource";
    if (r.type !== "tag" || !r.id.startsWith("minecraft:")) {
      const b = buildIdentifier(ns, kind, r.id.replace(/^minecraft:/, ""));
      if (!b.ok) fail("namespace", `resources[${i}].id`, "bad_id", b.error);
    }
  });

  // collect references
  const refs: RefUse[] = [];
  const ing = (at: string, x: DpIngredient) => {
    if (Array.isArray(x) && fe.features.ingredient === "string" && x.some((r) => r.startsWith("#"))) fail("version_features", at, "tag_in_alternatives", `from Minecraft 1.21.2 a list of alternatives may only hold item ids; use one #tag on its own (this pack targets ${v})`);
    ingRefs(at, x);
  };
  const ingRefs = (at: string, x: DpIngredient) => (Array.isArray(x) ? x : [x]).forEach((r, j) => refs.push(r.startsWith("#") ? { at: Array.isArray(x) ? `${at}[${j}]` : at, ref: r, kind: "tag/item", own: "tag:item" } : { at: Array.isArray(x) ? `${at}[${j}]` : at, ref: r, kind: "item" }));
  const itemSet = (at: string, x: string | string[]) => ing(at, x);
  const res = (at: string, r: DpResult) => refs.push({ at: `${at}.item`, ref: r.item, kind: "item" });
  const conds = (at: string, cs?: DpCondition[]) => cs?.forEach((c, j) => { if (c.cond === "match_tool") itemSet(`${at}[${j}].items`, c.items); });
  const enchRefs = (at: string, o: string | string[]) => (Array.isArray(o) ? o : [o]).forEach((r) => refs.push(r.startsWith("#") ? { at, ref: r, kind: "tag/enchantment", own: "tag:enchantment" } : { at, ref: r, kind: "enchantment", own: "enchantment" }));
  const fns = (at: string, fs?: DpFunction[]) => fs?.forEach((f, j) => {
    const p = `${at}[${j}]`;
    conds(`${p}.conditions`, f.conditions);
    if ((f.fn === "enchant_randomly" || f.fn === "enchant_with_levels") && f.options) enchRefs(`${p}.options`, f.options);
    if (f.fn === "set_enchantments") for (const k of Object.keys(f.enchantments)) enchRefs(`${p}.enchantments`, k);
    if (f.fn === "set_damage" && typeof f.damage === "number" && (f.damage < 0 || f.damage > 1)) fail("schema", `${p}.damage`, "range", "damage is a fraction between 0 and 1");
  });
  const fnRefs: { at: string; ref: string }[] = [];
  spec.resources.forEach((r, i) => {
    const at = `resources[${i}]`;
    if (r.type === "recipe") {
      const rc = r.recipe;
      if (rc.kind === "shaped") {
        const width = rc.pattern[0].length;
        if (rc.pattern.some((row) => row.length !== width)) fail("schema", `${at}.recipe.pattern`, "pattern_rows", "every pattern row must have the same length");
        const used = new Set(rc.pattern.join("").replace(/ /g, "").split(""));
        for (const ch of used) if (!(ch in rc.key)) fail("references", `${at}.recipe.pattern`, "pattern_key", `pattern uses "${ch}" but key has no "${ch}"`);
        for (const k of Object.keys(rc.key)) { if (!used.has(k)) warn("references", `${at}.recipe.key.${k}`, "unused_key", `key "${k}" is not used in the pattern`); ing(`${at}.recipe.key.${k}`, rc.key[k]); }
      } else if (rc.kind === "shapeless") rc.ingredients.forEach((x, j) => ing(`${at}.recipe.ingredients[${j}]`, x));
      else if (rc.kind === "smithing_transform") { ing(`${at}.recipe.template`, rc.template); ing(`${at}.recipe.base`, rc.base); ing(`${at}.recipe.addition`, rc.addition); }
      else ing(`${at}.recipe.ingredient`, rc.ingredient);
      res(`${at}.recipe.result`, rc.result);
      if (rc.result.item.replace(/^minecraft:/, "") === "air") fail("vanilla_ids", `${at}.recipe.result.item`, "air", "a recipe cannot make air");
      if (["smelting", "blasting", "smoking", "campfire_cooking"].includes(rc.kind)) {
        if ((rc.result.count ?? 1) > 1 && !fe.features.cookingResultCount) fail("version_features", `${at}.recipe.result.count`, "version_unsupported", `cooking results with a count need Minecraft 26.1 or newer (this pack targets ${v})`);
        if (rc.result.name || rc.result.lore) fail("version_features", `${at}.recipe.result`, "unsupported", "cooking results cannot carry a name or lore in Cyrus data packs; use a crafting recipe");
      }
    } else if (r.type === "loot_table") {
      fns(`${at}.table.functions`, r.table.functions);
      r.table.pools.forEach((p, j) => {
        const pa = `${at}.table.pools[${j}]`;
        conds(`${pa}.conditions`, p.conditions); fns(`${pa}.functions`, p.functions);
        if (r.table.kind !== "entity" && p.conditions?.some((c) => c.cond === "killed_by_player")) warn("references", `${pa}.conditions`, "context", "killed_by_player only works in entity loot tables");
        p.entries.forEach((e, k) => {
          const ea = `${pa}.entries[${k}]`;
          if (e.kind === "item") refs.push({ at: `${ea}.item`, ref: e.item, kind: "item" });
          if (e.kind === "tag") { if (!e.tag.startsWith("#")) fail("schema", `${ea}.tag`, "tag_ref", "a tag entry needs a #tag id"); else refs.push({ at: `${ea}.tag`, ref: e.tag, kind: "tag/item", own: "tag:item" }); }
          if (e.kind === "loot_table") refs.push({ at: `${ea}.table`, ref: e.table, kind: "loot_table", own: "loot_table" });
          if (e.kind !== "empty") { conds(`${ea}.conditions`, e.conditions); fns(`${ea}.functions`, e.functions); }
        });
      });
    } else if (r.type === "advancement") {
      const a = r.advancement;
      if (a.parent) refs.push({ at: `${at}.advancement.parent`, ref: a.parent, kind: "advancement", own: "advancement" });
      if (a.display) {
        refs.push({ at: `${at}.advancement.display.icon`, ref: a.display.icon, kind: "item" });
        if (!a.parent && !a.display.background) fail("references", `${at}.advancement.display.background`, "root_background", "an advancement without a parent starts a new tab and needs display.background");
        if (a.parent && a.display.background) warn("references", `${at}.advancement.display.background`, "background_ignored", "background only matters on a root advancement (no parent)");
      }
      const names = Object.keys(a.criteria);
      if (!names.length) fail("schema", `${at}.advancement.criteria`, "no_criteria", "an advancement needs at least one criterion");
      if (names.length > 16) fail("limits", `${at}.advancement.criteria`, "too_many", "at most 16 criteria");
      for (const n of names) {
        const c = a.criteria[n], ca = `${at}.advancement.criteria.${n}`;
        if (c.trigger === "inventory_changed") c.items.forEach((x, j) => refs.push(x.startsWith("#") ? { at: `${ca}.items[${j}]`, ref: x, kind: "tag/item", own: "tag:item" } : { at: `${ca}.items[${j}]`, ref: x, kind: "item" }));
        if (c.trigger === "consume_item") refs.push(c.item.startsWith("#") ? { at: `${ca}.item`, ref: c.item, kind: "tag/item", own: "tag:item" } : { at: `${ca}.item`, ref: c.item, kind: "item" });
        if (c.trigger === "player_killed_entity") refs.push(c.entity.startsWith("#") ? { at: `${ca}.entity`, ref: c.entity, kind: "tag/entity_type", own: "tag:entity_type" } : { at: `${ca}.entity`, ref: c.entity, kind: "entity_type" });
        if (c.trigger === "recipe_unlocked" || c.trigger === "recipe_crafted") refs.push({ at: `${ca}.recipe`, ref: c.recipe, kind: "recipe", own: "recipe" });
      }
      a.rewards?.loot?.forEach((x, j) => refs.push({ at: `${at}.advancement.rewards.loot[${j}]`, ref: x, kind: "loot_table", own: "loot_table" }));
      a.rewards?.recipes?.forEach((x, j) => refs.push({ at: `${at}.advancement.rewards.recipes[${j}]`, ref: x, kind: "recipe", own: "recipe" }));
      if (a.rewards?.function) fnRefs.push({ at: `${at}.advancement.rewards.function`, ref: a.rewards.function });
    } else if (r.type === "tag") {
      const vanillaTag = r.id.startsWith("minecraft:");
      if (vanillaTag) {
        if (r.replace) fail("references", `${at}.replace`, "replace_vanilla", `replace: true on ${r.id} would wipe the vanilla tag (and every other pack's additions); Cyrus only appends`);
        if (r.registry === "function") { if (!["minecraft:load", "minecraft:tick"].includes(r.id)) fail("references", `${at}.id`, "function_tag", "the only vanilla function tags are minecraft:load and minecraft:tick"); }
        else if (!isVanilla(`tag/${r.registry}` as IdKind, r.id, v)) fail("vanilla_ids", `${at}.id`, "unknown_vanilla_tag", missingIdReason(`tag/${r.registry}` as IdKind, `#${r.id}`, v));
      } else if (r.replace) warn("references", `${at}.replace`, "replace_own", "replace: true on your own tag only matters if another pack adds to it");
      r.values.forEach((x, j) => {
        const p = `${at}.values[${j}]`;
        if (r.registry === "function") { if (x.startsWith("#")) fail("references", p, "function_tag_value", "function tags list functions, not other tags"); else fnRefs.push({ at: p, ref: x }); return; }
        const kind = (r.registry === "item" ? "item" : r.registry === "block" ? "block" : r.registry === "entity_type" ? "entity_type" : "enchantment") as IdKind;
        refs.push(x.startsWith("#") ? { at: p, ref: x, kind: `tag/${r.registry}` as IdKind, own: `tag:${r.registry}` as RefUse["own"] } : { at: p, ref: x, kind, ...(r.registry === "enchantment" ? { own: "enchantment" as const } : {}) });
      });
    } else if (r.type === "enchantment") {
      const e = r.enchantment;
      itemSet(`${at}.enchantment.supportedItems`, e.supportedItems);
      if (e.primaryItems) itemSet(`${at}.enchantment.primaryItems`, e.primaryItems);
      if (e.exclusiveSet) enchRefs(`${at}.enchantment.exclusiveSet`, e.exclusiveSet);
      if (e.maxCost.base < e.minCost.base) warn("references", `${at}.enchantment.maxCost`, "cost_order", "maxCost.base is below minCost.base: the enchanting table never offers it");
      e.effects?.forEach((x, j) => { if (!isVanilla("enchantment_effect_component_type", x.component, v)) fail("version_features", `${at}.enchantment.effects[${j}].component`, "unknown_effect", `effect component ${x.component} does not exist in Minecraft ${v}`); });
    }
  });

  // resolve references
  for (const u of refs) {
    const nsOf = u.ref.replace(/^#/, "").split(":")[0];
    if (nsOf === "minecraft") {
      if (!isVanilla(u.kind, u.ref, v)) {
        fail("vanilla_ids", u.at, "unknown_vanilla_id", missingIdReason(u.kind, u.ref, v));
      }
    } else if (nsOf === ns) {
      if (!u.own) fail("references", u.at, "not_definable", `${u.ref}: a data pack cannot define new ${u.kind}s (only vanilla ${u.kind}s can be used here)`);
      else if (!own.get(u.own)?.has(u.ref.replace(/^#/, ""))) fail("references", u.at, "unresolved_ref", `${u.ref} is not defined in this pack`);
    } else fail("namespace", u.at, "foreign_namespace", `${u.ref} uses the namespace ${nsOf}; this pack may only use minecraft: and its own ${ns}`);
  }

  // functions: safety + call graph (tags resolved against this pack)
  const fnList = spec.resources.filter((r): r is Extract<DpResource, { type: "function" }> => r.type === "function");
  const functionTags = new Map<string, string[]>();
  const tickFns: string[] = [], loadFns: string[] = [];
  for (const r of spec.resources) if (r.type === "tag" && r.registry === "function") {
    const full = r.id.startsWith("minecraft:") ? r.id : `${ns}:${r.id}`;
    functionTags.set(`#${full}`, r.values.filter((x) => !x.startsWith("#")));
    if (full === "minecraft:tick") tickFns.push(...r.values); if (full === "minecraft:load") loadFns.push(...r.values);
  }
  for (const u of fnRefs) {
    if (!u.ref.startsWith(`${ns}:`)) fail("references", u.at, "function_ref", `${u.ref}: only this pack's own functions can be referenced`);
    else if (!fnList.some((f) => `${ns}:${f.id}` === u.ref)) fail("references", u.at, "unresolved_ref", `function ${u.ref} is not defined in this pack`);
  }
  const fr = checkFunctions(fnList.map((f) => ({ id: f.id, commands: f.commands, runOn: f.runOn })), {
    namespace: ns, versionCommands: vanillaIds("command", v), versionGamerules: vanillaIds("gamerule", v), functionTags, tickFunctions: tickFns, loadFunctions: loadFns,
  });
  for (const x of fr.findings as FnFinding[]) (x.severity === "error" ? fail : warn)("function_safety", x.at, x.rule, x.message);

  // limits
  const bytes = new TextEncoder().encode(JSON.stringify(spec)).length;
  if (bytes > DATAPACK_LIMITS.maxSpecBytes) fail("limits", "(root)", "spec_size", `the spec is ${bytes} bytes; the limit is ${DATAPACK_LIMITS.maxSpecBytes}`);

  if (errors.length) return { ok: false, errors, warnings, checks: checksOf(ran) };
  return { ok: true, spec, errors: [], warnings, checks: checksOf(ran), features: fe.features };
}

/** Canonical JSON (sorted keys), the hashing form of specs. */
export function canonicalJson(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(",")}]`;
  if (v && typeof v === "object") return `{${Object.keys(v as object).sort().filter((k) => (v as Record<string, unknown>)[k] !== undefined).map((k) => `${JSON.stringify(k)}:${canonicalJson((v as Record<string, unknown>)[k])}`).join(",")}}`;
  return JSON.stringify(v);
}

/** Does the pack contain registry content that /reload cannot load (needs a server restart)? */
export const needsRestart = (spec: DataPackSpec): boolean => spec.resources.some((r) => r.type === "enchantment");

// Spec -> data pack, per version. validate (fail closed) -> emit every resource through the per-version adapters ->
// pack.mcmeta from the registry's format -> static file check (mcdoc fields + value shapes + ids + function allowlist)
// -> deterministic zip (sorted entries, fixed timestamps; lib/cyrus/textures/zip.ts). Same spec + version = same bytes.
import { createHash } from "node:crypto";
import { zip } from "../../textures/zip";
import { canonicalJson, needsRestart, validateDataPackSpec, type DataPackSpec, type DpCheck, type DpIssue } from "../spec";
import { validatePackFiles, type FileReport } from "../validate";
import type { DataPackFeatures } from "../versions";
import { emitAdvancement } from "./advancement";
import { jsonText, type Json } from "./common";
import { emitEnchantment } from "./enchantment";
import { emitLootTable } from "./loot";
import { emitRecipe } from "./recipe";

export const EMITTER_VERSION = "dp-emit-1";

export type EmittedFile = { path: string; text: string };
export type BuiltDataPack = {
  name: string; version: string; namespace: string; spec: DataPackSpec; files: EmittedFile[]; zip: Buffer; sha1: string; sha256: string; bytes: number;
  format: { major: number; minor: number }; specSha256: string; counts: Record<string, number>;
  /** Enchantments are registry content: a server restart is needed; everything else loads with /reload. */
  apply: "reload" | "restart";
  checks: DpCheck[]; warnings: string[]; emitter: string;
};
export type BuildResult = { ok: true; pack: BuiltDataPack } | { ok: false; errors: string[]; issues: DpIssue[]; checks: DpCheck[]; fileReport?: FileReport };

export function mcmetaJson(description: string, fe: DataPackFeatures): Json {
  const { major, minor } = fe.format;
  return fe.mcmeta === "pack_format" ? { pack: { pack_format: major, description } } : { pack: { description, min_format: [major, minor], max_format: [major, minor] } };
}

/** The data pack files (no zip, no file check) of an ALREADY VALIDATED spec. */
export function emitFiles(spec: DataPackSpec, namespace: string, fe: DataPackFeatures): EmittedFile[] {
  const out: EmittedFile[] = [{ path: "pack.mcmeta", text: jsonText(mcmetaJson(spec.description, fe)) }];
  const tags = new Map<string, { replace: boolean; values: string[] }>();
  const tag = (path: string, values: string[], replace = false) => {
    const t = tags.get(path) ?? { replace: false, values: [] };
    t.replace = t.replace || replace;
    for (const v of values) if (!t.values.includes(v)) t.values.push(v);
    tags.set(path, t);
  };
  for (const r of spec.resources) {
    const base = `data/${namespace}`;
    switch (r.type) {
      case "recipe": out.push({ path: `${base}/recipe/${r.id}.json`, text: jsonText(emitRecipe(r.recipe, fe)) }); break;
      case "loot_table": out.push({ path: `${base}/loot_table/${r.id}.json`, text: jsonText(emitLootTable(r.table, fe, `${namespace}:${r.id}`)) }); break;
      case "advancement": out.push({ path: `${base}/advancement/${r.id}.json`, text: jsonText(emitAdvancement(r.advancement, fe)) }); break;
      case "enchantment": out.push({ path: `${base}/enchantment/${r.id}.json`, text: jsonText(emitEnchantment(r.enchantment, fe)) }); break;
      case "function":
        out.push({ path: `${base}/function/${r.id}.mcfunction`, text: [`# ${namespace}:${r.id} (generated by Cyrus from the "${spec.name}" data pack spec)`, ...r.commands.map((c) => c.trim())].join("\n") + "\n" });
        if (r.runOn) tag(`data/minecraft/tags/function/${r.runOn}.json`, [`${namespace}:${r.id}`]);
        break;
      case "tag": {
        const [tns, tpath] = r.id.startsWith("minecraft:") ? ["minecraft", r.id.slice(10)] : [namespace, r.id];
        tag(`data/${tns}/tags/${r.registry}/${tpath}.json`, r.values, r.replace === true && tns !== "minecraft");
        break;
      }
    }
  }
  for (const [path, t] of [...tags].sort((a, b) => (a[0] < b[0] ? -1 : 1))) out.push({ path, text: jsonText({ replace: t.replace, values: t.values }) });
  return out.sort((a, b) => (a.path < b.path ? -1 : 1));
}

const hash = (alg: "sha1" | "sha256", b: Buffer | string) => createHash(alg).update(b).digest("hex");

export function buildDataPack(input: unknown, ctx: { version: string; namespace: string }): BuildResult {
  const v = validateDataPackSpec(input, ctx);
  if (!v.ok) return { ok: false, errors: v.errors.map((e) => `${e.path}: ${e.message}`), issues: v.errors, checks: v.checks };
  const files = emitFiles(v.spec, ctx.namespace, v.features);
  const fileReport = validatePackFiles(files, ctx.version);
  const checks = [...v.checks, ...fileReport.checks.map((c) => ({ ...c, id: c.id === "vanilla_ids" ? "emitted_ids" : c.id === "function_safety" ? "emitted_functions" : c.id }))];
  if (!fileReport.ok) return { ok: false, errors: fileReport.errors.map((e) => `emitted: ${e}`), issues: [], checks, fileReport };
  const z = zip(files.map((f) => ({ path: f.path, data: Buffer.from(f.text, "utf8") })));
  const counts: Record<string, number> = {};
  for (const r of v.spec.resources) counts[r.type] = (counts[r.type] ?? 0) + 1;
  if (z.length > 1024 * 1024) return { ok: false, errors: [`the data pack is ${z.length} bytes; the limit is 1 MB`], issues: [], checks, fileReport };
  return {
    ok: true,
    pack: {
      name: v.spec.name, version: ctx.version, namespace: ctx.namespace, spec: v.spec, files, zip: z, sha1: hash("sha1", z), sha256: hash("sha256", z), bytes: z.length,
      format: v.features.format, specSha256: hash("sha256", canonicalJson(v.spec)), counts, apply: needsRestart(v.spec) ? "restart" : "reload",
      checks, warnings: [...v.warnings.map((w) => `${w.path}: ${w.message}`), ...fileReport.warnings], emitter: EMITTER_VERSION,
    },
  };
}
// Shared emit helpers: text components, ingredients, item stacks, number providers. Every version difference goes
// through DataPackFeatures (../versions.ts), never through ad-hoc version checks here.
import type { DataPackFeatures } from "../versions";
import type { DpIngredient, DpNum, DpResult, DpText } from "../spec";

export type Json = null | boolean | number | string | Json[] | { [k: string]: Json | undefined };

/** A styled run as a text component object (same shape in JSON files on every supported version). */
export function textComponent(t: DpText): Json {
  if (typeof t === "string") return { text: t };
  const o: { [k: string]: Json } = { text: t.text };
  if (t.color) o.color = t.color;
  for (const k of ["bold", "italic", "underlined", "strikethrough"] as const) if (t[k] !== undefined) o[k] = t[k]!;
  return o;
}

/** Text inside an ITEM COMPONENT (item_name, lore): a JSON string up to 1.21.4, an object from 1.21.5 (verified on the jars). */
export function componentText(t: DpText, fe: DataPackFeatures): Json {
  const c = textComponent(t);
  return fe.componentText === "json-string" ? JSON.stringify(c) : c;
}

const one = (r: string, fe: DataPackFeatures): Json => (fe.ingredient === "string" ? r : r.startsWith("#") ? { tag: r.slice(1) } : { item: r });

/** <=1.21.1: {"item": id} / {"tag": id} (a list = alternatives); >=1.21.2: "id" / "#tag" (a list = item ids). */
export function ingredient(x: DpIngredient, fe: DataPackFeatures): Json {
  return Array.isArray(x) ? x.map((r) => one(r, fe)) : one(x, fe);
}

/** An item stack template { id, count?, components? }. */
export function itemStack(r: DpResult, fe: DataPackFeatures, opts: { count?: boolean; components?: boolean } = {}): Json {
  const o: { [k: string]: Json } = { id: r.item };
  if (opts.count !== false && r.count !== undefined && r.count !== 1) o.count = r.count;
  if (opts.components !== false && (r.name || r.lore?.length)) {
    const comps: { [k: string]: Json } = {};
    if (r.name) comps["minecraft:item_name"] = componentText(r.name, fe);
    if (r.lore?.length) comps["minecraft:lore"] = r.lore.map((l) => componentText(l, fe));
    o.components = comps;
  }
  return o;
}

/** Number provider: a constant, uniform { min, max } or binomial { n, p }. */
export function numberProvider(n: DpNum): Json {
  if (typeof n === "number") return n;
  if ("min" in n) return { type: "minecraft:uniform", min: n.min, max: n.max };
  return { type: "minecraft:binomial", n: n.n, p: n.p };
}

/** Stable JSON text of an emitted file (2-space indent, trailing newline). */
export const jsonText = (j: Json): string => JSON.stringify(j, null, 2) + "\n";
import type { DataPackFeatures } from "../versions";
import type { DpEnchantment } from "../spec";
import { textComponent, type Json } from "./common";

const cost = (c: { base: number; perLevelAboveFirst: number }): Json => ({ base: c.base, per_level_above_first: c.perLevelAboveFirst });
const levelValue = (base: number, per?: number): Json => (per === undefined ? base : { type: "minecraft:linear", base, per_level_above_first: per });

/** The enchantment format of this subset is identical on 1.21.1 .. 26.2 (vanilla sharpness/unbreaking compared on every jar). */
export function emitEnchantment(e: DpEnchantment, _fe: DataPackFeatures): Json {
  const out: { [k: string]: Json } = { description: textComponent(e.description) };
  if (e.exclusiveSet) out.exclusive_set = e.exclusiveSet;
  out.supported_items = e.supportedItems;
  if (e.primaryItems) out.primary_items = e.primaryItems;
  Object.assign(out, { weight: e.weight, max_level: e.maxLevel, min_cost: cost(e.minCost), max_cost: cost(e.maxCost), anvil_cost: e.anvilCost, slots: e.slots });
  if (e.effects?.length) {
    const fx: { [k: string]: Json[] } = {};
    for (const x of e.effects) {
      const v = levelValue(x.base, x.perLevelAboveFirst);
      const effect = x.op === "multiply" ? { type: "minecraft:multiply", factor: v } : { type: `minecraft:${x.op}`, value: v };
      (fx[`minecraft:${x.component}`] ??= []).push({ effect });
    }
    out.effects = fx;
  }
  return out;
}
// Cyrus R2 data pack studio: does a BUILD get the data pack route? Pure + deterministic (no AI call; server side).
// The capability router's rules (adapter route rules with route "dataPack") read the request; worldgen alone never
// turns the route on (not built). OFF unless CYRUS_DATAPACK_STUDIO=1 (fail closed): off, nothing is decided, nothing
// is recorded and the build request stays byte-identical. Data packs are NOT plan-gated (owner decision for
// composition features): no plan lookup happens here.
import { getAdapter } from "../adapters";
import { routeSpec, type RouteDecision } from "../engine-core/router";
import type { ModSpec } from "../engine-core/spec";
import { dataPackFeatures } from "./versions";

export const DATAPACK_FLAG = "CYRUS_DATAPACK_STUDIO";
/** Adapter rule ids that mean "data-driven content the studio can build". `worldgen` is deliberately not here. */
export const DATAPACK_RULES = ["datapack_recipe", "datapack_loot", "datapack_advancement", "datapack_tag", "datapack_function", "datapack_enchantment", "datapack_content"] as const;

export const dataPackStudioOn = (env: Record<string, string | undefined> = process.env) => env[DATAPACK_FLAG] === "1";

export type DataPackRouteInput = {
  text: string;
  /** body.assets (a REQUEST only): ["datapack"] or { datapack: true }. */
  explicit?: unknown;
  /** The base build already ships data packs (a change keeps working on them). */
  existing?: boolean;
  mcVersion: string;
  game?: string;
  on: boolean;
};
export type DataPackRouteDecision = { route: boolean; matched: string[]; notices: string[]; limits: string[] };

const explicitDatapack = (raw: unknown) => (Array.isArray(raw) ? raw.includes("datapack") : !!raw && typeof raw === "object" && (raw as Record<string, unknown>).datapack === true);

/** Which data pack rules the adapter matches in this text (the router's own keyword rules, no AI). */
export function matchDataPackRules(text: string, game = "minecraft"): string[] {
  const adapter = getAdapter(game);
  if (!adapter || !text) return [];
  return adapter.routeRules.filter((r) => (DATAPACK_RULES as readonly string[]).includes(r.id) && r.keywords.some((k) => new RegExp(k, "i").test(text))).map((r) => r.id);
}

export function decideDataPackRoute(i: DataPackRouteInput): DataPackRouteDecision {
  const none: DataPackRouteDecision = { route: false, matched: [], notices: [], limits: [] };
  if (!i.on) return none; // switched off: decide nothing, record nothing
  const matched = matchDataPackRules(i.text, i.game);
  const wanted = matched.length > 0 || explicitDatapack(i.explicit) || !!i.existing;
  if (!wanted) return none;
  const fe = dataPackFeatures(i.mcVersion);
  if (!fe.ok) return { route: false, matched, notices: [`Data packs aren't available for Minecraft ${i.mcVersion} yet (${fe.error}), so Cyrus builds this as a plugin only.`], limits: [] };
  const adapter = getAdapter(i.game ?? "minecraft");
  const limits = (adapter?.routeRules ?? []).filter((r) => matched.includes(r.id) && r.limit).map((r) => r.limit!.message);
  return { route: true, matched, notices: [], limits };
}

/** Route a typed spec with the data pack route switched on where the host enabled it (wraps the engine router). */
export function routeWithDataPack(spec: ModSpec, opts: { prompt?: string; gate?: { plan: unknown }; env?: Record<string, string | undefined> } = {}): RouteDecision | null {
  const adapter = getAdapter(spec.game);
  if (!adapter) return null;
  return routeSpec(spec, adapter, { prompt: opts.prompt, gate: opts.gate, routesOn: dataPackStudioOn(opts.env) ? ["dataPack"] : [] });
}

/** Does a stored build result carry data packs (ModBuild.result.assets.datapacks, written by the asset sync)? */
export function hasDatapacks(result: unknown): boolean {
  const a = (result as { assets?: { datapacks?: unknown[] } } | null)?.assets;
  return Array.isArray(a?.datapacks) && a!.datapacks!.length > 0;
}
// Cyrus R2 data pack studio: DELIVERY of a built data pack to a server's world (pure planning + one flagged action).
//
// Where: `<server>/<level-name>/datapacks/nxeon-<namespace>-<name>.zip` (one file per pack; the prefix makes Nxeon's
// packs recognisable and the namespace keeps two mods apart). How: through the existing installer abstraction
// (lib/cyrus/modpack/install.ts `MemberPlacer`; in production `engineMemberPlacer`, the shared Mods engine, so the
// engine's state file knows the file) with staged writes. Then the reload rule (VERIFIED on Paper 1.21.1 .. 26.2 with
// Test Flight: `datapack disable` / `datapack enable` reloads recipes, loot tables, advancements, tags and
// functions without a restart):
//   apply "reload"  -> run `minecraft:reload` once over the console (never Bukkit's /reload, which reloads plugins)
//   apply "restart" -> the pack adds registry content (enchantments): only a restart loads it; mark restart-required
// Bytes: the emitter is deterministic, so the zip is rebuilt from the spec stored on the CyrusProjectAsset row and
// must hash to the recorded sha256 (no blob storage, nothing public).
// OFF unless CYRUS_DATAPACK_DELIVERY_REAL=1: off, it returns before touching anything (fail closed).
import type { MemberPlacer, PlacedFile } from "../modpack/install";
import { targetPath } from "../modpack/install";
import { buildDataPack } from "./emit";

export const DATAPACK_DELIVERY_FLAG = "CYRUS_DATAPACK_DELIVERY_REAL";
export const RELOAD_COMMAND = "minecraft:reload";

export type DeliveryPlan = { file: string; relPath: string; apply: "reload" | "restart"; commands: string[]; notes: string[] };

export function planDataPackDelivery(p: { namespace: string; name: string; apply: "reload" | "restart" }): DeliveryPlan {
  const file = `nxeon-${p.namespace}-${p.name}.zip`;
  return {
    file, relPath: `datapacks/${file}`, apply: p.apply,
    commands: p.apply === "reload" ? [RELOAD_COMMAND] : [],
    notes: p.apply === "restart"
      ? ["This data pack adds enchantments (registry content), which only load when the server starts: restart the server once."]
      : ["Recipes, loot tables, advancements, tags and functions load with minecraft:reload; no restart is needed."],
  };
}

/** Rebuild the zip from a stored asset's provenance and prove it is the same bytes that were checked at build time. */
export function rebuildForDelivery(prov: { spec?: unknown; version?: unknown; packSha256?: unknown }, namespace: string): { ok: true; zip: Buffer; sha256: string; apply: "reload" | "restart"; name: string } | { ok: false; error: string } {
  if (typeof prov.version !== "string" || typeof prov.packSha256 !== "string") return { ok: false, error: "the asset has no recorded version or pack hash" };
  const b = buildDataPack(prov.spec, { version: prov.version, namespace });
  if (!b.ok) return { ok: false, error: `the stored spec no longer builds: ${b.errors[0] ?? "?"}` };
  if (b.pack.sha256 !== prov.packSha256) return { ok: false, error: `rebuilt pack ${b.pack.sha256.slice(0, 12)} differs from the recorded ${prov.packSha256.slice(0, 12)} (emitter changed?)` };
  return { ok: true, zip: b.pack.zip, sha256: b.pack.sha256, apply: b.pack.apply, name: b.pack.name };
}

export type DeliveryInput = { projectId: string; revisionId: string; namespace: string; name: string; version: string; zip: Buffer; sha256: string; apply: "reload" | "restart" };
export type DeliveryResult =
  | { ok: true; placed: string; plan: DeliveryPlan; restartRequired: boolean }
  | { ok: false; skipped: true; reason: string }
  | { ok: false; skipped?: false; error: string };

/**
 * Place one data pack on a server. `runConsole` sends ONE console command (the host's RCON/console seam); absent, the
 * reload is left to the caller (reported in plan.commands). Never deletes other packs; a new version of the same pack
 * replaces its own file only.
 */
export async function deliverDataPack(
  input: DeliveryInput,
  deps: { placer: MemberPlacer; base?: string; level?: string; runConsole?: (cmd: string) => Promise<void>; env?: Record<string, string | undefined> },
): Promise<DeliveryResult> {
  const env = deps.env ?? process.env;
  if (env[DATAPACK_DELIVERY_FLAG] !== "1") return { ok: false, skipped: true, reason: `data pack delivery is switched off (${DATAPACK_DELIVERY_FLAG} is not 1); nothing was changed` };
  if (deps.placer.disabledReason) return { ok: false, skipped: true, reason: deps.placer.disabledReason };
  const plan = planDataPackDelivery({ namespace: input.namespace, name: input.name, apply: input.apply });
  const target = targetPath(plan.relPath, deps.base ?? "/opt/mc", deps.level ?? "world");
  const file: PlacedFile = { target, data: input.zip, sha256: input.sha256, role: "datapack" };
  try {
    await deps.placer.place({ member: { id: `dp-${input.name}`.slice(0, 64), kind: "datapack", origin: "cyrus", label: `${input.name} (Cyrus data pack)`, version: input.sha256.slice(0, 12), project: { projectId: input.projectId, revisionId: input.revisionId, namespace: input.namespace } }, files: [file] });
  } catch (e) { return { ok: false, error: `placing ${plan.file} failed: ${(e as Error).message}` }; }
  if (plan.apply === "reload" && deps.runConsole) {
    try { await deps.runConsole(RELOAD_COMMAND); } catch (e) { return { ok: false, error: `${plan.file} is placed but ${RELOAD_COMMAND} failed: ${(e as Error).message}; it loads on the next restart` }; }
  }
  return { ok: true, placed: target, plan, restartRequired: plan.apply === "restart" };
}
// Cyrus R2 data pack studio, PORTAL side of a succeeded build: the service's data pack specs are never trusted.
// Each returned spec is validated and emitted AGAIN here with the TypeScript emitter for the build's exact version;
// a spec that fails is dropped with a reason (never shipped). The zip is deterministic, so the portal does not need
// to store it: delivery rebuilds it from the spec kept in the CyrusProjectAsset row and checks the recorded sha256.
import { buildDataPack, type BuiltDataPack } from "./emit";
import { canonicalJson, type DataPackSpec } from "./spec";

export const DATAPACK_SPEC_MIME = "application/vnd.nxeon.datapack-spec+json";
export type SvcDatapack = { name: string; path: string; sha256: string; spec: unknown; pack?: { sha256?: string } | null };
export type CheckedDatapack = { name: string; spec: DataPackSpec; canonical: string; specSha256: string; pack: BuiltDataPack; serviceAgreed: boolean };

export function checkReturnedDatapacks(list: SvcDatapack[] | undefined, ctx: { namespace: string; mcVersion: string }): { ok: CheckedDatapack[]; dropped: { name: string; reason: string }[]; notices: string[] } {
  const ok: CheckedDatapack[] = [], dropped: { name: string; reason: string }[] = [], notices: string[] = [];
  const owners = new Map<string, string>();
  for (const d of (list ?? []).slice(0, 4)) {
    const name = typeof d?.name === "string" ? d.name.slice(0, 40) : "?";
    const b = buildDataPack(d?.spec, { version: ctx.mcVersion, namespace: ctx.namespace });
    if (!b.ok) { dropped.push({ name, reason: b.errors[0] ?? "failed the data pack checks" }); notices.push(`Data pack "${name}" was left out: it did not pass Nxeon's data pack checks for Minecraft ${ctx.mcVersion}.`); continue; }
    if (b.pack.name !== name || ok.some((x) => x.name === name)) { dropped.push({ name, reason: "name mismatch or duplicate" }); continue; }
    const spec = b.pack.spec;
    const clash = spec.resources.map((r) => (r.type === "tag" ? `tag/${r.registry}:${r.id}` : `${r.type}:${r.id}`)).find((k) => owners.has(k) && !/^tag\/[a-z_]+:minecraft:/.test(k));
    if (clash) { dropped.push({ name, reason: `${clash} is also defined in ${owners.get(clash)}` }); notices.push(`Data pack "${name}" was left out: it defines ${clash} a second time.`); continue; }
    for (const r of spec.resources) owners.set(r.type === "tag" ? `tag/${r.registry}:${r.id}` : `${r.type}:${r.id}`, name);
    const canonical = canonicalJson(spec);
    ok.push({ name, spec, canonical, specSha256: b.pack.specSha256, pack: b.pack, serviceAgreed: !d.pack?.sha256 || d.pack.sha256 === b.pack.sha256 });
  }
  return { ok, dropped, notices };
}
