/** RAW broken pack: JSON that is valid on 1.21.1 but not on 1.21.2+, a loot function that does not exist, an unknown item. */
function brokenFiles(version: string): PackFile[] {
  const fmt = version === "1.21.11" ? { min: [94, 1] } : version === "26.2" ? { min: [107, 1] } : null;
  const mcmeta = fmt ? { pack: { description: "raw broken pack", min_format: fmt.min, max_format: fmt.min } } : { pack: { pack_format: 61, description: "raw broken pack" } };
  return [
    { path: "pack.mcmeta", text: JSON.stringify(mcmeta) },
    { path: "data/nx_broken01/recipe/old_style.json", text: JSON.stringify({ type: "minecraft:crafting_shapeless", ingredients: [{ item: "minecraft:stick" }], result: { id: "minecraft:ladder" } }) },
    { path: "data/nx_broken01/loot_table/bad_fn.json", text: JSON.stringify({ pools: [{ rolls: 1, entries: [{ type: "minecraft:item", name: "minecraft:diamond", functions: [{ function: "minecraft:set_countt", count: 2 }] }] }] }) },
    { path: "data/nx_broken01/recipe/no_item.json", text: JSON.stringify({ type: "minecraft:crafting_shapeless", ingredients: ["minecraft:stick"], result: { id: "minecraft:rubyy" } }) },
    { path: "data/nx_broken01/function/ok.mcfunction", text: "say hi\n" },
  ];
}

async function main() {
  const which = process.argv[2] ?? "all";
  const vi = process.argv.indexOf("--versions");
  const versions = vi > 0 ? process.argv[vi + 1].split(",") : ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"];
  const oi = process.argv.indexOf("--out");
  const work = mkdtempSync(path.join(tmpdir(), "cyrus-dp-real-"));
  const spec = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-datapack/showcase.json"), "utf8"));
  const out: unknown[] = [];
  try {
    if (which === "all" || which === "showcase") for (const v of versions) {
      const b = buildDataPack(spec, { version: v, namespace: NS });
      if (!b.ok) { out.push({ flight: "showcase", version: v, error: b.errors }); console.log(`showcase ${v}: build refused: ${b.errors.join("; ")}`); continue; }
      const file = path.join(work, `cyrus_showcase-${v}.zip`);
      writeFileSync(file, b.pack.zip);
      const r = await fly({ version: v, datapacks: [{ name: "cyrus_showcase", localPath: file }], rcon: SHOWCASE_RCON, keepDir: true }, `showcase ${v}`);
      const log = harvestLog(r.report.runId);
      const vanilla = { recipes: vanillaIds("recipe", v).size, advancements: vanillaIds("advancement", v).size };
      const ours = { recipes: b.pack.counts.recipe ?? 0, advancements: b.pack.counts.advancement ?? 0 };
      const counts = { log, vanilla, ours, recipesMatch: log.recipes === vanilla.recipes + ours.recipes, advancementsMatch: log.advancements === vanilla.advancements + ours.advancements };
      console.log(`showcase ${v}: ${describeSummary(r.summary)} | recipes ${log.recipes} = ${vanilla.recipes}+${ours.recipes}? ${counts.recipesMatch} | advancements ${log.advancements} = ${vanilla.advancements}+${ours.advancements}? ${counts.advancementsMatch}`);
      out.push({
        flight: "showcase", version: v, packSha256: b.pack.sha256, packBytes: b.pack.bytes, format: b.pack.format, status: r.report.status, overall: r.summary.overall, success: r.summary.success,
        bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, runId: r.report.runId, paper: r.report.engine?.paper, jdk: r.report.engine?.jdk?.version, counts,
        checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 30) })),
      });
    }
    if (which === "all" || which === "broken") for (const v of versions.filter((x) => x === "1.21.11" || x === "26.2")) {
      const files = brokenFiles(v);
      const stat = validatePackFiles(files, v);
      const file = path.join(work, `cyrus_broken-${v}.zip`);
      writeFileSync(file, zip(files.map((f) => ({ path: f.path, data: Buffer.from(f.text) }))));
      const r = await fly({ version: v, datapacks: [{ name: "cyrus_broken", localPath: file }], rcon: [{ id: "ok-function", command: "function nx_broken01:ok", required: false }] }, `broken ${v}`);
      const logCheck = r.report.checks.find((c) => c.id === "startup_log_clean");
      console.log(`broken ${v}: validator ok=${stat.ok} (${stat.errors.length} errors); server ${describeSummary(r.summary)}; log ${logCheck?.status}`);
      out.push({
        flight: "broken-raw", version: v, validator: { ok: stat.ok, errors: stat.errors }, status: r.report.status, overall: r.summary.overall, runId: r.report.runId,
        agree: !stat.ok && logCheck?.status === "fail",
        checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 30) })),
      });
    }
  } finally { rmSync(work, { recursive: true, force: true }); }
  const text = JSON.stringify(out, null, 1);
  if (oi > 0) writeFileSync(process.argv[oi + 1], text); else console.log(text);
}
main().catch((e) => { console.error(e); process.exit(1); });

// Cyrus Test Flight (R0) types: the typed spec a caller writes, the resolved spec the node-2 runner receives,
// and the report it returns. The runner is services/modbuilder/tools/testflight/runner.js (plain Node on node-2).
// A check passes only if it actually ran; a skipped required check means the flight is NOT a success.

export const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "clean_stop", "no_leaks"] as const;
export type CheckId = (typeof CHECK_IDS)[number];
export type CheckStatus = "pass" | "fail" | "not_run";

/** A regex matched against each log line (JS syntax; flags limited to i/m/s/u). */
export type LogMatcher = { id: string; pattern: string; flags?: string };

/** A small text file in the server directory (e.g. a plugin's config). Path relative to the server root, under plugins/ only. */
export type ServerFile = { path: string; content: string };

export type SeedRef = { from: string; to: string };

export type RconCheck = {
  id?: string;
  /** Written (created or replaced) in the server dir right before this command is sent, e.g. to test a config reload. */
  writeFile?: ServerFile;
  /** Wait this long (ms, max 30000) before sending the command (after writeFile), e.g. for a file watcher. */
  waitMs?: number;
  /** One console command without the leading slash. stop/restart/op/deop/reload are reserved for the runner. */
  command: string;
  /** Every substring must appear in the reply (colour codes stripped). Empty = the command only has to answer. */
  expect?: string[];
  /** None of these may appear. */
  expectNot?: string[];
  /** Default true. An optional check is reported but does not fail the stage. */
  required?: boolean;
};

/** An artifact either on the caller's disk (uploaded by the invoker) or already on node-2 under the Test Flight root. */
export type ArtifactRef = { localPath: string; remotePath?: never; sha256?: string } | { remotePath: string; localPath?: never; sha256?: string };

export type TestFlightSpec = {
  /** Exact registry id, e.g. "26.2" or "1.21.11". The registry supplies the JDK and the pinned Paper server jar. */
  version: string;
  plugins?: ArtifactRef[];
  /** Datapacks go into world/datapacks before first boot; each one adds an automatic `datapack list enabled` check. */
  datapacks?: (ArtifactRef & { name: string })[];
  /** Written to server.properties only. No client connects, so the pack itself is NOT exercised (reported as such). */
  resourcePack?: { url: string; sha1?: string; id?: string; required?: boolean };
  /** Small text files placed before the first boot (max 16, 64 KB each, under plugins/). */
  files?: ServerFile[];
  /**
   * Read-only directories prepared on node-2 under `<root>/seeds/<from>` copied into the server dir before boot
   * (`to` = "libraries" or a path under plugins/). The flight has no internet, so a managed plugin's pinned runtime
   * libraries are seeded this way (runner tf-lite-2).
   */
  seeds?: SeedRef[];
  /** Server-dir files copied out after the stop to `<root>/collect/<runId>/` (a path ending in "/" = a listing). */
  collect?: string[];
  rcon?: RconCheck[];
  /** Replace the runner's default startup-log matchers (omit to use the defaults). */
  logMatchers?: LogMatcher[];
  /** Extra ignore patterns, added to the runner's sandbox ignores. */
  logIgnore?: LogMatcher[];
  timeouts?: { bootSec?: number; rconSec?: number; stopSec?: number; totalSec?: number };
  /** xmxMb max 1024 (node-2 rule). rssCapMb is a watchdog: above it the server is killed and the run fails. */
  memory?: { xmxMb?: number; rssCapMb?: number };
  /** Extra stages to treat as required even if the spec would not make them required. */
  requireStages?: CheckId[];
  /** Keep the server dir on node-2 for debugging (default false). */
  keepDir?: boolean;
};

/** What the runner receives: registry pins resolved, artifact paths on node-2. */
export type ResolvedSpec = {
  schema: 1;
  runId: string;
  version: string;
  javaRelease: 21 | 25;
  paper: { build: number; sha256: string };
  plugins: { path: string; sha256?: string }[];
  datapacks: { path: string; name: string }[];
  resourcePack?: TestFlightSpec["resourcePack"];
  files?: ServerFile[];
  seeds?: SeedRef[];
  collect?: string[];
  rcon: RconCheck[];
  logMatchers?: LogMatcher[];
  logIgnore?: LogMatcher[];
  timeouts: { bootSec: number; rconSec: number; stopSec: number; totalSec: number };
  memory: { xmxMb: number; rssCapMb: number };
  keepDir: boolean;
};

export type CheckResult = { id: CheckId; status: CheckStatus; required: boolean; evidence: string[]; durationMs: number };

export type ReportArtifact =
