#!/usr/bin/env python3
"""Derive the committed data of the Cyrus data pack studio (lib/cyrus/datapack/data/) on the BUILD HOST (node-2).

  python3 datapack-derive.py ids    <gen-dir>  > vanilla-ids.json     (ids ONLY, from Mojang's data generator)
  python3 datapack-derive.py mcdoc  <mcdoc-dir> > mcdoc-subset.json   (field tables, from vanilla-mcdoc, MIT)

ids: <gen-dir>/<version>/out is `java -DbundlerMainClass=net.minecraft.data.Main -jar <vanilla server jar> --reports
--server --output out` for each registry version (the jar Paper's paperclip downloaded and checked; sha256s below).
Only identifier names are kept (registries.json keys, vanilla data file names, command names): no assets, no content.
Grouped by a bitmask over VERSIONS (bit i = present in VERSIONS[i]): {kind: {mask: [names]}}.

mcdoc: a deliberately small parser for the subset the emitters write: `dispatch minecraft:<registry>[keys] to struct`
and named `struct X { ... }` bodies -> top-level fields with optional flag and #[since]/#[until] (since inclusive,
until exclusive, as in mcdoc) plus spreads of named structs (resolved by the TypeScript side per version).
"""
import glob, hashlib, json, os, re, subprocess, sys

TF = "/tank/nxeon-build/tmp/testflight"

VERSIONS = ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"]
REGISTRIES = ["item", "block", "entity_type", "loot_function_type", "loot_condition_type", "loot_pool_entry_type",
              "loot_number_provider_type", "trigger_type", "recipe_serializer", "recipe_type",
              "enchantment_effect_component_type", "enchantment_value_effect_type", "mob_effect", "attribute"]
DATA_DIRS = {"enchantment": "enchantment", "loot_table": "loot_table", "advancement": "advancement", "recipe": "recipe",
             "tag/item": "tags/item", "tag/block": "tags/block", "tag/entity_type": "tags/entity_type",
             "tag/enchantment": "tags/enchantment"}

def strip_ns(i):
    return i[10:] if i.startswith("minecraft:") else i

def group(m):
    """{name: mask} -> {mask: [names]} (mask as a decimal string; most ids are in every version)."""
    g = {}
    for name, mask in sorted(m.items()):
        g.setdefault(str(mask), []).append(name)
    return dict(sorted(g.items(), key=lambda kv: -len(kv[1])))

def ids(gen):
    out = {}
    def add(kind, name, bit):
        out.setdefault(kind, {})
        out[kind][name] = out[kind].get(name, 0) | (1 << bit)
    for bit, v in enumerate(VERSIONS):
        root = os.path.join(gen, v, "out")
        regs = json.load(open(os.path.join(root, "reports", "registries.json")))
        for r in REGISTRIES:
            for e in regs.get("minecraft:" + r, {}).get("entries", {}):
                add(r, strip_ns(e), bit)
        for kind, d in DATA_DIRS.items():
            base = os.path.join(root, "data", "minecraft", d)
            for f in glob.glob(base + "/**/*.json", recursive=True):
                add(kind, os.path.relpath(f, base)[:-5].replace(os.sep, "/"), bit)
        cmds = json.load(open(os.path.join(root, "reports", "commands.json")))
        for name, node in cmds.get("children", {}).items():
            add("command", name, bit)
            if name in ("execute", "gamerule"):
                for sub in node.get("children", {}):
                    add("execute_sub" if name == "execute" else "gamerule", sub, bit)
    jars = {}
    for v in VERSIONS:
        for j in sorted(glob.glob(f"{TF}/paper/*/cache/mojang_{v}.jar")):
            jars[v] = {"vanillaServerJarSha256": hashlib.sha256(open(j, "rb").read()).hexdigest(), "paperServerSha256": j.split("/")[-3]}
    return {"source": {"what": "identifier names only (registries.json keys, vanilla data file names, command names) from Mojang's data generator (--reports --server); no assets or content", "jars": jars},
            "versions": VERSIONS, "ids": {k: group(v) for k, v in sorted(out.items())}}

# ----------------------------------------------------------------------------------------------------------------
ROOTS = {
    "recipe_serializer": ["crafting_shaped", "crafting_shapeless", "smelting", "blasting", "smoking", "campfire_cooking", "stonecutting", "smithing_transform"],
    "loot_function": ["set_count", "set_damage", "enchant_randomly", "enchant_with_levels", "set_name", "set_lore", "set_enchantments", "explosion_decay", "furnace_smelt", "enchanted_count_increase"],
    "loot_condition": ["random_chance", "killed_by_player", "survives_explosion", "match_tool", "weather_check", "random_chance_with_enchanted_bonus", "inverted"],
    "loot_pool_entry": ["item", "tag", "loot_table", "empty"],
    "trigger": ["impossible", "tick", "inventory_changed", "consume_item", "player_killed_entity", "recipe_unlocked", "recipe_crafted"],
    "resource": ["loot_table", "advancement", "enchantment", "recipe"],
}
STRUCTS = ["OldEntityPredicate", "RootAdvancementDisplay", "Pack", "PackBase", "LootPool", "LootPoolEntry", "AdvancementDisplay", "AdvancementIcon", "AdvancementCriterion", "AdvancementRewards", "EnchantmentCost"]

def clean(src):
    src = re.sub(r"//[^\n]*", "", src)
    return src

def match_close(s, i, o, c):
    d = 0
    while i < len(s):
        if s[i] == o: d += 1
        elif s[i] == c:
            d -= 1
            if d == 0: return i
        elif s[i] == '"':
            j = s.index('"', i + 1); i = j
        i += 1
    raise ValueError("unbalanced")

ATTR = re.compile(r'#\[([a-z_]+)(?:=("[^"]*"|\([^)]*\)))?\]')

def take_attrs(s):
    """leading #[..] attributes -> (dict, rest)"""
    attrs = {}
    s = s.lstrip()
    while s.startswith("#["):
        j = match_close(s, 1, "[", "]")
        m = ATTR.match(s[: j + 1])
        if m and m.group(2) and m.group(2).startswith('"'): attrs[m.group(1)] = m.group(2).strip('"')
        elif m: attrs[m.group(1)] = True
        s = s[j + 1 :].lstrip()
    return attrs, s

def split_members(body):
    parts, d, cur, i = [], 0, "", 0
    while i < len(body):
        ch = body[i]
        if ch == '"':
            j = body.index('"', i + 1); cur += body[i : j + 1]; i = j + 1; continue
        if ch in "{([": d += 1
        elif ch in "})]": d -= 1
        if ch == "," and d == 0:
            parts.append(cur); cur = ""
        else: cur += ch
        i += 1
    if cur.strip(): parts.append(cur)
    return [p.strip() for p in parts if p.strip()]

def ver(attrs):
    return {k: attrs[k] for k in ("since", "until") if isinstance(attrs.get(k), str)}

def parse_body(body, inline):
    fields = []
    for m in split_members(body):
        attrs, rest = take_attrs(m)
        v = ver(attrs)
        if rest.startswith("..."):
            ref = rest[3:].strip()
            if ref.startswith("struct"):
                b = ref.index("{"); e = match_close(ref, b, "{", "}")
                fields.append({"spread": parse_body(ref[b + 1 : e], inline), **v})
            elif re.match(r"^[A-Z][A-Za-z0-9_]*$", ref): fields.append({"spread": ref, **v})
            elif "::" in ref and re.match(r"^[a-z_:]*[A-Z][A-Za-z0-9_]*$", ref): fields.append({"spread": ref.split("::")[-1], **v})
            else: fields.append({"dynamic": ref[:80], **v})
            continue
        fm = re.match(r'^("?)([a-z0-9_]+)\1(\?)?\s*:\s*(.*)$', rest, re.S)
        if fm:
            typ = fm.group(4)
            for sm in re.finditer(r"struct ([A-Z][A-Za-z0-9_]*)\s*\{", typ):
                b = sm.end() - 1; e = match_close(typ, b, "{", "}")
                inline[sm.group(1)] = parse_body(typ[b + 1 : e], inline)
            fields.append({"n": fm.group(2), **({"opt": True} if fm.group(3) else {}), **v})
        elif rest.startswith("["):
            fields.append({"n": "*", "opt": True, **v})
    return fields

def mcdoc(root):
# Build host config — sourced by scripts/lib/buildhost.sh, scripts/devhost and
# scripts/buildhost/provision.sh (all run on the PRIMARY). See /root/agent-notes/BUILD-HOST.md
# and docs/DOCUMENTATION.md "Build host (node-2)".
: "${BUILD_HOST:=root@178.63.94.114}"          # node-2 / nxeon-fsn1 (Hetzner FSN1)
: "${BUILD_HOST_NAME:=nxeon-fsn1}"            # its hostname, asserted before every build
: "${BH_TOOL:=/opt/nxeon-build}"              # toolchain + scripts on node-2
: "${BH_ROOT:=/tank/nxeon-build}"             # mirror.git, wt/, npm-cache, pg-agents, logs
: "${BH_DEPLOY_ROOT:=/tank/nxeon-deploy}"     # <env>/build release build trees on node-2
: "${BH_MIRROR:=$BH_ROOT/mirror.git}"
: "${BH_SSH_OPTS:=-o BatchMode=yes -o ConnectTimeout=15 -o ServerAliveInterval=20 -o ServerAliveCountMax=6}"
bh_ssh() { # shellcheck disable=SC2086
  ssh $BH_SSH_OPTS "$BUILD_HOST" "$@"; }

