def mcdoc(root):
    disp, structs = {}, {}
    files = sorted(glob.glob(os.path.join(root, "java", "**", "*.mcdoc"), recursive=True))
    for f in files:
        s = clean(open(f, encoding="utf-8").read())
        for m in re.finditer(r"((?:#\[[^\]]*\]\s*)*)dispatch minecraft:([a-z_]+)\[([^\]]+)\] to ", s):
            reg, keys = m.group(2), [k.strip() for k in m.group(3).split(",")]
            dattrs, _ = take_attrs(m.group(1))
            rest = s[m.end():]
            pre, rest = take_attrs(rest)
            alts = []
            if rest.startswith("struct") or rest.startswith("("):
                if rest.startswith("("):
                    e = match_close(rest, 0, "(", ")")
                    for alt in split_members(rest[1:e].replace("|", ",")):
                        a, r2 = take_attrs(alt)
                        if r2.startswith("struct"):
                            b = r2.index("{"); ee = match_close(r2, b, "{", "}")
                            alts.append({**ver(a), "fields": parse_body(r2[b + 1 : ee], structs)})
                else:
                    b = rest.index("{"); e = match_close(rest, b, "{", "}")
                    alts.append({**ver(pre), "fields": parse_body(rest[b + 1 : e], structs)})
            else:
                mm = re.match(r"((?:::)?[A-Za-z0-9_:]+)", rest)
                if not mm: continue
                alts.append({**ver(pre), "fields": [{"spread": mm.group(1).split("::")[-1]}]})
            for k in keys:
                if k in ROOTS.get(reg, []):
                    disp[f"{reg}/{k}"] = {**ver(dattrs), "alts": alts}
        for m in re.finditer(r"struct ([A-Z][A-Za-z0-9_]*)\s*\{", s):
            b = m.end() - 1; e = match_close(s, b, "{", "}")
            if m.group(1) not in structs: structs[m.group(1)] = parse_body(s[b + 1 : e], structs)
        # trigger conditions: `type X = AllOptional<struct { ... }>` (every field optional) / `type X = struct { ... }`
        # (for triggers these are the fields of the criterion's `conditions` object)
        for m in re.finditer(r"type ([A-Z][A-Za-z0-9_]*) = (AllOptional<|ParitalRequired<)?struct\s*\{", s):
            b = m.end() - 1; e = match_close(s, b, "{", "}")
            fields = parse_body(s[b + 1 : e], structs)
            if m.group(2) == "AllOptional<":
                fields = [{**x, "opt": True} if "n" in x else x for x in fields]
            if m.group(1) not in structs: structs[m.group(1)] = fields
        for m in re.finditer(r"type ([A-Z][A-Za-z0-9_]*) = (?:AllOptional|ParitalRequired)<([A-Z][A-Za-z0-9_]*)>", s):
            if m.group(1) not in structs: structs[m.group(1)] = [{"spread": m.group(2)}]
    # keep only what is reachable from the roots
    need, seen = list(STRUCTS), set()
    def walk(fields):
        for x in fields:
            if isinstance(x.get("spread"), str): need.append(x["spread"])
            elif isinstance(x.get("spread"), list): walk(x["spread"])
    for d in disp.values():
        for a in d["alts"]: walk(a["fields"])
    while need:
        n = need.pop()
        if n in seen or n not in structs: continue
        seen.add(n); walk(structs[n])
    commit = subprocess.run(["git", "-C", root, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    lic = open(os.path.join(root, "LICENSE"), encoding="utf-8").read().splitlines()
    return {"source": {"repo": "https://github.com/SpyglassMC/vanilla-mcdoc", "commit": commit, "license": "MIT", "copyright": next((l for l in lic if l.startswith("Copyright")), ""),
                       "what": "top-level field names, optional flags and since/until of the structs the Cyrus emitters write; derived by scripts/cyrus/datapack-derive.py"},
            "dispatch": dict(sorted(disp.items())), "structs": {k: structs[k] for k in sorted(seen)}}

if __name__ == "__main__":
    mode, arg = sys.argv[1], sys.argv[2]
    data = ids(arg) if mode == "ids" else mcdoc(arg)
    json.dump(data, sys.stdout, separators=(",", ":"), sort_keys=False)
    sys.stdout.write("\n")
