// Generated files of the Cyrus data pack studio (committed, so the build service needs no esbuild or zod at runtime;
// test/cyrus-datapack.test.ts rebuilds them in memory and fails when one is stale):
//   services/modbuilder/datapack-spec.js        the build service's validator + emitter, bundled from lib/cyrus/datapack
//   lib/cyrus/datapack/datapack.v1.schema.json  the portable DataPackSpec contract (JSON Schema)
//   npx tsx scripts/cyrus/build-datapack-artifacts.ts [--check] [--out-dir DIR]   (DIR: write there instead of the repo, e.g. on a build host)
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { dataPackJsonSchema } from "../../lib/cyrus/datapack/spec";

const ROOT = path.join(__dirname, "../..");

export async function datapackArtifacts(): Promise<Record<string, string>> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({
    entryPoints: [path.join(ROOT, "lib/cyrus/datapack/service-entry.ts")], bundle: true, platform: "node", format: "cjs", target: "node20", write: false,
    minify: true, keepNames: true, legalComments: "none", banner: { js: `"use strict";\n// GENERATED by scripts/cyrus/build-datapack-artifacts.ts from lib/cyrus/datapack/*.ts (+ zod, the version registry and the derived data files). Do not edit.` },
  });
  return {
    "services/modbuilder/datapack-spec.js": r.outputFiles[0].text,
    "lib/cyrus/datapack/datapack.v1.schema.json": JSON.stringify(dataPackJsonSchema(), null, 1) + "\n",
  };
}

if (require.main === module) {
  datapackArtifacts().then((files) => {
    let stale = 0;
    const oi = process.argv.indexOf("--out-dir");
    for (const [rel, text] of Object.entries(files)) {
      const abs = oi > 0 ? path.join(process.argv[oi + 1], path.basename(rel)) : path.join(ROOT, rel);
      if (process.argv.includes("--check")) {
        let cur = ""; try { cur = readFileSync(abs, "utf8"); } catch { /* missing */ }
        if (cur !== text) { stale++; console.error(`stale: ${rel}`); }
      } else { writeFileSync(abs, text); console.log(`wrote ${rel} (${Buffer.byteLength(text)} bytes)`); }
    }
    if (stale) { console.error("run: npx tsx scripts/cyrus/build-datapack-artifacts.ts"); process.exit(1); }
  }).catch((e) => { console.error(e); process.exit(1); });
}

import { deflateRawSync } from "node:zlib";
import { crc32 } from "./png";

/** A minimal, deterministic ZIP writer (fixed timestamps, sorted entries, deflate) so the same pack always hashes the same. */
export function zip(files: { path: string; data: Buffer }[]): Buffer {
  const sorted = [...files].sort((a, b) => (a.path < b.path ? -1 : 1));
  const parts: Buffer[] = []; const central: Buffer[] = []; let offset = 0;
  const DOS_TIME = 0, DOS_DATE = (1 << 5) | 1; // 1980-01-01 00:00
  for (const f of sorted) {
    const name = Buffer.from(f.path, "utf8"); const comp = deflateRawSync(f.data, { level: 9 }); const crc = crc32(f.data);
    const lh = Buffer.alloc(30); lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6); lh.writeUInt16LE(8, 8); lh.writeUInt16LE(DOS_TIME, 10); lh.writeUInt16LE(DOS_DATE, 12);
    lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(comp.length, 18); lh.writeUInt32LE(f.data.length, 22); lh.writeUInt16LE(name.length, 26);
    parts.push(lh, name, comp);
    const ch = Buffer.alloc(46); ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(8, 10); ch.writeUInt16LE(DOS_TIME, 12); ch.writeUInt16LE(DOS_DATE, 14);
    ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(comp.length, 20); ch.writeUInt32LE(f.data.length, 24); ch.writeUInt16LE(name.length, 28); ch.writeUInt32LE(offset, 42);
    central.push(ch, name);
    offset += lh.length + name.length + comp.length;
  }
  const cd = Buffer.concat(central);
  const end = Buffer.alloc(22); end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(sorted.length, 8); end.writeUInt16LE(sorted.length, 10); end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(offset, 16);
  return Buffer.concat([...parts, cd, end]);
}
