// Cyrus R4 worldgen: a small, DETERMINISTIC NBT writer (Java edition, big-endian) + a reference reader.
//
// The AI never writes NBT. Structure templates are compiled from a typed block layout (./template.ts) into this tree
// and serialised here. Determinism: compound keys are written in the order given (the compiler builds them in a fixed
// order), no floats are produced by the compiler, and the gzip wrapper uses STORED deflate blocks with mtime 0, so
// the bytes never depend on the zlib build (the outer pack zip compresses them anyway). Minecraft reads structure
// files through a GZIPInputStream, which accepts stored blocks.
// The reader (`readNbt`) is independent of the writer (its own cursor code, real gunzip) and is used by the tests
// (round trips + a vanilla structure file read on node-2) and by the static file validator (an emitted or imported
// `.nbt` must parse, have DataVersion/size/palette/blocks, stay inside the size cap and reference real palette rows).
import { gunzipSync } from "node:zlib";

export const TAG = { End: 0, Byte: 1, Short: 2, Int: 3, Long: 4, Float: 5, Double: 6, ByteArray: 7, String: 8, List: 9, Compound: 10, IntArray: 11, LongArray: 12 } as const;

export type Nbt =
  | { t: "byte"; v: number } | { t: "short"; v: number } | { t: "int"; v: number } | { t: "long"; v: bigint }
  | { t: "float"; v: number } | { t: "double"; v: number } | { t: "string"; v: string }
  | { t: "list"; of: Nbt["t"] | "end"; v: Nbt[] } | { t: "compound"; v: [string, Nbt][] }
  | { t: "intArray"; v: number[] } | { t: "byteArray"; v: number[] } | { t: "longArray"; v: bigint[] };

const ID: Record<Nbt["t"] | "end", number> = { end: 0, byte: 1, short: 2, int: 3, long: 4, float: 5, double: 6, byteArray: 7, string: 8, list: 9, compound: 10, intArray: 11, longArray: 12 };
const NAME = Object.fromEntries(Object.entries(ID).map(([k, v]) => [v, k])) as Record<number, Nbt["t"] | "end">;

export const nInt = (v: number): Nbt => ({ t: "int", v });
export const nStr = (v: string): Nbt => ({ t: "string", v });
export const nList = (of: Nbt["t"] | "end", v: Nbt[]): Nbt => ({ t: "list", of: v.length ? of : "end", v });
export const nCompound = (entries: [string, Nbt][]): Nbt => ({ t: "compound", v: entries });

class Out {
  private chunks: Buffer[] = [];
  push(b: Buffer) { this.chunks.push(b); }
  u8(n: number) { const b = Buffer.alloc(1); b.writeUInt8(n); this.push(b); }
  i8(n: number) { const b = Buffer.alloc(1); b.writeInt8(n); this.push(b); }
  i16(n: number) { const b = Buffer.alloc(2); b.writeInt16BE(n); this.push(b); }
  u16(n: number) { const b = Buffer.alloc(2); b.writeUInt16BE(n); this.push(b); }
  i32(n: number) { const b = Buffer.alloc(4); b.writeInt32BE(n); this.push(b); }
  i64(n: bigint) { const b = Buffer.alloc(8); b.writeBigInt64BE(n); this.push(b); }
  f32(n: number) { const b = Buffer.alloc(4); b.writeFloatBE(n); this.push(b); }
  f64(n: number) { const b = Buffer.alloc(8); b.writeDoubleBE(n); this.push(b); }
  /** Java "modified UTF-8": NUL as C0 80, supplementary chars as surrogate pairs (3 bytes each). */
  str(s: string) {
    const bytes: number[] = [];
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      if (c >= 1 && c <= 0x7f) bytes.push(c);
      else if (c <= 0x7ff) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
      else bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    }
    if (bytes.length > 0xffff) throw new Error("NBT string longer than 65535 bytes");
    this.u16(bytes.length); this.push(Buffer.from(bytes));
  }
  done() { return Buffer.concat(this.chunks); }
}

function payload(o: Out, n: Nbt) {
  switch (n.t) {
    case "byte": o.i8(n.v); break;
    case "short": o.i16(n.v); break;
    case "int": o.i32(n.v); break;
    case "long": o.i64(n.v); break;
    case "float": o.f32(n.v); break;
    case "double": o.f64(n.v); break;
    case "string": o.str(n.v); break;
    case "byteArray": o.i32(n.v.length); for (const x of n.v) o.i8(x); break;
    case "intArray": o.i32(n.v.length); for (const x of n.v) o.i32(x); break;
    case "longArray": o.i32(n.v.length); for (const x of n.v) o.i64(x); break;
    case "list": {
      const of = n.v.length ? n.of : "end";
      if (n.v.some((x) => x.t !== of)) throw new Error("NBT list with mixed element types");
      o.u8(ID[of]); o.i32(n.v.length); for (const x of n.v) payload(o, x); break;
    }
    case "compound": {
      const seen = new Set<string>();
      for (const [k, v] of n.v) { if (seen.has(k)) throw new Error(`duplicate NBT key ${k}`); seen.add(k); o.u8(ID[v.t]); o.str(k); payload(o, v); }
      o.u8(0); break;
    }
  }
