export function writeNbt(root: Nbt, name = ""): Buffer {
  if (root.t !== "compound") throw new Error("the NBT root must be a compound");
  const o = new Out(); o.u8(TAG.Compound); o.str(name); payload(o, root); return o.done();
}

const CRC_TABLE = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
export function crc32(b: Uint8Array): number { let c = 0xffffffff; for (let i = 0; i < b.length; i++) c = CRC_TABLE[(c ^ b[i]) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; }

/** RFC 1952 gzip with STORED deflate blocks, mtime 0, OS 255: byte-identical on every platform and Node version. */
export function gzipStored(data: Buffer): Buffer {
  const parts: Buffer[] = [Buffer.from([0x1f, 0x8b, 8, 0, 0, 0, 0, 0, 0, 0xff])];
  let off = 0;
  do {
    const len = Math.min(65535, data.length - off), last = off + len >= data.length;
    const h = Buffer.alloc(5); h.writeUInt8(last ? 1 : 0, 0); h.writeUInt16LE(len, 1); h.writeUInt16LE(~len & 0xffff, 3);
    parts.push(h, data.subarray(off, off + len)); off += len;
  } while (off < data.length);
  const t = Buffer.alloc(8); t.writeUInt32LE(crc32(data), 0); t.writeUInt32LE(data.length >>> 0, 4); parts.push(t);
  return Buffer.concat(parts);
}

// ---------------------------------------------------------------------------------------------------------------
// Reference reader (independent cursor code)
// ---------------------------------------------------------------------------------------------------------------
export type NbtRead = { name: string; root: Nbt };
export const NBT_READ_LIMITS = { maxBytes: 8 * 1024 * 1024, maxDepth: 32, maxListLength: 1 << 20 } as const;

export function readNbt(input: Uint8Array): NbtRead {
  let buf = Buffer.from(input);
  if (buf[0] === 0x1f && buf[1] === 0x8b) buf = gunzipSync(buf, { maxOutputLength: NBT_READ_LIMITS.maxBytes });
  if (buf.length > NBT_READ_LIMITS.maxBytes) throw new Error("NBT larger than the read limit");
  let p = 0;
  const need = (n: number) => { if (p + n > buf.length) throw new Error("truncated NBT"); };
  const u8 = () => { need(1); return buf.readUInt8(p++); };
  const i8 = () => { need(1); return buf.readInt8(p++); };
  const i16 = () => { need(2); const v = buf.readInt16BE(p); p += 2; return v; };
  const u16 = () => { need(2); const v = buf.readUInt16BE(p); p += 2; return v; };
  const i32 = () => { need(4); const v = buf.readInt32BE(p); p += 4; return v; };
  const i64 = () => { need(8); const v = buf.readBigInt64BE(p); p += 8; return v; };
  const str = () => {
    const n = u16(); need(n); const b = buf.subarray(p, p + n); p += n;
    let s = "";
    for (let i = 0; i < b.length;) {
      const c = b[i];
      if (c < 0x80) { s += String.fromCharCode(c); i++; }
      else if ((c & 0xe0) === 0xc0) { s += String.fromCharCode(((c & 0x1f) << 6) | (b[i + 1] & 0x3f)); i += 2; }
      else { s += String.fromCharCode(((c & 0x0f) << 12) | ((b[i + 1] & 0x3f) << 6) | (b[i + 2] & 0x3f)); i += 3; }
    }
    return s;
  };
  const len = () => { const n = i32(); if (n < 0 || n > NBT_READ_LIMITS.maxListLength) throw new Error("bad NBT length"); return n; };
  const read = (id: number, depth: number): Nbt => {
    if (depth > NBT_READ_LIMITS.maxDepth) throw new Error("NBT nested too deep");
    switch (id) {
      case 1: return { t: "byte", v: i8() };
      case 2: return { t: "short", v: i16() };
      case 3: return { t: "int", v: i32() };
      case 4: return { t: "long", v: i64() };
      case 5: { need(4); const v = buf.readFloatBE(p); p += 4; return { t: "float", v }; }
      case 6: { need(8); const v = buf.readDoubleBE(p); p += 8; return { t: "double", v }; }
      case 7: { const n = len(); const v: number[] = []; for (let i = 0; i < n; i++) v.push(i8()); return { t: "byteArray", v }; }
      case 8: return { t: "string", v: str() };
      case 9: { const of = u8(); const n = len(); if (!(of in NAME)) throw new Error(`bad NBT list type ${of}`); const v: Nbt[] = []; for (let i = 0; i < n; i++) v.push(read(of, depth + 1)); return { t: "list", of: NAME[of], v }; }
      case 10: { const v: [string, Nbt][] = []; for (;;) { const t = u8(); if (t === 0) break; if (!(t in NAME)) throw new Error(`bad NBT tag ${t}`); const k = str(); v.push([k, read(t, depth + 1)]); } return { t: "compound", v }; }
      case 11: { const n = len(); const v: number[] = []; for (let i = 0; i < n; i++) v.push(i32()); return { t: "intArray", v }; }
      case 12: { const n = len(); const v: bigint[] = []; for (let i = 0; i < n; i++) v.push(i64()); return { t: "longArray", v }; }
      default: throw new Error(`bad NBT tag ${id}`);
    }
  };
  if (u8() !== TAG.Compound) throw new Error("the NBT root is not a compound");
  const name = str();
  const root = read(TAG.Compound, 0);
  if (p !== buf.length) throw new Error(`${buf.length - p} trailing bytes after the NBT root`);
  return { name, root };
}

/** Compound field lookup on a read tree. */
export function nbtGet(n: Nbt | undefined, key: string): Nbt | undefined {
  return n?.t === "compound" ? n.v.find(([k]) => k === key)?.[1] : undefined;
}

/** Plain-JS view (ints/strings/lists/objects) for tests and reports; longs become strings. */
export function nbtToJs(n: Nbt): unknown {
  switch (n.t) {
    case "compound": return Object.fromEntries(n.v.map(([k, v]) => [k, nbtToJs(v)]));
    case "list": return n.v.map(nbtToJs);
    case "long": return n.v.toString();
    case "longArray": return n.v.map(String);
    default: return n.v;
  }
}

