      case 10: { const v: [string, Nbt][] = []; for (;;) { const t = u8(); if (t === 0) break; if (!(t in NAME)) throw new Error(`bad NBT tag ${t}`); const k = str(); v.push([k, read(t, depth + 1)]); } return { t: "compound", v }; }
      case 11: { const n = len(); const v: number[] = []; for (let i = 0; i < n; i++) v.push(i32()); return { t: "intArray", v }; }
      case 12: { const n = len(); const v: bigint[] = []; for (let i = 0; i < n; i++) v.push(i64()); return { t: "longArray", v }; }
      default: throw new Error(`bad NBT tag ${id}`);
    }
  };
  if (u8() !== TAG.Compound) throw new Error("the NBT root is not a compound");
  const name = str();
  const root = read(TAG.Compound, 0);
  if (p !== buf.length) throw new Error(`${buf.length - p} trailing bytes after the NBT root`);
  return { name, root };
}

/** Compound field lookup on a read tree. */
export function nbtGet(n: Nbt | undefined, key: string): Nbt | undefined {
  return n?.t === "compound" ? n.v.find(([k]) => k === key)?.[1] : undefined;
}

/** Plain-JS view (ints/strings/lists/objects) for tests and reports; longs become strings. */
export function nbtToJs(n: Nbt): unknown {
  switch (n.t) {
    case "compound": return Object.fromEntries(n.v.map(([k, v]) => [k, nbtToJs(v)]));
    case "list": return n.v.map(nbtToJs);
    case "long": return n.v.toString();
    case "longArray": return n.v.map(String);
    default: return n.v;
  }
}

