// Cyrus R4 worldgen: what differs per Minecraft version for world generation files, plus the block state tables,
// world DataVersions and vanilla noise ranges derived from each pinned jar (data/worldgen-data.json, see
// scripts/cyrus/datapack-derive.py `worldgen`). Every difference below was VERIFIED on the real jars (2026-10-10,
// node-2): the vanilla data generator's own worldgen files were compared across 1.21.1 .. 26.2 and cross-checked with
// vanilla-mcdoc (docs "Cyrus worldgen (R4)"), then the emitted packs were booted with Test Flight.
import data from "../data/worldgen-data.json";
import { atLeast, DATAPACK_VERSIONS } from "../versions";

type WgData = { versions: string[]; dataVersion: Record<string, number>; noise: Record<string, Record<string, { minY: number; height: number }>>; blockStates: Record<string, Record<string, string[]>> };
const WG = data as unknown as WgData;
export const WORLDGEN_DATA_SOURCE = (data as unknown as { source: unknown }).source;

export type WorldgenFeatures = {
  version: string;
  /** World DataVersion written into structure NBT (the jar's version.json world_version). */
  dataVersion: number;
  /** <1.21.2: biome carvers are a map {"air": [...]}; >=1.21.2: a list. */
  carvers: "map" | "list";
  /**
   * <1.21.11: sky / fog / water fog colours, sounds, music and particles live in biome `effects` (colours as ints);
   * >=1.21.11: they are ENVIRONMENT ATTRIBUTES (`attributes`: minecraft:visual/sky_color, audio/background_music, ...),
   * `effects` keeps only water / grass / foliage colours, and colours are "#rrggbb" strings.
   */
  biome: "effects" | "attributes";
  /** <1.21.4: effects.music is one object; 1.21.4 .. 1.21.10: a weighted list [{data, weight}]. (Attributes: background_music.default.) */
  music: "single" | "weighted";
  /** effects.dry_foliage_color exists from 1.21.5. */
  dryFoliage: boolean;
  /**
   * <1.21.11: dimension_type has ultrawarm / natural / piglin_safe / bed_works / respawn_anchor_works / has_raids /
   * fixed_time / effects; >=1.21.11: those are environment attributes + has_fixed_time / skybox / cardinal_light /
   * timelines. >=26.1 adds default_clock and the REQUIRED has_ender_dragon_fight.
   */
  dimensionType: "classic" | "attributes";
  worldClock: boolean;
  /** <26.1: patches are the random_patch feature; >=26.1 random_patch / flower are gone (registry) and vanilla
   *  expresses a patch as a simple_block feature placed with count + random_offset + a block filter. */
  patch: "random_patch" | "placement";
  /** <26.1: tree dirt_provider + force_dirt; >=26.1: below_trunk_provider (required from 26.2). */
  treeDirt: "dirt_provider" | "below_trunk_provider";
  /** >=26.2: lake needs can_place_feature / can_replace_with_air_or_fluid / can_replace_with_barrier. */
  lakePredicates: boolean;
  /** The vertical range of each vanilla noise_settings preset in this version. */
  noise: Record<string, { minY: number; height: number }>;
};

export function worldgenFeatures(version: string): { ok: true; features: WorldgenFeatures } | { ok: false; error: string } {
  if (!WG.versions.includes(version) || !DATAPACK_VERSIONS.includes(version) || WG.dataVersion[version] === undefined) return { ok: false, error: `Cyrus has no verified world generation data for Minecraft ${version} yet` };
  return {
    ok: true,
    features: {
      version, dataVersion: WG.dataVersion[version],
      carvers: atLeast(version, "1.21.2") ? "list" : "map",
      biome: atLeast(version, "1.21.11") ? "attributes" : "effects",
      music: atLeast(version, "1.21.4") ? "weighted" : "single",
      dryFoliage: atLeast(version, "1.21.5"),
      dimensionType: atLeast(version, "1.21.11") ? "attributes" : "classic",
      worldClock: atLeast(version, "26.1"),
      patch: atLeast(version, "26.1") ? "placement" : "random_patch",
      treeDirt: atLeast(version, "26.1") ? "below_trunk_provider" : "dirt_provider",
      lakePredicates: atLeast(version, "26.2"),
      noise: WG.noise[version] ?? {},
    },
  };
}

const stateCache = new Map<string, Map<string, Record<string, string[]>>>();
/** block name (no "minecraft:") -> { property: allowed values } for one version (blocks without properties map to {}). */
export function blockStates(version: string): Map<string, Record<string, string[]>> {
  const hit = stateCache.get(version);
  if (hit) return hit;
  const bit = WG.versions.indexOf(version);
  const out = new Map<string, Record<string, string[]>>();
  if (bit >= 0) for (const [sig, masks] of Object.entries(WG.blockStates)) {
    const props: Record<string, string[]> = {};
    for (const part of sig.split(";")) { const [k, vs] = part.split("="); props[k] = vs.split(","); }
    for (const [mask, names] of Object.entries(masks)) if ((Number(mask) >> bit) & 1) for (const n of names) out.set(n, props);
  }
  stateCache.set(version, out);
  return out;
}

/** Problems with a block state ({ block, properties }) in `version`: unknown property names or values. The block id itself is checked elsewhere. */
export function blockStateProblems(block: string, properties: Record<string, string> | undefined, version: string): string[] {
  if (!properties) return [];
  const table = blockStates(version).get(block.replace(/^minecraft:/, "")) ?? {};
  const out: string[] = [];
  for (const [k, v] of Object.entries(properties)) {
    if (!(k in table)) out.push(`${block} has no block state property "${k}" in Minecraft ${version}${Object.keys(table).length ? ` (it has ${Object.keys(table).join(", ")})` : ""}`);
    else if (!table[k].includes(v)) out.push(`${block} ${k}=${v} is not allowed in Minecraft ${version} (allowed: ${table[k].join(", ")})`);
  }
  return out;
}

