// Cyrus R4 worldgen: the VERSION-NEUTRAL resource kinds the build model may write into a DataPackSpec (still
// schemaVersion 1: the new kinds are additions to the resource union, so every existing v1 spec stays valid and emits
// the same bytes). World generation is confined to the mod's OWN namespace: a custom dimension (dimension +
// dimension_type) whose biome source uses only the pack's own biomes, the pack's own features in those biomes, and
// structures placed only in those biomes. Vanilla biomes / dimensions / noise are never edited (see NOT_SUPPORTED).
//
// Engine safety: there is no custom noise router or density function: terrain shape comes from a vanilla
// noise_settings PRESET, so an absurd generator cannot be written. Every count / size below is capped
// (WORLDGEN_LIMITS), and ./cost.ts turns a pack into a per-chunk cost estimate with a hard ceiling.
import { z } from "zod";

export const WORLDGEN_LIMITS = {
  dimensions: 2, dimensionTypes: 2, biomes: 16, configuredFeatures: 32, placedFeatures: 32, templates: 8, structures: 8, structureSets: 4,
  /** own + vanilla placed features per biome */
  featuresPerBiome: 24,
  spawnsPerBiome: 16,
  /** structure template: each side <= 48 blocks (max volume 48 x 48 x 48), non-void blocks <= 32768, palette <= 32 */
  templateSide: 48, templateBlocks: 32768, paletteSize: 32, lootBlocksPerTemplate: 16,
  /** feature placement attempts per chunk (count x patch tries) per placed feature / per biome */
  attemptsPerFeature: 256, attemptsPerBiome: 1024,
  /** per-chunk cost estimate ceiling (cost.ts units); above it the pack is refused */
  maxCost: 100,
} as const;

const PATH = /^[a-z0-9_]+(\/[a-z0-9_]+){0,5}$/;
const REF = /^#?[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const Path = z.string().max(64).regex(PATH, "lowercase letters, digits, _ and / (max 6 segments)");
const Ref = z.string().max(120).regex(REF, "a namespaced id like minecraft:stone or nx_abcd1234:my_biome");
const IdRef = z.string().max(120).regex(/^[a-z0-9_.-]+:[a-z0-9_./-]+$/, "a namespaced id (no #tag here)");
const Int = (min: number, max: number) => z.number().int().min(min).max(max);
const Hex = z.string().regex(/^#[0-9a-fA-F]{6}$/, "a colour like #7ba4ff");
const PropName = z.string().regex(/^[a-z0-9_]{1,32}$/);
const PropValue = z.string().regex(/^[a-z0-9_]{1,32}$/);

/** A block state: a vanilla block id + optional properties (checked against the version's real block state table). */
export const BlockStateSchema = z.strictObject({ block: IdRef, properties: z.record(PropName, PropValue).optional() });
export type DpBlockState = z.infer<typeof BlockStateSchema>;
const StateOrId = z.union([IdRef, BlockStateSchema]);
export type DpStateOrId = z.infer<typeof StateOrId>;
export const asState = (s: DpStateOrId): DpBlockState => (typeof s === "string" ? { block: s } : s);

// ---- dimension_type -------------------------------------------------------------------------------------------
export const DimensionTypeSchema = z.strictObject({
  /** Base behaviour and sky: overworld (day cycle, sky), nether (no sky light, ceiling, fixed night), end (end sky, fixed time). */
  preset: z.enum(["overworld", "nether", "end"]),
  /** Bottom of the world; multiple of 16. Default: the preset's vanilla value. */
  minY: Int(-64, 0).refine((v) => v % 16 === 0, "minY must be a multiple of 16").optional(),
  /** World height; multiple of 16 (minY + height <= 320). */
  height: Int(64, 384).refine((v) => v % 16 === 0, "height must be a multiple of 16").optional(),
  logicalHeight: Int(64, 384).optional(),
  ambientLight: z.number().min(0).max(1).optional(),
  /** true = the sun/moon never move (nether / end feel); false = normal day-night cycle. Default per preset. */
  fixedTime: z.boolean().optional(),
  hasSkylight: z.boolean().optional(),
  hasCeiling: z.boolean().optional(),
  bedWorks: z.boolean().optional(),
  respawnAnchorWorks: z.boolean().optional(),
  hasRaids: z.boolean().optional(),
  /** Travel scale (the nether uses 8). 1 by default for custom dimensions. */
  coordinateScale: z.number().min(0.125).max(8).optional(),
  /** Monsters spawn at sky+block light 0..N (vanilla overworld: 7). */
  monsterSpawnLightLevel: Int(0, 15).optional(),
  monsterSpawnBlockLightLimit: Int(0, 15).optional(),
});
export type DpDimensionType = z.infer<typeof DimensionTypeSchema>;

// ---- dimension ------------------------------------------------------------------------------------------------
/** Vanilla terrain shapes the generator may use (no custom noise / density functions). */
export const NOISE_PRESETS = ["overworld", "large_biomes", "amplified", "caves", "floating_islands", "nether", "end"] as const;
const Climate = z.union([z.number().min(-2).max(2), z.tuple([z.number().min(-2).max(2), z.number().min(-2).max(2)])]);
export const BiomeSourceSchema = z.discriminatedUnion("kind", [
  z.strictObject({ kind: z.literal("fixed"), biome: IdRef }),
  /** Biomes in a grid of squares of 2^(scale+2) blocks. */
  z.strictObject({ kind: z.literal("checkerboard"), biomes: z.array(IdRef).min(1).max(8), scale: Int(0, 8).optional() }),
  /** Climate-based placement like the overworld: each biome sits at a point (or range) of the six climate noises. */
  z.strictObject({
    kind: z.literal("multi_noise"),
    biomes: z.array(z.strictObject({ biome: IdRef, temperature: Climate.optional(), humidity: Climate.optional(), continentalness: Climate.optional(), erosion: Climate.optional(), weirdness: Climate.optional(), depth: Climate.optional(), offset: z.number().min(0).max(1).optional() })).min(1).max(16),
  }),
]);
export type DpBiomeSource = z.infer<typeof BiomeSourceSchema>;
export const DimensionSchema = z.strictObject({
  /** Own dimension_type (nx_x:path) or a vanilla one (minecraft:overworld / the_nether / the_end / overworld_caves). */
  dimensionType: IdRef,
  generator: z.discriminatedUnion("kind", [
    z.strictObject({ kind: z.literal("noise"), terrain: z.enum(NOISE_PRESETS), biomes: BiomeSourceSchema }),
    /** Superflat: layers bottom-up (block + thickness), one biome; features: place the biome's features (default true). */
    z.strictObject({ kind: z.literal("flat"), layers: z.array(z.strictObject({ block: IdRef, height: Int(1, 64) })).min(1).max(16), biome: IdRef, features: z.boolean().optional() }),
  ]),
});
export type DpDimension = z.infer<typeof DimensionSchema>;

// ---- biome ----------------------------------------------------------------------------------------------------
export const DECORATION_STEPS = ["raw_generation", "lakes", "local_modifications", "underground_structures", "surface_structures", "strongholds", "underground_ores", "underground_decoration", "fluid_springs", "vegetal_decoration", "top_layer_modification"] as const;
export const MOB_CATEGORIES = ["monster", "creature", "ambient", "axolotls", "underground_water_creature", "water_creature", "water_ambient", "misc"] as const;
/** Ambient particles without options (the option-carrying ones are not in the subset). Each must exist in the version. */
export const BIOME_PARTICLES = ["ash", "white_ash", "crimson_spore", "warped_spore", "spore_blossom_air", "mycelium", "end_rod", "glow", "snowflake", "white_smoke", "firefly"] as const;
export const BiomeSchema = z.strictObject({
  temperature: z.number().min(-2).max(2),
  downfall: z.number().min(0).max(1),
  /** Rain (or snow when cold). */
  precipitation: z.boolean(),
  /** Frozen oceans / snow regardless of temperature. */
  frozen: z.boolean().optional(),
  colors: z.strictObject({ sky: Hex, fog: Hex, water: Hex, waterFog: Hex, grass: Hex.optional(), foliage: Hex.optional(), dryFoliage: Hex.optional(), grassModifier: z.enum(["none", "dark_forest", "swamp"]).optional() }),
  /** Background music: a vanilla sound event (e.g. minecraft:music.overworld.cherry_grove); delays in ticks. */
  music: z.strictObject({ sound: IdRef, minDelay: Int(0, 72000).optional(), maxDelay: Int(0, 72000).optional() }).optional(),
  /** Looping ambience (e.g. minecraft:ambient.basalt_deltas.loop). */
  ambientLoop: IdRef.optional(),
  /** Cave mood sound; default minecraft:ambient.cave. */
  mood: IdRef.optional(),
  additions: z.strictObject({ sound: IdRef, tickChance: z.number().min(0).max(0.1) }).optional(),
  particle: z.strictObject({ type: z.enum(BIOME_PARTICLES), probability: z.number().min(0).max(0.05) }).optional(),
  spawns: z.array(z.strictObject({ category: z.enum(MOB_CATEGORIES), entity: IdRef, weight: Int(1, 100), min: Int(1, 8), max: Int(1, 8) })).max(WORLDGEN_LIMITS.spawnsPerBiome).optional(),
  /** Placed features: own (nx_x:path) or vanilla placed features (minecraft:trees_plains, minecraft:ore_iron_middle, ...). */
  features: z.array(z.strictObject({ step: z.enum(DECORATION_STEPS), feature: IdRef })).max(WORLDGEN_LIMITS.featuresPerBiome).optional(),
  /** Vanilla configured carvers (minecraft:cave, minecraft:canyon, minecraft:cave_extra_underground, minecraft:nether_cave). */
  carvers: z.array(IdRef).max(4).optional(),
});
export type DpBiome = z.infer<typeof BiomeSchema>;

// ---- configured_feature (documented subset) ---------------------------------------------------------------------
export const ConfiguredFeatureSchema = z.discriminatedUnion("kind", [
  /** Ore blobs replacing `replace` (a block or #block tag, e.g. #minecraft:stone_ore_replaceables). */
  z.strictObject({ kind: z.literal("ore"), targets: z.array(z.strictObject({ replace: Ref, block: StateOrId })).min(1).max(4), size: Int(1, 32), discardOnAirExposure: z.number().min(0).max(1).optional() }),
  /** A straight-trunk, blob-canopy tree (vanilla oak shape) from any log / leaves. */
  z.strictObject({ kind: z.literal("tree"), trunk: StateOrId, foliage: StateOrId, baseHeight: Int(2, 12), heightRandA: Int(0, 6).optional(), heightRandB: Int(0, 6).optional(), foliageRadius: Int(1, 4).optional(), foliageHeight: Int(1, 4).optional(), dirt: IdRef.optional() }),
  /** A scattered patch of plants / small blocks (flowers, grass, mushrooms...). Placed only where the block survives. */
  z.strictObject({ kind: z.literal("patch"), blocks: z.array(z.strictObject({ block: StateOrId, weight: Int(1, 100).optional() })).min(1).max(8), tries: Int(1, 96), xzSpread: Int(0, 8), ySpread: Int(0, 4) }),
  /** A small surface lake of water or lava, rimmed with `barrier`. */
  z.strictObject({ kind: z.literal("lake"), fluid: z.enum(["water", "lava"]), barrier: IdRef }),
  /** One block (e.g. a single flower), placed only where it survives. */
  z.strictObject({ kind: z.literal("block"), block: StateOrId }),
]);
export type DpConfiguredFeature = z.infer<typeof ConfiguredFeatureSchema>;

// ---- placed_feature ---------------------------------------------------------------------------------------------
const Anchor = z.union([z.strictObject({ absolute: Int(-2032, 2031) }), z.strictObject({ aboveBottom: Int(-512, 512) }), z.strictObject({ belowTop: Int(-512, 512) })]);
export type DpAnchor = z.infer<typeof Anchor>;
export const HEIGHTMAPS = ["WORLD_SURFACE_WG", "WORLD_SURFACE", "OCEAN_FLOOR_WG", "OCEAN_FLOOR", "MOTION_BLOCKING", "MOTION_BLOCKING_NO_LEAVES"] as const;
export const PlacementSchema = z.discriminatedUnion("kind", [
  /** Try N times per chunk (or a uniform range). */
  z.strictObject({ kind: z.literal("count"), count: z.union([Int(1, 64), z.strictObject({ min: Int(0, 64), max: Int(1, 64) })]) }),
  /** Only in 1 of `chance` chunks. */
  z.strictObject({ kind: z.literal("rarity"), chance: Int(1, 1024) }),
  /** Random x/z inside the chunk. */
  z.strictObject({ kind: z.literal("in_square") }),
  /** Only where the biome at the position lists this feature (vanilla puts it last). */
  z.strictObject({ kind: z.literal("biome") }),
