  z.strictObject({ kind: z.literal("height_range"), shape: z.enum(["uniform", "trapezoid"]), min: Anchor, max: Anchor }),
  z.strictObject({ kind: z.literal("surface_water_depth"), maxDepth: Int(0, 8) }),
  /** Only where this block would survive (trees: their sapling). */
  z.strictObject({ kind: z.literal("would_survive"), block: StateOrId }),
]);
export type DpPlacement = z.infer<typeof PlacementSchema>;
export const PlacedFeatureSchema = z.strictObject({
  /** Own configured feature (nx_x:path) or a vanilla one (minecraft:ore_iron, minecraft:oak ...). */
  feature: IdRef,
  placement: z.array(PlacementSchema).max(10),
});
export type DpPlacedFeature = z.infer<typeof PlacedFeatureSchema>;

// ---- structure_template (block layout -> .nbt, compiled by ./template.ts) --------------------------------------
export const VOID_CHAR = ".";
const PaletteChar = z.string().regex(/^[ -~]$/, "one printable ASCII character").refine((c) => c !== VOID_CHAR, `"${VOID_CHAR}" is reserved for structure void (keep the terrain)`);
export const StructureTemplateSchema = z.strictObject({
  /** [x, y, z] in blocks, each 1..48. */
  size: z.tuple([Int(1, WORLDGEN_LIMITS.templateSide), Int(1, WORLDGEN_LIMITS.templateSide), Int(1, WORLDGEN_LIMITS.templateSide)]),
  /** One character per block state. "." is reserved: structure void (the terrain stays). Map a character to minecraft:air to clear space. */
  palette: z.record(PaletteChar, z.strictObject({ block: IdRef, properties: z.record(PropName, PropValue).optional(), /** chests / barrels: an own loot table */ loot: IdRef.optional() })),
  /** layers[y][z] = a row of x characters, bottom layer first (y = 0). */
  layers: z.array(z.array(z.string().max(WORLDGEN_LIMITS.templateSide)).max(WORLDGEN_LIMITS.templateSide)).max(WORLDGEN_LIMITS.templateSide),
});
export type DpStructureTemplate = z.infer<typeof StructureTemplateSchema>;

// ---- structure + structure_set -------------------------------------------------------------------------------------
export const StructureSchema = z.strictObject({
  /** Own structure template (nx_x:path), placed as one jigsaw piece. */
  template: IdRef,
  /** OWN biomes only (structures never appear in vanilla biomes). */
  biomes: z.array(IdRef).min(1).max(16),
  step: z.enum(DECORATION_STEPS).optional(),
  /** How the terrain fits around it: none, beard_thin (vanilla villages), beard_box, bury. */
