export type DpStructure = z.infer<typeof StructureSchema>;
export const StructureSetSchema = z.strictObject({
  structures: z.array(z.strictObject({ structure: IdRef, weight: Int(1, 100).optional() })).min(1).max(4),
  /** Average distance between attempts, in chunks (8..64). */
