  z.strictObject({ type: z.literal("dimension"), id: Path, dimension: DimensionSchema }),
  z.strictObject({ type: z.literal("biome"), id: Path, biome: BiomeSchema }),
  z.strictObject({ type: z.literal("configured_feature"), id: Path, feature: ConfiguredFeatureSchema }),
