  /** [x, y, z] in blocks, each 1..48. */
  size: z.tuple([Int(1, WORLDGEN_LIMITS.templateSide), Int(1, WORLDGEN_LIMITS.templateSide), Int(1, WORLDGEN_LIMITS.templateSide)]),
