// Cyrus R4 worldgen: structure TEMPLATE compiler. A typed block layout (palette of characters + y layers of z rows of
// x characters) -> a Minecraft structure file (`data/<ns>/structure/<id>.nbt`, gzipped NBT), deterministically:
// blocks in y, z, x order (block entities last, as vanilla's StructureTemplate does), palette rows in order of first
// use, fixed key order, stored gzip (./nbt.ts). Same layout + version = same bytes. The AI never writes NBT.
//
// File format (vanilla StructureTemplate.save, checked against vanilla templates read with readNbt on node-2):
//   { DataVersion: int, size: [x, y, z] ints, palette: [{ Name, Properties? }], blocks: [{ pos: [x, y, z], state: int, nbt? }], entities: [] }
// "." = structure void: no block entry, the terrain stays. A loot container (chest / trapped chest / barrel) gets the
// block entity { id, LootTable } so the chest rolls the pack's loot table when a player first opens it.
import type { DpStructureTemplate } from "./spec";
import { VOID_CHAR, WORLDGEN_LIMITS } from "./spec";
import { gzipStored, nCompound, nInt, nList, nStr, writeNbt, type Nbt } from "./nbt";

export const LOOT_CONTAINERS = ["chest", "trapped_chest", "barrel"] as const;

export type TemplateShapeIssue = { at: string; message: string };

/** Shape checks that do not depend on the version: layer / row counts and lengths, unknown characters, caps. */
export function templateShapeIssues(t: DpStructureTemplate): TemplateShapeIssue[] {
  const out: TemplateShapeIssue[] = [];
  const [sx, sy, sz] = t.size;
  const keys = Object.keys(t.palette);
  if (keys.length > WORLDGEN_LIMITS.paletteSize) out.push({ at: "palette", message: `${keys.length} palette entries; the limit is ${WORLDGEN_LIMITS.paletteSize}` });
  if (keys.some((k) => k.length !== 1)) out.push({ at: "palette", message: "palette keys must be single characters" });
  if (t.layers.length !== sy) out.push({ at: "layers", message: `size says ${sy} layers (y) but there are ${t.layers.length}` });
  let blocks = 0, loot = 0;
  t.layers.forEach((layer, y) => {
    if (layer.length !== sz) out.push({ at: `layers[${y}]`, message: `size says ${sz} rows (z) per layer but layer ${y} has ${layer.length}` });
    layer.forEach((row, z) => {
      if (row.length !== sx) out.push({ at: `layers[${y}][${z}]`, message: `size says ${sx} blocks (x) per row but this row has ${row.length}` });
      for (const ch of row) {
        if (ch === VOID_CHAR) continue;
        const p = t.palette[ch];
        if (!p) { out.push({ at: `layers[${y}][${z}]`, message: `"${ch}" is not in the palette` }); continue; }
        blocks++;
        if (p.loot) loot++;
      }
    });
  });
  if (blocks > WORLDGEN_LIMITS.templateBlocks) out.push({ at: "layers", message: `${blocks} blocks; the limit is ${WORLDGEN_LIMITS.templateBlocks} per template` });
  if (loot > WORLDGEN_LIMITS.lootBlocksPerTemplate) out.push({ at: "palette", message: `${loot} loot containers; the limit is ${WORLDGEN_LIMITS.lootBlocksPerTemplate} per template` });
  for (const [k, p] of Object.entries(t.palette)) if (p.loot && !(LOOT_CONTAINERS as readonly string[]).includes(p.block.replace(/^minecraft:/, ""))) out.push({ at: `palette.${k}.loot`, message: `only ${LOOT_CONTAINERS.join(", ")} can carry a loot table (not ${p.block})` });
  const unused = keys.filter((k) => !t.layers.some((l) => l.some((r) => r.includes(k))));
  if (unused.length) out.push({ at: "palette", message: `palette entries never used: ${unused.map((u) => JSON.stringify(u)).join(", ")}` });
  return out;
}

export type CompiledTemplate = { nbt: Buffer; raw: Buffer; blocks: number; nonAir: number; palette: number; volume: number; loot: string[] };

