// Cyrus R4 worldgen emitters: spec resources -> real worldgen files for ONE version. Every version difference goes
// through WorldgenFeatures (./versions.ts); the shapes mirror the vanilla files of the same version (dumped by the
// data generator of each pinned jar). Called by ../emit/index.ts for an ALREADY VALIDATED spec.
import type { DataPackSpec, DpResource } from "../spec";
import { jsonText, type Json } from "../emit/common";
import { asState, DECORATION_STEPS, MOB_CATEGORIES, type DpBiome, type DpBiomeSource, type DpBlockState, type DpConfiguredFeature, type DpDimension, type DpDimensionType, type DpPlacement, type DpStateOrId, type DpStructure, type DpStructureSet, type DpAnchor } from "./spec";
import { compileTemplate } from "./template";
import type { WorldgenFeatures } from "./versions";

export type WgFile = { path: string; text: string; data?: Buffer };
type J = { [k: string]: Json | undefined };
const mc = (id: string) => (id.includes(":") ? id : `minecraft:${id}`);

export function blockStateJson(s: DpBlockState): Json {
  const o: J = { Name: mc(s.block) };
  const keys = Object.keys(s.properties ?? {}).sort();
  if (keys.length) o.Properties = Object.fromEntries(keys.map((k) => [k, s.properties![k]]));
  return o;
}
const simple = (s: DpStateOrId): Json => ({ type: "minecraft:simple_state_provider", state: blockStateJson(asState(s)) });
const provider = (xs: { block: DpStateOrId; weight?: number }[]): Json =>
  xs.length === 1 ? simple(xs[0].block) : { type: "minecraft:weighted_state_provider", entries: xs.map((x) => ({ data: blockStateJson(asState(x.block)), weight: x.weight ?? 1 })) };
const hexInt = (h: string) => parseInt(h.slice(1), 16);
const hexStr = (h: string) => h.toLowerCase();

// ---- dimension_type -----------------------------------------------------------------------------------------------
const DT_DEFAULTS = {
  overworld: { minY: -64, height: 384, ambientLight: 0, fixedTime: false, hasSkylight: true, hasCeiling: false, bedWorks: true, respawnAnchorWorks: false, hasRaids: true, monsterSpawnLightLevel: 7, monsterSpawnBlockLightLimit: 0, infiniburn: "#minecraft:infiniburn_overworld", fixedAt: 6000 },
  nether: { minY: 0, height: 256, ambientLight: 0.1, fixedTime: true, hasSkylight: false, hasCeiling: true, bedWorks: false, respawnAnchorWorks: true, hasRaids: false, monsterSpawnLightLevel: 7, monsterSpawnBlockLightLimit: 15, infiniburn: "#minecraft:infiniburn_nether", fixedAt: 18000 },
  end: { minY: 0, height: 256, ambientLight: 0, fixedTime: true, hasSkylight: false, hasCeiling: false, bedWorks: false, respawnAnchorWorks: false, hasRaids: true, monsterSpawnLightLevel: 7, monsterSpawnBlockLightLimit: 0, infiniburn: "#minecraft:infiniburn_end", fixedAt: 6000 },
} as const;

/** Resolved knobs (preset defaults applied); also used by the validator (height range vs the noise preset). */
export function resolveDimensionType(d: DpDimensionType) {
  const b = DT_DEFAULTS[d.preset];
  const minY = d.minY ?? b.minY, height = d.height ?? b.height;
  return {
    preset: d.preset, minY, height, logicalHeight: Math.min(d.logicalHeight ?? height, height), ambientLight: d.ambientLight ?? b.ambientLight, fixedTime: d.fixedTime ?? b.fixedTime,
    hasSkylight: d.hasSkylight ?? b.hasSkylight, hasCeiling: d.hasCeiling ?? b.hasCeiling, bedWorks: d.bedWorks ?? b.bedWorks, respawnAnchorWorks: d.respawnAnchorWorks ?? b.respawnAnchorWorks,
    hasRaids: d.hasRaids ?? b.hasRaids, coordinateScale: d.coordinateScale ?? 1, monsterSpawnLightLevel: d.monsterSpawnLightLevel ?? b.monsterSpawnLightLevel,
    monsterSpawnBlockLightLimit: d.monsterSpawnBlockLightLimit ?? b.monsterSpawnBlockLightLimit, infiniburn: b.infiniburn, fixedAt: b.fixedAt,
  };
}
const spawnLight = (n: number): Json => (n === 0 ? 0 : { type: "minecraft:uniform", max_inclusive: n, min_inclusive: 0 });

export function emitDimensionType(d: DpDimensionType, wf: WorldgenFeatures): Json {
  const r = resolveDimensionType(d);
  if (wf.dimensionType === "classic") {
    const o: J = {
      ambient_light: r.ambientLight, bed_works: r.bedWorks, coordinate_scale: r.coordinateScale,
      effects: r.preset === "overworld" ? "minecraft:overworld" : r.preset === "nether" ? "minecraft:the_nether" : "minecraft:the_end",
      ...(r.fixedTime ? { fixed_time: r.fixedAt } : {}),
      has_ceiling: r.hasCeiling, has_raids: r.hasRaids, has_skylight: r.hasSkylight, height: r.height, infiniburn: r.infiniburn, logical_height: r.logicalHeight, min_y: r.minY,
      monster_spawn_block_light_limit: r.monsterSpawnBlockLightLimit, monster_spawn_light_level: spawnLight(r.monsterSpawnLightLevel),
      natural: r.preset === "overworld", piglin_safe: r.preset === "nether", respawn_anchor_works: r.respawnAnchorWorks, ultrawarm: r.preset === "nether",
    };
    return o;
  }
  // 1.21.11+: environment attributes (mirrors vanilla's overworld / the_nether / the_end of the same version)
  const attrs: J = {
    "minecraft:gameplay/bed_rule": r.bedWorks ? { can_set_spawn: "always", can_sleep: "when_dark", error_message: { translate: "block.minecraft.bed.no_sleep" } } : { can_set_spawn: "never", can_sleep: "never", explodes: true },
    ...(r.hasRaids ? {} : { "minecraft:gameplay/can_start_raid": false }),
    ...(r.preset === "nether" ? { "minecraft:gameplay/fast_lava": true, "minecraft:gameplay/piglins_zombify": false, "minecraft:gameplay/water_evaporates": true } : {}),
    "minecraft:gameplay/respawn_anchor_works": r.respawnAnchorWorks,
  };
  const timelines = r.fixedTime ? null : r.preset === "end" ? "#minecraft:in_end" : r.preset === "nether" ? "#minecraft:in_nether" : "#minecraft:in_overworld";
  return {
    ambient_light: r.ambientLight, attributes: attrs,
    ...(r.preset === "nether" ? { cardinal_light: "nether" } : {}),
    coordinate_scale: r.coordinateScale,
    ...(wf.worldClock && !r.fixedTime ? { default_clock: r.preset === "end" ? "minecraft:the_end" : "minecraft:overworld" } : {}),
    has_ceiling: r.hasCeiling,
    ...(wf.worldClock ? { has_ender_dragon_fight: false } : {}),
    ...(r.fixedTime ? { has_fixed_time: true } : {}),
    has_skylight: r.hasSkylight, height: r.height, infiniburn: r.infiniburn, logical_height: r.logicalHeight, min_y: r.minY,
    monster_spawn_block_light_limit: r.monsterSpawnBlockLightLimit, monster_spawn_light_level: spawnLight(r.monsterSpawnLightLevel),
    ...(r.preset === "end" ? { skybox: "end" } : r.preset === "nether" ? { skybox: "none" } : {}),
    ...(timelines ? { timelines } : {}),
  };
}

// ---- dimension ------------------------------------------------------------------------------------------------------
const climate = (v: number | [number, number] | undefined): Json => (v === undefined ? 0 : v);
function biomeSource(b: DpBiomeSource): Json {
  if (b.kind === "fixed") return { type: "minecraft:fixed", biome: b.biome };
  if (b.kind === "checkerboard") return { type: "minecraft:checkerboard", biomes: b.biomes, scale: b.scale ?? 2 };
  return {
    type: "minecraft:multi_noise",
    biomes: b.biomes.map((x) => ({ biome: x.biome, parameters: { continentalness: climate(x.continentalness), depth: climate(x.depth), erosion: climate(x.erosion), humidity: climate(x.humidity), offset: x.offset ?? 0, temperature: climate(x.temperature), weirdness: climate(x.weirdness) } })),
  };
}
export function emitDimension(d: DpDimension, ownSets: string[]): Json {
  const g = d.generator;
  if (g.kind === "noise") return { type: d.dimensionType, generator: { type: "minecraft:noise", biome_source: biomeSource(g.biomes), settings: `minecraft:${g.terrain}` } };
  return { type: d.dimensionType, generator: { type: "minecraft:flat", settings: { biome: g.biome, features: g.features ?? true, lakes: false, layers: g.layers.map((l) => ({ block: l.block, height: l.height })), structure_overrides: ownSets } } };
}

// ---- biome --------------------------------------------------------------------------------------------------------
export function emitBiome(b: DpBiome, wf: WorldgenFeatures): Json {
  const spawners: J = {};
  for (const c of MOB_CATEGORIES) spawners[c] = (b.spawns ?? []).filter((s) => s.category === c).map((s) => ({ type: s.entity, maxCount: Math.max(s.min, s.max), minCount: Math.min(s.min, s.max), weight: s.weight }));
  const steps: string[][] = DECORATION_STEPS.map(() => []);
  for (const f of b.features ?? []) { const i = DECORATION_STEPS.indexOf(f.step); if (!steps[i].includes(f.feature)) steps[i].push(f.feature); }
  let last = steps.length; while (last > 0 && !steps[last - 1].length) last--;
  const carvers = b.carvers ?? [];
  const music = b.music ? { max_delay: Math.max(b.music.minDelay ?? 12000, b.music.maxDelay ?? 24000), min_delay: Math.min(b.music.minDelay ?? 12000, b.music.maxDelay ?? 24000), replace_current_music: false, sound: b.music.sound } : null;
  const mood = { block_search_extent: 8, offset: 2.0, sound: b.mood ?? "minecraft:ambient.cave", tick_delay: 6000 };
  const c = b.colors;
  const head: J = {}, effects: J = {};
  if (wf.biome === "effects") {
    if (b.additions) effects.additions_sound = { sound: b.additions.sound, tick_chance: b.additions.tickChance };
    if (b.ambientLoop) effects.ambient_sound = b.ambientLoop;
    if (c.dryFoliage && wf.dryFoliage) effects.dry_foliage_color = hexInt(c.dryFoliage);
    effects.fog_color = hexInt(c.fog);
    if (c.foliage) effects.foliage_color = hexInt(c.foliage);
    if (c.grass) effects.grass_color = hexInt(c.grass);
    if (c.grassModifier && c.grassModifier !== "none") effects.grass_color_modifier = c.grassModifier;
    effects.mood_sound = mood;
    if (music) effects.music = wf.music === "single" ? music : [{ data: music, weight: 1 }];
    if (b.particle) effects.particle = { options: { type: `minecraft:${b.particle.type}` }, probability: b.particle.probability };
    effects.sky_color = hexInt(c.sky); effects.water_color = hexInt(c.water); effects.water_fog_color = hexInt(c.waterFog);
  } else {
    const attrs: J = {};
    if (b.ambientLoop || b.mood || b.additions) attrs["minecraft:audio/ambient_sounds"] = { ...(b.additions ? { additions: { sound: b.additions.sound, tick_chance: b.additions.tickChance } } : {}), ...(b.ambientLoop ? { loop: b.ambientLoop } : {}), mood };
    if (music) attrs["minecraft:audio/background_music"] = { default: { max_delay: music.max_delay, min_delay: music.min_delay, sound: music.sound } };
    if (b.particle) attrs["minecraft:visual/ambient_particles"] = [{ particle: { type: `minecraft:${b.particle.type}` }, probability: b.particle.probability }];
    attrs["minecraft:visual/fog_color"] = hexStr(c.fog); attrs["minecraft:visual/sky_color"] = hexStr(c.sky); attrs["minecraft:visual/water_fog_color"] = hexStr(c.waterFog);
    head.attributes = attrs;
    if (c.dryFoliage) effects.dry_foliage_color = hexStr(c.dryFoliage);
    if (c.foliage) effects.foliage_color = hexStr(c.foliage);
    if (c.grass) effects.grass_color = hexStr(c.grass);
    if (c.grassModifier && c.grassModifier !== "none") effects.grass_color_modifier = c.grassModifier;
    effects.water_color = hexStr(c.water);
  }
  return {
    ...head,
    carvers: wf.carvers === "map" ? (carvers.length ? { air: carvers } : {}) : carvers,
    downfall: b.downfall, effects, features: steps.slice(0, last), has_precipitation: b.precipitation,
    spawn_costs: {}, spawners, temperature: b.temperature,
    ...(b.frozen ? { temperature_modifier: "frozen" } : {}),
  };
}

// ---- configured / placed features ------------------------------------------------------------------------------------
const AIR_FILTER: Json = { type: "minecraft:block_predicate_filter", predicate: { type: "minecraft:matching_blocks", blocks: "minecraft:air" } };
export function emitConfiguredFeature(f: DpConfiguredFeature, wf: WorldgenFeatures): Json {
  switch (f.kind) {
    case "ore":
      return { type: "minecraft:ore", config: { discard_chance_on_air_exposure: f.discardOnAirExposure ?? 0, size: f.size, targets: f.targets.map((t) => ({ state: blockStateJson(asState(t.block)), target: t.replace.startsWith("#") ? { predicate_type: "minecraft:tag_match", tag: t.replace.slice(1) } : { block: t.replace, predicate_type: "minecraft:block_match" } })) } };
    case "tree": {
      const dirt = { type: "minecraft:simple_state_provider", state: { Name: f.dirt ?? "minecraft:dirt" } };
      const cfg: J = {};
      if (wf.treeDirt === "below_trunk_provider") cfg.below_trunk_provider = { type: "minecraft:rule_based_state_provider", rules: [{ if_true: { type: "minecraft:not", predicate: { type: "minecraft:matching_block_tag", tag: "minecraft:cannot_replace_below_tree_trunk" } }, then: dirt }] };
      cfg.decorators = [];
      if (wf.treeDirt === "dirt_provider") cfg.dirt_provider = dirt;
      cfg.foliage_placer = { type: "minecraft:blob_foliage_placer", height: f.foliageHeight ?? 3, offset: 0, radius: f.foliageRadius ?? 2 };
      cfg.foliage_provider = simple(f.foliage);
      if (wf.treeDirt === "dirt_provider") cfg.force_dirt = false;
      cfg.ignore_vines = true;
      cfg.minimum_size = { type: "minecraft:two_layers_feature_size", limit: 1, lower_size: 0, upper_size: 1 };
      cfg.trunk_placer = { type: "minecraft:straight_trunk_placer", base_height: f.baseHeight, height_rand_a: f.heightRandA ?? 2, height_rand_b: f.heightRandB ?? 0 };
      cfg.trunk_provider = simple(f.trunk);
      return { type: "minecraft:tree", config: cfg };
    }
    case "patch":
      if (wf.patch === "placement") return { type: "minecraft:simple_block", config: { to_place: provider(f.blocks) } };
      return { type: "minecraft:random_patch", config: { feature: { feature: { type: "minecraft:simple_block", config: { to_place: provider(f.blocks) } }, placement: [AIR_FILTER] }, tries: f.tries, xz_spread: f.xzSpread, y_spread: f.ySpread } };
    case "lake": {
      const cfg: J = { barrier: simple(f.barrier) };
      if (wf.lakePredicates) Object.assign(cfg, {
        can_place_feature: { type: "minecraft:true" },
        can_replace_with_air_or_fluid: { type: "minecraft:not", predicate: { type: "minecraft:matching_block_tag", tag: "minecraft:features_cannot_replace" } },
        can_replace_with_barrier: { type: "minecraft:not", predicate: { type: "minecraft:matching_block_tag", tag: "minecraft:lava_pool_stone_cannot_replace" } },
      });
      cfg.fluid = { type: "minecraft:simple_state_provider", state: { Name: `minecraft:${f.fluid}`, Properties: { level: "0" } } };
      return { type: "minecraft:lake", config: cfg };
    }
    case "block":
      return { type: "minecraft:simple_block", config: { to_place: simple(f.block) } };
  }
}

const anchor = (a: DpAnchor): Json => ("absolute" in a ? { absolute: a.absolute } : "aboveBottom" in a ? { above_bottom: a.aboveBottom } : { below_top: a.belowTop });
const spread = (n: number): Json => (n === 0 ? 0 : { type: "minecraft:trapezoid", max: n, min: -n, plateau: 0 });
function placement(p: DpPlacement): Json {
  switch (p.kind) {
    case "count": return { type: "minecraft:count", count: typeof p.count === "number" ? p.count : { type: "minecraft:uniform", max_inclusive: Math.max(p.count.min, p.count.max), min_inclusive: Math.min(p.count.min, p.count.max) } };
    case "rarity": return { type: "minecraft:rarity_filter", chance: p.chance };
    case "in_square": return { type: "minecraft:in_square" };
    case "biome": return { type: "minecraft:biome" };
    case "heightmap": return { type: "minecraft:heightmap", heightmap: p.heightmap };
    case "height_range": return { type: "minecraft:height_range", height: { type: `minecraft:${p.shape}`, max_inclusive: anchor(p.max), min_inclusive: anchor(p.min) } };
    case "surface_water_depth": return { type: "minecraft:surface_water_depth_filter", max_water_depth: p.maxDepth };
    case "would_survive": return { type: "minecraft:block_predicate_filter", predicate: { state: blockStateJson(asState(p.block)), type: "minecraft:would_survive" } };
  }
}
/** `patchOf` = the OWN patch configured feature this placed feature uses (26.1+ appends the patch spread here). */
export function emitPlacedFeature(p: { feature: string; placement: DpPlacement[] }, wf: WorldgenFeatures, patchOf: Extract<DpConfiguredFeature, { kind: "patch" }> | null): Json {
  const mods = p.placement.map(placement);
  if (patchOf && wf.patch === "placement") mods.push({ type: "minecraft:count", count: patchOf.tries }, { type: "minecraft:random_offset", xz_spread: spread(patchOf.xzSpread), y_spread: spread(patchOf.ySpread) }, AIR_FILTER);
  return { feature: p.feature, placement: mods };
}

// ---- structures -------------------------------------------------------------------------------------------------------
export function emitStructure(s: DpStructure, startPool: string): Json {
  return {
    type: "minecraft:jigsaw", biomes: s.biomes, max_distance_from_center: 80, project_start_to_heightmap: s.heightmap ?? "WORLD_SURFACE_WG", size: 1,
    spawn_overrides: {}, start_height: { absolute: s.yOffset ?? 0 }, start_pool: startPool, step: s.step ?? "surface_structures",
    terrain_adaptation: s.terrainAdaptation ?? "beard_thin", use_expansion_hack: false,
  };
}
export const emitTemplatePool = (template: string): Json => ({ elements: [{ element: { element_type: "minecraft:single_pool_element", location: template, processors: { processors: [] }, projection: "rigid" }, weight: 1 }], fallback: "minecraft:empty" });
export function emitStructureSet(s: DpStructureSet): Json {
  const pl: J = { type: "minecraft:random_spread" };
  if (s.frequency !== undefined && s.frequency < 1) { pl.frequency = s.frequency; pl.frequency_reduction_method = "default"; }
  pl.salt = s.salt; pl.separation = s.separation; pl.spacing = s.spacing;
  if (s.spreadType) pl.spread_type = s.spreadType;
  return { placement: pl, structures: s.structures.map((x) => ({ structure: x.structure, weight: x.weight ?? 1 })) };
}

/** All worldgen files of a validated spec for one version (JSON as text; structure templates as gzipped NBT in `data`). */
export function emitWorldgenFiles(spec: DataPackSpec, ns: string, wf: WorldgenFeatures): WgFile[] {
  const out: WgFile[] = [];
  const base = `data/${ns}`;
  const own = (t: string) => spec.resources.filter((r) => r.type === t) as DpResource[];
  const patches = new Map<string, Extract<DpConfiguredFeature, { kind: "patch" }>>();
  for (const r of own("configured_feature")) if (r.type === "configured_feature" && r.feature.kind === "patch") patches.set(`${ns}:${r.id}`, r.feature);
  const sets = own("structure_set").map((r) => `${ns}:${r.id}`).sort();
  for (const r of spec.resources) {
    switch (r.type) {
      case "dimension_type": out.push({ path: `${base}/dimension_type/${r.id}.json`, text: jsonText(emitDimensionType(r.dimensionType, wf)) }); break;
      case "dimension": out.push({ path: `${base}/dimension/${r.id}.json`, text: jsonText(emitDimension(r.dimension, sets)) }); break;
      case "biome": out.push({ path: `${base}/worldgen/biome/${r.id}.json`, text: jsonText(emitBiome(r.biome, wf)) }); break;
      case "configured_feature": out.push({ path: `${base}/worldgen/configured_feature/${r.id}.json`, text: jsonText(emitConfiguredFeature(r.feature, wf)) }); break;
      case "placed_feature": out.push({ path: `${base}/worldgen/placed_feature/${r.id}.json`, text: jsonText(emitPlacedFeature(r.placed, wf, patches.get(r.placed.feature) ?? null)) }); break;
      case "structure":
        out.push({ path: `${base}/worldgen/structure/${r.id}.json`, text: jsonText(emitStructure(r.structure, `${ns}:${r.id}`)) });
        out.push({ path: `${base}/worldgen/template_pool/${r.id}.json`, text: jsonText(emitTemplatePool(r.structure.template)) });
        break;
      case "structure_set": out.push({ path: `${base}/worldgen/structure_set/${r.id}.json`, text: jsonText(emitStructureSet(r.structureSet)) }); break;
      case "structure_template": {
        const c = compileTemplate(r.template, wf.dataVersion);
        out.push({ path: `${base}/structure/${r.id}.nbt`, text: "", data: c.nbt });
        break;
      }
    }
  }
  return out;
}

