// Cyrus R4 worldgen: SEMANTIC checks of the worldgen resources of a parsed DataPackSpec (called by
// validateDataPackSpec) + the engine-level safety limits and the per-chunk cost estimate.
//   references   every reference resolves: own ids inside the pack (right kind), vanilla ids in THIS version's real
//                registries (blocks, block tags, placed / configured features, carvers, sound events, particles,
//                entity types, dimension types); biome sources and structures use only the pack's OWN biomes
//   worldgen     the dimension's height range contains the noise preset's; flat layers fit; block state properties
//                exist; template shape; denied blocks; loot containers point at own loot tables; feature order
//                cycles (Minecraft refuses to start: "Feature order cycle found"); unused biomes / structures warn
//   limits       counts per kind, placement attempts per feature / biome, template volume, the cost estimate ceiling
import type { DataPackSpec, DpResource } from "../spec";
import { isVanilla, missingIdReason, type IdKind } from "../versions";
import { resolveDimensionType } from "./emit";
import { asState, DECORATION_STEPS, WORLDGEN_LIMITS, WORLDGEN_TYPES, type DpConfiguredFeature, type DpPlacement, type DpStateOrId } from "./spec";
import { templateShapeIssues } from "./template";
import { blockStateProblems, worldgenFeatures, type WorldgenFeatures } from "./versions";

type Fail = (check: string, path: string, code: string, message: string) => void;
type R<T extends string> = Extract<DpResource, { type: T }>;

/** Blocks that never go into generated terrain, features or templates (operator / technical / griefing blocks). */
export const DENIED_BLOCKS = new Set(["command_block", "chain_command_block", "repeating_command_block", "structure_block", "jigsaw", "structure_void", "barrier", "spawner", "trial_spawner", "vault", "end_portal", "end_gateway", "nether_portal", "moving_piston", "piston_head", "tnt", "fire", "soul_fire", "test_block", "test_instance_block", "light"]);
/** Mobs a biome may spawn (each must also exist in the version). No bosses, players, projectiles or technical entities. */
export const SPAWNABLE = new Set([
  "pig", "cow", "sheep", "chicken", "rabbit", "horse", "donkey", "llama", "goat", "fox", "wolf", "cat", "ocelot", "panda", "parrot", "polar_bear", "bee", "frog", "turtle", "camel", "armadillo", "mooshroom", "strider",
  "zombie", "skeleton", "creeper", "spider", "cave_spider", "enderman", "witch", "slime", "drowned", "husk", "stray", "bogged", "zombie_villager", "blaze", "ghast", "magma_cube", "piglin", "zombified_piglin", "hoglin", "wither_skeleton", "silverfish", "endermite", "breeze",
  "bat", "squid", "glow_squid", "dolphin", "cod", "salmon", "tropical_fish", "pufferfish", "axolotl",
]);
/** Vanilla dimension types and their height ranges (identical 1.21.1 .. 26.2, from the generated vanilla files). */
const VANILLA_DT: Record<string, { minY: number; height: number }> = { overworld: { minY: -64, height: 384 }, overworld_caves: { minY: -64, height: 384 }, the_nether: { minY: 0, height: 256 }, the_end: { minY: 0, height: 256 } };
const TERRAIN_COST: Record<string, number> = { overworld: 10, large_biomes: 10, amplified: 14, caves: 12, floating_islands: 8, nether: 8, end: 5 };

export type WorldgenCost = {
  /** Heuristic per-chunk generation cost (1 = a superflat chunk; vanilla overworld terrain = 10). */
  score: number; class: "low" | "medium" | "high" | "refused";
  perDimension: { id: string; terrain: number; features: number; structures: number; total: number }[];
  notes: string[];
};
export type WorldgenSummary = { types: Record<string, number>; dimensions: string[]; biomes: string[]; structures: string[]; templates: { id: string; blocks: number; volume: number }[]; cost: WorldgenCost };

export const hasWorldgen = (spec: { resources: { type: string }[] }) => spec.resources.some((r) => (WORLDGEN_TYPES as readonly string[]).includes(r.type));

export function checkWorldgen(spec: DataPackSpec, ctx: { ns: string; version: string; worldgen?: boolean }, fail: Fail, warn: Fail): WorldgenSummary | null {
  const wgIdx = spec.resources.map((r, i) => ({ r, i })).filter((x) => (WORLDGEN_TYPES as readonly string[]).includes(x.r.type));
  if (!wgIdx.length) return null;
  const v = ctx.version, ns = ctx.ns;
  if (!ctx.worldgen) { fail("worldgen", `resources[${wgIdx[0].i}]`, "worldgen_off", "world generation resources (dimensions, biomes, features, structures) are not enabled for this build"); return null; }
  const wfr = worldgenFeatures(v);
  if (!wfr.ok) { fail("version_features", "version", "worldgen_version", wfr.error); return null; }
  const wf: WorldgenFeatures = wfr.features;

  const of = <T extends string>(t: T) => spec.resources.map((r, i) => ({ r, i })).filter((x): x is { r: R<T>; i: number } => x.r.type === t);
  const ids = (t: string) => new Set(spec.resources.filter((r) => r.type === t).map((r) => `${ns}:${(r as { id: string }).id}`));
  const own = { dimension_type: ids("dimension_type"), biome: ids("biome"), configured_feature: ids("configured_feature"), placed_feature: ids("placed_feature"), structure_template: ids("structure_template"), structure: ids("structure"), structure_set: ids("structure_set"), loot_table: ids("loot_table") };
  const caps: [string, number][] = [["dimension", WORLDGEN_LIMITS.dimensions], ["dimension_type", WORLDGEN_LIMITS.dimensionTypes], ["biome", WORLDGEN_LIMITS.biomes], ["configured_feature", WORLDGEN_LIMITS.configuredFeatures], ["placed_feature", WORLDGEN_LIMITS.placedFeatures], ["structure_template", WORLDGEN_LIMITS.templates], ["structure", WORLDGEN_LIMITS.structures], ["structure_set", WORLDGEN_LIMITS.structureSets]];
  for (const [t, max] of caps) { const n = of(t).length; if (n > max) fail("limits", "resources", "worldgen_count", `${n} ${t} resources; the limit is ${max} per pack`); }

  const nsOf = (ref: string) => ref.replace(/^#/, "").split(":")[0];
  /** own-or-vanilla reference of one kind */
  const ref = (at: string, r: string, opts: { own?: Set<string>; ownKind?: string; vanilla?: IdKind; vanillaTag?: IdKind; ownOnly?: string }) => {
    const n = nsOf(r);
    if (n === ns) {
      if (r.startsWith("#") || !opts.own) return fail("references", at, "not_definable", `${r}: this pack cannot define that here`);
      if (!opts.own.has(r)) fail("references", at, "unresolved_ref", `${r} is not defined in this pack (as a ${opts.ownKind})`);
    } else if (n === "minecraft") {
      if (opts.ownOnly) return fail("references", at, "own_only", `${r}: ${opts.ownOnly}`);
      const kind = r.startsWith("#") ? opts.vanillaTag : opts.vanilla;
      if (!kind) return fail("references", at, "not_allowed", `${r}: ${r.startsWith("#") ? "a tag" : "a vanilla id"} is not allowed here`);
      if (!isVanilla(kind, r, v)) fail("vanilla_ids", at, "unknown_vanilla_id", missingIdReason(kind, r, v));
    } else fail("namespace", at, "foreign_namespace", `${r} uses the namespace ${n}; this pack may only use minecraft: and its own ${ns}`);
  };
  const block = (at: string, s: DpStateOrId) => {
    const st = asState(s);
    if (nsOf(st.block) !== "minecraft") return fail("references", at, "own_block", `${st.block}: a data pack cannot add blocks; use a vanilla block`);
    if (!isVanilla("block", st.block, v)) return fail("vanilla_ids", at, "unknown_vanilla_id", missingIdReason("block", st.block, v));
    const bare = st.block.replace(/^minecraft:/, "");
    if (DENIED_BLOCKS.has(bare)) fail("worldgen", at, "denied_block", `${st.block} is not allowed in generated worlds (operator / technical / griefing block)`);
    for (const m of blockStateProblems(st.block, st.properties, v)) fail("worldgen", at, "block_state", m);
  };

  // ---- dimension types + dimensions
  const dtRange = new Map<string, { minY: number; height: number }>();
  for (const { r, i } of of("dimension_type")) {
    const d = resolveDimensionType(r.dimensionType), at = `resources[${i}].dimensionType`;
    if (d.minY + d.height > 320) fail("worldgen", at, "dimension_height", `minY ${d.minY} + height ${d.height} is above 320; keep the dimension inside -64..320`);
    if ((r.dimensionType.logicalHeight ?? d.height) > d.height) warn("worldgen", `${at}.logicalHeight`, "logical_height", "logicalHeight is above height; it is clamped to height");
    dtRange.set(`${ns}:${r.id}`, { minY: d.minY, height: d.height });
  }
  const biomeUse = new Map<string, string[]>(); // biome -> dimensions
  for (const { r, i } of of("dimension")) {
    const at = `resources[${i}].dimension`, d = r.dimension;
    const dt = d.dimensionType;
    ref(`${at}.dimensionType`, dt, { own: own.dimension_type, ownKind: "dimension_type", vanilla: "dimension_type" });
    const range = nsOf(dt) === ns ? dtRange.get(dt) : VANILLA_DT[dt.replace(/^minecraft:/, "")];
    const useBiome = (p: string, b: string) => {
      ref(p, b, { own: own.biome, ownKind: "biome", ownOnly: "a custom dimension uses only this pack's own biomes (vanilla biomes are not edited or reused)" });
      biomeUse.set(b, [...(biomeUse.get(b) ?? []), `${ns}:${r.id}`]);
    };
    const g = d.generator;
    if (g.kind === "noise") {
      const n = wf.noise[g.terrain];
      if (!n) fail("vanilla_ids", `${at}.generator.terrain`, "unknown_noise", `the terrain preset ${g.terrain} does not exist in Minecraft ${v}`);
      else if (range && (range.minY > n.minY || range.minY + range.height < n.minY + n.height)) fail("worldgen", `${at}.generator.terrain`, "noise_range", `the ${g.terrain} terrain spans y ${n.minY}..${n.minY + n.height}, but the dimension type only spans ${range.minY}..${range.minY + range.height}; raise the dimension type's height or pick another terrain`);
      const bs = g.biomes;
      if (bs.kind === "fixed") useBiome(`${at}.generator.biomes.biome`, bs.biome);
      else if (bs.kind === "checkerboard") bs.biomes.forEach((b, j) => useBiome(`${at}.generator.biomes.biomes[${j}]`, b));
      else {
        const pts = new Set<string>();
        bs.biomes.forEach((b, j) => {
          useBiome(`${at}.generator.biomes.biomes[${j}].biome`, b.biome);
          for (const k of ["temperature", "humidity", "continentalness", "erosion", "weirdness", "depth"] as const) { const x = b[k]; if (Array.isArray(x) && x[0] > x[1]) fail("worldgen", `${at}.generator.biomes.biomes[${j}].${k}`, "climate_range", `${k} range [${x[0]}, ${x[1]}] has min > max`); }
          const key = JSON.stringify([b.temperature, b.humidity, b.continentalness, b.erosion, b.weirdness, b.depth, b.offset]);
          if (pts.has(key)) warn("worldgen", `${at}.generator.biomes.biomes[${j}]`, "climate_duplicate", "two biomes share the same climate point; only one of them can ever be picked");
          pts.add(key);
        });
      }
    } else {
      g.layers.forEach((l, j) => block(`${at}.generator.layers[${j}].block`, l.block));
      const total = g.layers.reduce((s, l) => s + l.height, 0);
      if (range && total > range.height) fail("worldgen", `${at}.generator.layers`, "flat_height", `the layers are ${total} blocks thick; the dimension is ${range.height} high`);
      useBiome(`${at}.generator.biome`, g.biome);
    }
  }
  if (of("dimension").length === 0) warn("worldgen", "resources", "no_dimension", "the pack has world generation but no dimension: its biomes, features and structures never generate (vanilla biomes are not edited)");

  // ---- biomes
  const featureKinds = new Map<string, DpConfiguredFeature>();
  for (const { r } of of("configured_feature")) featureKinds.set(`${ns}:${r.id}`, r.feature);
  const placedAttempts = new Map<string, { attempts: number; weight: number }>();
  const attemptsOf = (pl: DpPlacement[]) => {
    let a = 1, rarity = 1;
    for (const p of pl) { if (p.kind === "count") a *= typeof p.count === "number" ? p.count : Math.max(p.count.min, p.count.max); if (p.kind === "rarity") rarity *= p.chance; }
    return { a, rarity };
  };
  const kindWeight = (f: DpConfiguredFeature | undefined): number => (!f ? 1 : f.kind === "ore" ? f.size / 16 : f.kind === "tree" ? 1.5 : f.kind === "lake" ? 3 : f.kind === "patch" ? 0.05 : 0.05);
  for (const { r, i } of of("placed_feature")) {
    const at = `resources[${i}].placed`, p = r.placed;
    ref(`${at}.feature`, p.feature, { own: own.configured_feature, ownKind: "configured_feature", vanilla: "configured_feature" });
    const own0 = featureKinds.get(p.feature);
    const { a, rarity } = attemptsOf(p.placement);
    const tries = own0?.kind === "patch" ? own0.tries : 1;
    const attempts = a * tries;
    if (attempts > WORLDGEN_LIMITS.attemptsPerFeature) fail("limits", `${at}.placement`, "feature_attempts", `${attempts} placement attempts per chunk (count x patch tries); the limit is ${WORLDGEN_LIMITS.attemptsPerFeature}`);
    placedAttempts.set(`${ns}:${r.id}`, { attempts: attempts / rarity, weight: own0?.kind === "patch" ? 0.05 : kindWeight(own0) });
    p.placement.forEach((m, j) => {
      if (m.kind === "would_survive") block(`${at}.placement[${j}].block`, m.block);
      if (m.kind === "height_range" && "absolute" in m.min && "absolute" in m.max && m.min.absolute > m.max.absolute) fail("worldgen", `${at}.placement[${j}]`, "height_range", "height_range min is above max");
    });
    if (a > 1 && !p.placement.some((m) => m.kind === "in_square")) warn("worldgen", `${at}.placement`, "no_in_square", "without in_square every attempt lands on the same column at the chunk corner");
    if (!p.placement.some((m) => m.kind === "biome")) warn("worldgen", `${at}.placement`, "no_biome_filter", "vanilla ends placements with { kind: biome } so features never spill into a neighbouring biome");
  }
  const biomeCost = new Map<string, number>();
  for (const { r, i } of of("biome")) {
    const at = `resources[${i}].biome`, b = r.biome, full = `${ns}:${r.id}`;
    if (b.music) ref(`${at}.music.sound`, b.music.sound, { vanilla: "sound_event" });
    if (b.ambientLoop) ref(`${at}.ambientLoop`, b.ambientLoop, { vanilla: "sound_event" });
    if (b.mood) ref(`${at}.mood`, b.mood, { vanilla: "sound_event" });
    if (b.additions) ref(`${at}.additions.sound`, b.additions.sound, { vanilla: "sound_event" });
    if (b.particle && !isVanilla("particle_type", b.particle.type, v)) fail("vanilla_ids", `${at}.particle.type`, "unknown_vanilla_id", missingIdReason("particle_type", `minecraft:${b.particle.type}`, v));
    if (b.colors.dryFoliage && !wf.dryFoliage) warn("worldgen", `${at}.colors.dryFoliage`, "version_ignored", `dry foliage colour needs Minecraft 1.21.5+; it is left out for ${v}`);
    (b.spawns ?? []).forEach((s, j) => {
      const p = `${at}.spawns[${j}]`;
      ref(`${p}.entity`, s.entity, { vanilla: "entity_type" });
      if (!SPAWNABLE.has(s.entity.replace(/^minecraft:/, ""))) fail("worldgen", `${p}.entity`, "not_spawnable", `${s.entity} is not on the natural-spawn list (no bosses, players, projectiles or technical entities)`);
      if (s.min > s.max) warn("worldgen", p, "spawn_count_order", "min is above max (they are swapped)");
    });
    const seen = new Set<string>();
    let cost = 0, attempts = 0;
    (b.features ?? []).forEach((f, j) => {
      const p = `${at}.features[${j}].feature`;
      ref(p, f.feature, { own: own.placed_feature, ownKind: "placed_feature", vanilla: "placed_feature" });
      if (seen.has(`${f.step}|${f.feature}`)) warn("worldgen", p, "duplicate_feature", `${f.feature} is listed twice in ${f.step} (kept once)`);
      seen.add(`${f.step}|${f.feature}`);
      const pa = placedAttempts.get(f.feature) ?? { attempts: 4, weight: 1 }; // vanilla placed feature: flat estimate
      attempts += pa.attempts; cost += pa.attempts * pa.weight;
    });
    if (attempts > WORLDGEN_LIMITS.attemptsPerBiome) fail("limits", `${at}.features`, "biome_attempts", `about ${Math.round(attempts)} feature attempts per chunk; the limit is ${WORLDGEN_LIMITS.attemptsPerBiome} per biome`);
    (b.carvers ?? []).forEach((c, j) => ref(`${at}.carvers[${j}]`, c, { vanilla: "configured_carver" }));
    biomeCost.set(full, cost);
    if (!biomeUse.has(full)) warn("worldgen", at, "unused_biome", `${full} is not used by any dimension of this pack, so it never generates`);
  }
  // feature order cycles (Minecraft's FeatureSorter refuses the whole biome source)
  for (const { r, i } of of("dimension")) {
    const biomes = [...biomeUse].filter(([, ds]) => ds.includes(`${ns}:${r.id}`)).map(([b]) => b);
    const cyc = featureCycle(biomes.map((b) => spec.resources.find((x) => x.type === "biome" && `${ns}:${x.id}` === b) as R<"biome"> | undefined).filter((x): x is R<"biome"> => !!x));
    if (cyc) fail("worldgen", `resources[${i}].dimension`, "feature_order_cycle", `the biomes of this dimension list ${cyc.join(" and ")} in different orders; Minecraft refuses to start ("Feature order cycle found"). Use one order in every biome`);
  }
  // ---- configured features
  for (const { r, i } of of("configured_feature")) {
    const at = `resources[${i}].feature`, f = r.feature;
    if (f.kind === "ore") f.targets.forEach((t, j) => { block(`${at}.targets[${j}].block`, t.block); ref(`${at}.targets[${j}].replace`, t.replace, { vanilla: "block", vanillaTag: "tag/block" }); });
    if (f.kind === "tree") { block(`${at}.trunk`, f.trunk); block(`${at}.foliage`, f.foliage); if (f.dirt) block(`${at}.dirt`, f.dirt); }
    if (f.kind === "patch") f.blocks.forEach((x, j) => block(`${at}.blocks[${j}].block`, x.block));
    if (f.kind === "lake") block(`${at}.barrier`, f.barrier);
    if (f.kind === "block") block(`${at}.block`, f.block);
  }
  // ---- templates
  const templates: WorldgenSummary["templates"] = [];
  const tplBlocks = new Map<string, number>();
  for (const { r, i } of of("structure_template")) {
    const at = `resources[${i}].template`, t = r.template;
    const issues = templateShapeIssues(t);
    for (const x of issues) (/never used/.test(x.message) ? warn : fail)(/limit/.test(x.message) ? "limits" : "worldgen", `${at}.${x.at}`, "template_shape", x.message);
    for (const [k, p] of Object.entries(t.palette)) {
      block(`${at}.palette.${k}`, { block: p.block, properties: p.properties });
      if (p.loot) ref(`${at}.palette.${k}.loot`, p.loot, { own: own.loot_table, ownKind: "loot_table", ownOnly: "a template chest uses one of this pack's own loot tables" });
    }
    let blocks = 0; for (const l of t.layers) for (const row of l) for (const ch of row) if (ch !== ".") blocks++;
    templates.push({ id: `${ns}:${r.id}`, blocks, volume: t.size[0] * t.size[1] * t.size[2] });
    tplBlocks.set(`${ns}:${r.id}`, blocks);
  }
  // ---- structures + sets
  const inSet = new Set<string>();
  for (const { r, i } of of("structure_set")) {
    const at = `resources[${i}].structureSet`, s = r.structureSet;
    if (s.separation >= s.spacing) fail("worldgen", `${at}.separation`, "separation", `separation (${s.separation}) must be smaller than spacing (${s.spacing})`);
    s.structures.forEach((x, j) => { ref(`${at}.structures[${j}].structure`, x.structure, { own: own.structure, ownKind: "structure", ownOnly: "a structure set places only this pack's own structures" }); inSet.add(x.structure); });
  }
  const salts = of("structure_set").map((x) => x.r.structureSet.salt);
  if (new Set(salts).size !== salts.length) warn("worldgen", "resources", "salt_reuse", "two structure sets share a salt: they will pick the same chunks");
  for (const { r, i } of of("structure")) {
    const at = `resources[${i}].structure`, s = r.structure, full = `${ns}:${r.id}`;
    ref(`${at}.template`, s.template, { own: own.structure_template, ownKind: "structure_template", ownOnly: "a structure uses one of this pack's own templates" });
    s.biomes.forEach((b, j) => {
      ref(`${at}.biomes[${j}]`, b, { own: own.biome, ownKind: "biome", ownOnly: "structures are placed only in this pack's own biomes" });
      if (own.biome.has(b) && !biomeUse.has(b)) warn("worldgen", `${at}.biomes[${j}]`, "unused_biome", `${b} is in no dimension, so the structure never generates there`);
    });
    if (!inSet.has(full)) warn("worldgen", at, "no_structure_set", `${full} is in no structure_set, so it never generates on its own (place structure still works)`);
  }

  // ---- cost
  const cost: WorldgenCost = { score: 0, class: "low", perDimension: [], notes: [] };
  for (const { r } of of("dimension")) {
    const g = r.dimension.generator, id = `${ns}:${r.id}`;
    const terrain = g.kind === "flat" ? 1 : TERRAIN_COST[g.terrain] ?? 10;
    const biomes = [...biomeUse].filter(([, ds]) => ds.includes(id)).map(([b]) => b);
    const features = g.kind === "flat" && g.features === false ? 0 : Math.max(0, ...biomes.map((b) => biomeCost.get(b) ?? 0)) * 0.5;
    let structures = 0;
    for (const { r: set } of of("structure_set")) {
      const ss = set.structureSet;
      const members = ss.structures.map((x) => spec.resources.find((y) => y.type === "structure" && `${ns}:${y.id}` === x.structure) as R<"structure"> | undefined).filter((x): x is R<"structure"> => !!x && x.structure.biomes.some((b) => biomes.includes(b)));
      if (!members.length) continue;
      const avg = members.reduce((s, m) => s + (tplBlocks.get(m.structure.template) ?? 0), 0) / members.length;
      structures += (avg / 500) * (64 / (ss.spacing * ss.spacing)) * (ss.frequency ?? 1);
    }
    const total = Math.round((terrain + features + structures) * 10) / 10;
    cost.perDimension.push({ id, terrain, features: Math.round(features * 10) / 10, structures: Math.round(structures * 100) / 100, total });
  }
  cost.score = Math.max(0, ...cost.perDimension.map((d) => d.total));
  cost.class = cost.score > WORLDGEN_LIMITS.maxCost ? "refused" : cost.score > 40 ? "high" : cost.score > 20 ? "medium" : "low";
  cost.notes.push("heuristic per-chunk cost: 1 = a superflat chunk, 10 = vanilla overworld terrain; calibrated against node-2 Test Flight chunk generation (docs: Cyrus worldgen (R4))");
  if (cost.class === "refused") fail("limits", "resources", "worldgen_cost", `the estimated generation cost is ${cost.score} per chunk; the limit is ${WORLDGEN_LIMITS.maxCost} (fewer feature attempts, smaller or rarer structures)`);
  else if (cost.class === "high") warn("limits", "resources", "worldgen_cost", `the estimated generation cost is ${cost.score} per chunk (high): exploring the dimension will load the server noticeably`);

  const types: Record<string, number> = {};
  for (const { r } of wgIdx) types[r.type] = (types[r.type] ?? 0) + 1;
  return { types, dimensions: [...ids("dimension")].sort(), biomes: [...own.biome].sort(), structures: [...own.structure].sort(), templates, cost };
}

/** A pair of features listed in opposite orders by two biomes of the same biome source (null = no cycle). */
export function featureCycle(biomes: R<"biome">[]): string[] | null {
  // nodes = (step, feature); edges = consecutive entries of one step in one biome (vanilla FeatureSorter)
  const edges = new Map<string, Set<string>>();
  for (const b of biomes) {
    for (const step of DECORATION_STEPS) {
      const list = [...new Set((b.biome.features ?? []).filter((f) => f.step === step).map((f) => `${step}|${f.feature}`))];
      for (let k = 0; k + 1 < list.length; k++) { if (!edges.has(list[k])) edges.set(list[k], new Set()); edges.get(list[k])!.add(list[k + 1]); }
    }
  }
  const state = new Map<string, 1 | 2>();
  let found: string[] | null = null;
  const dfs = (n: string, stack: string[]): void => {
    if (found) return;
    state.set(n, 1);
    for (const m of edges.get(n) ?? []) {
      if (state.get(m) === 1) { found = [n.split("|")[1], m.split("|")[1]]; return; }
      if (!state.has(m)) dfs(m, [...stack, m]);
    }
    state.set(n, 2);
  };
  for (const n of [...edges.keys()].sort()) if (!state.has(n)) dfs(n, [n]);
  return found;
}

