// Cyrus R4 worldgen: STATIC checks of worldgen FILES (what ./emit.ts wrote, or a raw hand-written file), per version:
//   mcdoc_fields  unknown / missing keys of biomes, biome effects, dimension types, dimensions, configured + placed
//                 features (the subset's feature and placement types), jigsaw structures, structure sets and
//                 template pools, against the vanilla-mcdoc tables (../mcdoc.ts)
//   value_shapes  the version shifts that break worldgen silently: colours int vs "#rrggbb" (1.21.11), biome sounds /
//                 music / particles in effects vs environment attributes (1.21.11), carvers map vs list (1.21.2),
//                 music single vs weighted (1.21.4), dimension_type classic fields vs attributes (1.21.11)
//   vanilla_ids   feature / placement / structure / pool element / biome source / generator TYPES exist in the
//                 version's registries (random_patch is gone in 26.1), vanilla noise presets, placed features,
//                 sound events, environment attribute ids
//   structure NBT a `.nbt` template must parse (gzip + NBT), carry DataVersion / size / palette / blocks, stay inside
//                 the size cap, use existing blocks and only valid palette indexes inside the size
// Pure. Only used for files of packs that carry world generation (the studio passes { worldgen: true }).
import { checkKeys, dispatchFields, structFields, type FieldTable } from "../mcdoc";
import { isVanilla, type IdKind } from "../versions";
import { nbtGet, readNbt, type Nbt } from "./nbt";
import { WORLDGEN_LIMITS } from "./spec";
import { worldgenFeatures, type WorldgenFeatures } from "./versions";

type Fail = (check: string, message: string) => void;
type Ctx = { at: string; v: string; wf: WorldgenFeatures; fail: Fail; warn: Fail };
const isObj = (x: unknown): x is Record<string, unknown> => !!x && typeof x === "object" && !Array.isArray(x);
const bare = (s: string) => s.replace(/^#/, "").replace(/^minecraft:/, "");

function keys(ctx: Ctx, where: string, obj: Record<string, unknown>, t: FieldTable | null, ignore: string[] = []) {
  const r = checkKeys(obj, t, ignore);
  for (const k of r.unknown) ctx.fail("mcdoc_fields", `${ctx.at}: ${where} has the key "${k}", which Minecraft ${ctx.v} does not know`);
  for (const k of r.missing) ctx.fail("mcdoc_fields", `${ctx.at}: ${where} is missing the required key "${k}" for Minecraft ${ctx.v}`);
}
/** Union of tables (a struct whose tail is a dispatched spread we resolve ourselves, e.g. Structure + jigsaw). */
function union(...ts: (FieldTable | null)[]): FieldTable | null {
  const real = ts.filter((t): t is FieldTable => !!t);
  if (!real.length) return null;
  const out: FieldTable = { fields: new Map(), open: false };
  for (const t of real) for (const [k, f] of t.fields) out.fields.set(k, { required: f.required || !!out.fields.get(k)?.required });
  return out;
}
function vid(ctx: Ctx, kind: IdKind, id: unknown, what: string) {
  if (typeof id !== "string") return ctx.fail("value_shapes", `${ctx.at}: ${what} must be an id string`);
  if (id.replace(/^#/, "").startsWith("minecraft:") || !id.includes(":")) {
    if (!isVanilla(kind, id, ctx.v)) ctx.fail("vanilla_ids", `${ctx.at}: ${what} ${id} does not exist in Minecraft ${ctx.v}`);
  }
}
function colour(ctx: Ctx, x: unknown, where: string) {
  if (x === undefined) return;
  if (ctx.wf.biome === "attributes") { if (typeof x !== "string" || !/^#[0-9a-fA-F]{6}$/.test(x)) ctx.fail("value_shapes", `${ctx.at}: ${where} must be a "#rrggbb" string from Minecraft 1.21.11 (is ${JSON.stringify(x)})`); }
  else if (typeof x !== "number" || !Number.isInteger(x)) ctx.fail("value_shapes", `${ctx.at}: ${where} must be an integer colour before Minecraft 1.21.11 (is ${JSON.stringify(x)})`);
}

function checkBiome(j: Record<string, unknown>, ctx: Ctx) {
  keys(ctx, "the biome", j, dispatchFields("resource/worldgen/biome", ctx.v));
  const e = j.effects;
  if (!isObj(e)) return ctx.fail("mcdoc_fields", `${ctx.at}: a biome needs "effects"`);
  keys(ctx, "effects", e, structFields("BiomeEffects", ctx.v));
  for (const k of ["sky_color", "fog_color", "water_color", "water_fog_color", "grass_color", "foliage_color", "dry_foliage_color"]) colour(ctx, e[k], `effects.${k}`);
  if (ctx.wf.biome === "effects") {
    if (e.music !== undefined) {
      const weighted = Array.isArray(e.music);
      if (ctx.wf.music === "weighted" && !weighted) ctx.fail("value_shapes", `${ctx.at}: effects.music is a weighted list [{data, weight}] from Minecraft 1.21.4`);
      if (ctx.wf.music === "single" && weighted) ctx.fail("value_shapes", `${ctx.at}: effects.music is a single object before Minecraft 1.21.4`);
      for (const m of weighted ? (e.music as unknown[]).map((x) => (isObj(x) ? x.data : x)) : [e.music]) if (isObj(m)) vid(ctx, "sound_event", m.sound, "music sound");
    }
    for (const k of ["ambient_sound"]) if (e[k] !== undefined) vid(ctx, "sound_event", e[k], `effects.${k}`);
    for (const k of ["mood_sound", "additions_sound"]) if (isObj(e[k])) vid(ctx, "sound_event", (e[k] as Record<string, unknown>).sound, `effects.${k}.sound`);
    if (isObj(e.particle) && isObj(e.particle.options)) vid(ctx, "particle_type", e.particle.options.type, "effects.particle");
  } else if (isObj(j.attributes)) {
    for (const [k, x] of Object.entries(j.attributes)) {
      vid(ctx, "environment_attribute", k, "attribute");
      if (/_color$/.test(k)) colour(ctx, x, `attributes.${k}`);
    }
    const bm = j.attributes["minecraft:audio/background_music"];
    if (isObj(bm) && isObj(bm.default)) vid(ctx, "sound_event", bm.default.sound, "background music");
  }
  if (ctx.wf.carvers === "map" && Array.isArray(j.carvers)) ctx.fail("value_shapes", `${ctx.at}: carvers are a map {"air": [...]} before Minecraft 1.21.2`);
  if (ctx.wf.carvers === "list" && isObj(j.carvers)) ctx.fail("value_shapes", `${ctx.at}: carvers are a list (or tag) from Minecraft 1.21.2`);
  for (const c of Array.isArray(j.carvers) ? j.carvers : isObj(j.carvers) ? Object.values(j.carvers).flat() : []) vid(ctx, "configured_carver", c, "carver");
  if (!Array.isArray(j.features) || j.features.length > 11 || j.features.some((s) => !Array.isArray(s))) ctx.fail("value_shapes", `${ctx.at}: features must be a list of up to 11 lists (one per decoration step)`);
  else for (const s of j.features as unknown[][]) for (const f of s) vid(ctx, "placed_feature", f, "feature");
  if (isObj(j.spawners)) for (const list of Object.values(j.spawners)) if (Array.isArray(list)) for (const s of list) { if (isObj(s)) { keys(ctx, "a spawner", s, structFields("SpawnerData", ctx.v), ["weight"]); vid(ctx, "entity_type", s.type, "spawner type"); } }
}

function checkDimensionType(j: Record<string, unknown>, ctx: Ctx) {
  keys(ctx, "the dimension type", j, dispatchFields("resource/dimension_type", ctx.v));
  for (const k of ["min_y", "height"]) if (typeof j[k] === "number" && (j[k] as number) % 16 !== 0) ctx.fail("value_shapes", `${ctx.at}: ${k} must be a multiple of 16`);
  if (isObj(j.attributes)) for (const k of Object.keys(j.attributes)) vid(ctx, "environment_attribute", k, "attribute");
}

function checkDimension(j: Record<string, unknown>, ctx: Ctx) {
  keys(ctx, "the dimension", j, dispatchFields("resource/dimension", ctx.v));
  const g = j.generator;
  if (!isObj(g) || typeof g.type !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: a dimension needs a generator with a type`);
  vid(ctx, "worldgen/chunk_generator", g.type, "generator type");
  keys(ctx, "the generator", g, dispatchFields(`chunk_generator/${bare(g.type)}`, ctx.v), ["type"]);
  if (bare(g.type) === "noise") {
    if (typeof g.settings === "string") vid(ctx, "noise_settings", g.settings, "noise settings");
    else ctx.fail("value_shapes", `${ctx.at}: Cyrus dimensions use a vanilla noise_settings preset id, not inline noise settings`);
    const bs = g.biome_source;
    if (!isObj(bs) || typeof bs.type !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: the noise generator needs a biome_source with a type`);
    vid(ctx, "worldgen/biome_source", bs.type, "biome source type");
    keys(ctx, "the biome source", bs, dispatchFields(`biome_source/${bare(bs.type)}`, ctx.v), ["type"]);
  }
  if (bare(g.type) === "flat" && isObj(g.settings)) {
    keys(ctx, "the flat settings", g.settings, structFields("FlatGeneratorSettings", ctx.v));
    for (const l of Array.isArray(g.settings.layers) ? g.settings.layers : []) if (isObj(l)) vid(ctx, "block", l.block, "layer block");
  }
}

function checkConfigured(j: Record<string, unknown>, ctx: Ctx) {
  keys(ctx, "the configured feature", j, dispatchFields("resource/worldgen/configured_feature", ctx.v));
  if (typeof j.type !== "string") return;
  vid(ctx, "worldgen/feature", j.type, "feature type");
  const t = dispatchFields(`feature_config/${bare(j.type)}`, ctx.v);
  if (t && isObj(j.config)) keys(ctx, `config (${j.type})`, j.config, t);
}

function checkPlaced(j: Record<string, unknown>, ctx: Ctx) {
  keys(ctx, "the placed feature", j, dispatchFields("resource/worldgen/placed_feature", ctx.v));
  if (typeof j.feature === "string") vid(ctx, "configured_feature", j.feature, "feature");
  for (const [i, m] of (Array.isArray(j.placement) ? j.placement : []).entries()) {
    if (!isObj(m) || typeof m.type !== "string") { ctx.fail("mcdoc_fields", `${ctx.at}: placement[${i}] needs a type`); continue; }
    vid(ctx, "worldgen/placement_modifier_type", m.type, `placement[${i}] type`);
    const t = dispatchFields(`placement_modifier/${bare(m.type)}`, ctx.v);
    if (t) keys(ctx, `placement[${i}] (${m.type})`, m, t, ["type"]);
    else if (["in_square", "biome"].includes(bare(m.type)) && Object.keys(m).length > 1) ctx.fail("mcdoc_fields", `${ctx.at}: placement[${i}] (${m.type}) takes no fields`);
  }
}

function checkStructure(j: Record<string, unknown>, ctx: Ctx) {
  if (typeof j.type !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: a structure needs a type`);
  vid(ctx, "worldgen/structure_type", j.type, "structure type");
  const base = dispatchFields("resource/worldgen/structure", ctx.v);
  const st = structFields("Structure", ctx.v);
  if (bare(j.type) === "jigsaw") keys(ctx, "the jigsaw structure", j, union(st, dispatchFields("structure_config/jigsaw", ctx.v)));
  else keys(ctx, "the structure", j, base);
}

function checkStructureSet(j: Record<string, unknown>, ctx: Ctx) {
  keys(ctx, "the structure set", j, dispatchFields("resource/worldgen/structure_set", ctx.v));
  const p = j.placement;
  if (!isObj(p) || typeof p.type !== "string") return ctx.fail("mcdoc_fields", `${ctx.at}: a structure set needs a placement with a type`);
  vid(ctx, "worldgen/structure_placement", p.type, "placement type");
  const t = dispatchFields(`structure_placement/${bare(p.type)}`, ctx.v);
  if (t) keys(ctx, `placement (${p.type})`, p, t, ["type"]);
  if (typeof p.spacing === "number" && typeof p.separation === "number" && p.separation >= p.spacing) ctx.fail("value_shapes", `${ctx.at}: separation must be smaller than spacing (Minecraft refuses the set)`);
  for (const s of Array.isArray(j.structures) ? j.structures : []) if (isObj(s)) keys(ctx, "a structure entry", s, structFields("StructureSetElement", ctx.v));
}

function checkTemplatePool(j: Record<string, unknown>, ctx: Ctx) {
  keys(ctx, "the template pool", j, dispatchFields("resource/worldgen/template_pool", ctx.v));
  for (const [i, w] of (Array.isArray(j.elements) ? j.elements : []).entries()) {
    if (!isObj(w) || !isObj(w.element)) { ctx.fail("mcdoc_fields", `${ctx.at}: elements[${i}] needs an element`); continue; }
    keys(ctx, `elements[${i}]`, w, structFields("WeightedElement", ctx.v));
    const el = w.element;
    if (typeof el.element_type !== "string") { ctx.fail("mcdoc_fields", `${ctx.at}: elements[${i}] needs element_type`); continue; }
    vid(ctx, "worldgen/structure_pool_element", el.element_type, `elements[${i}] element_type`);
    const t = dispatchFields(`template_pool_element/${bare(el.element_type)}`, ctx.v);
    if (t) keys(ctx, `elements[${i}].element`, el, t, ["element_type"]);
  }
}

/** A structure template file: parse + structural checks. Returns the block count (or null when unreadable). */
export function checkTemplateNbt(data: Uint8Array, ctx: Ctx): number | null {
  let root: Nbt;
  try { root = readNbt(data).root; } catch (e) { ctx.fail("mcdoc_fields", `${ctx.at}: not a readable structure file (${(e as Error).message.slice(0, 80)})`); return null; }
  const dv = nbtGet(root, "DataVersion");
  if (dv?.t !== "int") ctx.fail("mcdoc_fields", `${ctx.at}: structure file has no DataVersion`);
  else if (dv.v > ctx.wf.dataVersion) ctx.fail("value_shapes", `${ctx.at}: DataVersion ${dv.v} is newer than Minecraft ${ctx.v} (${ctx.wf.dataVersion}); the server cannot load it`);
  const size = nbtGet(root, "size"), palette = nbtGet(root, "palette"), blocks = nbtGet(root, "blocks");
  const dims = size?.t === "list" && size.v.length === 3 && size.v.every((x) => x.t === "int") ? size.v.map((x) => (x as { v: number }).v) : null;
  if (!dims) { ctx.fail("mcdoc_fields", `${ctx.at}: structure file needs size [x, y, z]`); return null; }
  if (dims.some((d) => d < 1 || d > WORLDGEN_LIMITS.templateSide)) ctx.fail("value_shapes", `${ctx.at}: size ${dims.join("x")} is outside 1..${WORLDGEN_LIMITS.templateSide} per side`);
  if (palette?.t !== "list" || blocks?.t !== "list") { ctx.fail("mcdoc_fields", `${ctx.at}: structure file needs palette and blocks lists`); return null; }
  palette.v.forEach((p, i) => { const n = nbtGet(p, "Name"); if (n?.t !== "string") ctx.fail("mcdoc_fields", `${ctx.at}: palette[${i}] has no Name`); else vid(ctx, "block", n.v, `palette[${i}]`); });
  if (blocks.v.length > WORLDGEN_LIMITS.templateBlocks) ctx.fail("value_shapes", `${ctx.at}: ${blocks.v.length} blocks; the limit is ${WORLDGEN_LIMITS.templateBlocks}`);
  let bad = 0;
  for (const b of blocks.v) {
    const pos = nbtGet(b, "pos"), st = nbtGet(b, "state");
    const ok = pos?.t === "list" && pos.v.length === 3 && pos.v.every((x, k) => x.t === "int" && x.v >= 0 && x.v < dims[k]) && st?.t === "int" && st.v >= 0 && st.v < palette.v.length;
    if (!ok) bad++;
  }
  if (bad) ctx.fail("value_shapes", `${ctx.at}: ${bad} block entries are outside the size or point at a missing palette row`);
  return blocks.v.length;
}

/** Judge one worldgen file. `type` is the data folder ("worldgen/biome", "dimension_type", "dimension", "structure" for .nbt). */
export function checkWorldgenFile(type: string, file: { text: string; data?: Uint8Array }, at: string, version: string, fail: Fail, warn: Fail): boolean {
  const wfr = worldgenFeatures(version);
  if (!wfr.ok) { fail("mcmeta", wfr.error); return true; }
  const ctx: Ctx = { at, v: version, wf: wfr.features, fail, warn };
  if (type === "structure") { checkTemplateNbt(file.data ?? Buffer.from(file.text, "latin1"), ctx); return true; }
  const fns: Record<string, (j: Record<string, unknown>, c: Ctx) => void> = {
    "worldgen/biome": checkBiome, dimension_type: checkDimensionType, dimension: checkDimension, "worldgen/configured_feature": checkConfigured,
    "worldgen/placed_feature": checkPlaced, "worldgen/structure": checkStructure, "worldgen/structure_set": checkStructureSet, "worldgen/template_pool": checkTemplatePool,
  };
  const fn = fns[type];
  if (!fn) return false;
  let j: unknown;
  try { j = JSON.parse(file.text.replace(/^\uFEFF/, "")); } catch (e) { fail("mcdoc_fields", `${at}: not valid JSON (${(e as Error).message.slice(0, 80)})`); return true; }
  if (!isObj(j)) { fail("mcdoc_fields", `${at}: must be a JSON object`); return true; }
  fn(j, ctx);
  return true;
}

/** data/<ns>/<worldgen folder>/<path>.(json|nbt) -> the folder type, or null for a non-worldgen path. */
export function worldgenPath(p: string): { ns: string; type: string; id: string } | null {
  let m = /^data\/([a-z0-9_.-]+)\/worldgen\/([a-z_]+)\/([a-z0-9_./-]+)\.json$/.exec(p);
  if (m) return { ns: m[1], type: `worldgen/${m[2]}`, id: `${m[1]}:${m[3]}` };
  m = /^data\/([a-z0-9_.-]+)\/(dimension|dimension_type)\/([a-z0-9_./-]+)\.json$/.exec(p);
  if (m) return { ns: m[1], type: m[2], id: `${m[1]}:${m[3]}` };
  m = /^data\/([a-z0-9_.-]+)\/structure\/([a-z0-9_./-]+)\.nbt$/.exec(p);
  if (m) return { ns: m[1], type: "structure", id: `${m[1]}:${m[2]}` };
  return null;
}

