// REAL world generation load tests on node-2 through Test Flight (not part of the unit suite: it boots real Paper
// servers and generates chunks).
//   scripts/devhost run -- npx tsx test/cyrus-worldgen-real.ts [showcase|broken|all] [--versions 1.21.11,26.2] [--out file.json] --local
// showcase: the emitted worldgen showcase (test/fixtures/cyrus-worldgen/showcase.json) on a FRESH tiny world per
//   version, structure generation on: the pack is enabled; the two custom dimensions exist (forceload in each); 25
//   chunks generate in the noise dimension, the flat dimension and (baseline) the vanilla nether, timed by polling
//   `execute if loaded` on the area's corners; terrain height probe (a marker summoned at the surface); `locate biome`
//   for both own biomes; `locate structure` (needs the template to load); `place template` -> the chest is there
//   with the pack's loot table; `place structure`; `place feature` (ore); the flat layers are where they should be;
//   the server log after Done has no exception / error lines; clean stop. Boot time, RSS per step, region files.
// broken: RAW hand-written worldgen files with version-wrong / invalid content: the static validator rejects each,
//   and the real server must reject them too (registry load errors in the log, or it refuses to start).
import { spawn } from "node:child_process";
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck, TestFlightSpec } from "../lib/cyrus/testflight/types";
import { buildDataPack } from "../lib/cyrus/datapack/emit";
import { validatePackFiles, type PackFile } from "../lib/cyrus/datapack/validate";
import { dataPackFeatures } from "../lib/cyrus/datapack/versions";
import { zip } from "../lib/cyrus/textures/zip";

const NS = "nx_worldg01";
const TF_ROOT = "/tank/nxeon-build/tmp/testflight";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
const REMOTE = process.argv.includes("--local") ? localRemote : undefined;

async function fly(spec: TestFlightSpec, label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: REMOTE });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

/** Kept run dir: post-Done log problems, worldgen log lines, region files per dimension folder; then delete it. */
function harvest(runId: string | null): { afterDoneProblems: string[]; worldgenLines: string[]; regions: Record<string, { files: number; bytes: number }> } {
  const out = { afterDoneProblems: [] as string[], worldgenLines: [] as string[], regions: {} as Record<string, { files: number; bytes: number }> };
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF_ROOT, "runs", runId);
  const log = path.join(dir, "logs/latest.log");
  if (existsSync(log)) {
    let done = false;
    for (const line of readFileSync(log, "utf8").split("\n")) {
      if (/Done \(/.test(line)) { done = true; continue; }
      if (/nx_worldg01|nx_broken02|worldgen|dimension|Feature order|registry|Registry/i.test(line)) out.worldgenLines.push(line.slice(0, 300));
      if (done && /ERROR|Exception|Caused by|Couldn't|Failed to|FATAL/.test(line) && !/Stopping|Saving/.test(line)) out.afterDoneProblems.push(line.slice(0, 300));
    }
  }
  const walk = (d: string, depth: number) => {
    if (depth > 6 || !existsSync(d)) return;
    for (const e of readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) { if (e.name === "region") { const files = readdirSync(p).filter((f) => f.endsWith(".mca")); out.regions[path.relative(dir, p)] = { files: files.length, bytes: files.reduce((s, f) => s + statSync(path.join(p, f)).size, 0) }; } else walk(p, depth + 1); }
    }
  };
  walk(dir, 0);
  rmSync(dir, { recursive: true, force: true });
  return { ...out, worldgenLines: out.worldgenLines.slice(0, 40), afterDoneProblems: out.afterDoneProblems.slice(0, 30) };
}

const AREA = "-32 -32 47 47"; // 5 x 5 chunks
const corners = (dim: string) => `execute in ${dim} if loaded -32 0 -32 if loaded 47 0 47 if loaded -32 0 47 if loaded 47 0 -32 if loaded 8 0 8`;
const POLLS = 40, POLL_MS = 250;
const polls = (dim: string, tag: string): RconCheck[] => Array.from({ length: POLLS }, (_, i) => ({ id: `${tag}-poll-${i + 1}`, command: corners(dim), expect: ["Test passed"], waitMs: POLL_MS, required: false }));
const D = `${NS}:crystal`, F = `${NS}:flatland`;

const SHOWCASE_RCON: RconCheck[] = [
  { id: "crystal-forceload", command: `execute in ${D} run forceload add ${AREA}`, expect: [D] },
  ...polls(D, "crystal"),
  { id: "crystal-all-loaded", command: corners(D), expect: ["Test passed"], waitMs: 2000 },
  { id: "crystal-surface-probe", command: `execute in ${D} positioned 8 0 8 positioned over world_surface run summon minecraft:marker ~ ~ ~ {Tags:["cyrus_probe"]}`, expectNot: ["Unknown", "Invalid", "not loaded"] },
  { id: "crystal-surface-height", command: "data get entity @e[type=minecraft:marker,tag=cyrus_probe,limit=1] Pos", expect: ["Pos"] },
  { id: "crystal-biome-here", command: `execute in ${D} positioned 8 70 8 if biome ~ ~ ~ ${NS}:crystal_plains`, required: false },
  { id: "locate-biome-plains", command: `execute in ${D} run locate biome ${NS}:crystal_plains`, expect: [`${NS}:crystal_plains`], expectNot: ["Could not find"] },
  { id: "locate-biome-hills", command: `execute in ${D} run locate biome ${NS}:amethyst_hills`, expect: [`${NS}:amethyst_hills`], expectNot: ["Could not find"] },
  { id: "locate-structure", command: `execute in ${D} run locate structure ${NS}:ruin`, expect: [`${NS}:ruin`], expectNot: ["Could not find", "no structure"] },
  { id: "place-template", command: `execute in ${D} run place template ${NS}:ruin 0 200 0`, expectNot: ["Unknown", "not loaded", "Invalid", "Failed", "not found"] },
  { id: "template-chest-placed", command: `execute in ${D} if block 3 201 3 minecraft:chest`, expect: ["Test passed"] },
  { id: "template-chest-loot", command: `execute in ${D} run data get block 3 201 3 LootTable`, expect: [`${NS}:chests/ruin`] },
  { id: "template-roof", command: `execute in ${D} if block 3 204 3 minecraft:glowstone`, expect: ["Test passed"] },
  { id: "template-void-kept", command: `execute in ${D} if block 0 204 0 minecraft:air`, expect: ["Test passed"] },
  { id: "place-structure", command: `execute in ${D} run place structure ${NS}:ruin 8 64 8`, expectNot: ["Unknown", "not loaded", "Invalid", "Failed", "not found"] },
  { id: "place-feature-ore", command: `execute in ${D} run place feature ${NS}:amethyst_ore 8 -20 8`, expectNot: ["Unknown", "Invalid", "not found"], required: false },
  { id: "flat-forceload", command: `execute in ${F} run forceload add ${AREA}`, expect: [F] },
  ...polls(F, "flat"),
  { id: "flat-all-loaded", command: corners(F), expect: ["Test passed"], waitMs: 1000 },
  { id: "flat-grass-layer", command: `execute in ${F} if block 8 6 8 minecraft:grass_block`, expect: ["Test passed"] },
  { id: "flat-bedrock-layer", command: `execute in ${F} if block 8 0 8 minecraft:bedrock`, expect: ["Test passed"] },
  { id: "flat-locate-biome", command: `execute in ${F} run locate biome ${NS}:crystal_plains`, expect: [`${NS}:crystal_plains`] },
  { id: "nether-forceload", command: `execute in minecraft:the_nether run forceload add ${AREA}`, required: false },
  ...polls("minecraft:the_nether", "nether"),
  { id: "pack-function", command: `function ${NS}:go_crystal`, expectNot: ["Unknown function", "Can't find"] },
];

/** First poll index that passed -> approximate wall time for 25 chunks (the per-command ms comes from runner tf-lite-3). */
function pollTime(evidence: string[], tag: string): { polls: number | null; approxMs: number | null; rssMb: number | null } {
  let total = 0;
  for (let i = 1; i <= POLLS; i++) {
    const line = evidence.find((e) => e.startsWith(`${tag}-poll-${i} `));
    if (!line) return { polls: null, approxMs: null, rssMb: null };
    const ms = Number((/, (\d+) ms\]/.exec(line) ?? [])[1] ?? 0);
    total += POLL_MS + ms;
    if (/: ok/.test(line)) return { polls: i, approxMs: total, rssMb: Number((/\[rss (\d+) MB/.exec(line) ?? [])[1] ?? 0) };
  }
  return { polls: null, approxMs: null, rssMb: null };
}

/** RAW broken worldgen files (each one the validator must reject, and the server too). */
export function brokenWorldgenFiles(version: string): PackFile[] {
  const fe = dataPackFeatures(version);
  if (!fe.ok) throw new Error(fe.error);
  const { major, minor } = fe.features.format;
  const mcmeta = fe.features.mcmeta === "pack_format" ? { pack: { pack_format: major, description: "raw broken worldgen" } } : { pack: { description: "raw broken worldgen", min_format: [major, minor], max_format: [major, minor] } };
  const N = "nx_broken02";
  return [
    { path: "pack.mcmeta", text: JSON.stringify(mcmeta) },
    // 1.21.1-style biome effects (int colours, sky_color / fog_color in effects) on a version with environment attributes
    { path: `data/${N}/worldgen/biome/old_style.json`, text: JSON.stringify({ temperature: 0.5, downfall: 0.5, has_precipitation: true, effects: { sky_color: 7907327, fog_color: 12638463, water_color: 4159204, water_fog_color: 329011 }, spawners: {}, spawn_costs: {}, carvers: [], features: [] }) },
    // a feature type that does not exist (random_patch is gone in 26.1; on 1.21.x a typo)
    { path: `data/${N}/worldgen/configured_feature/gone.json`, text: JSON.stringify({ type: version.startsWith("26.") ? "minecraft:random_patch" : "minecraft:random_patchh", config: { tries: 8, xz_spread: 3, y_spread: 1, feature: "minecraft:patch_grass" } }) },
    // separation >= spacing
    { path: `data/${N}/worldgen/structure_set/bad_spacing.json`, text: JSON.stringify({ structures: [{ structure: "minecraft:igloo", weight: 1 }], placement: { type: "minecraft:random_spread", salt: 1, spacing: 4, separation: 8 } }) },
    // a dimension whose fixed biome does not exist
    { path: `data/${N}/dimension/nowhere.json`, text: JSON.stringify({ type: "minecraft:overworld", generator: { type: "minecraft:noise", settings: "minecraft:overworld", biome_source: { type: "minecraft:fixed", biome: `${N}:missing_biome` } } }) },
  ];
}

async function main() {
  const which = process.argv[2] ?? "all";
  const vi = process.argv.indexOf("--versions");
  const versions = vi > 0 ? process.argv[vi + 1].split(",") : ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"];
  const oi = process.argv.indexOf("--out");
  const work = mkdtempSync(path.join(tmpdir(), "cyrus-wg-real-"));
  const spec = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-worldgen/showcase.json"), "utf8"));
  const out: unknown[] = [];
  const save = () => { const text = JSON.stringify(out, null, 1); if (oi > 0) writeFileSync(process.argv[oi + 1], text); };
  try {
    if (which === "all" || which === "showcase") for (const v of versions) {
      const b = buildDataPack(spec, { version: v, namespace: NS, worldgen: true });
      if (!b.ok) { out.push({ flight: "showcase", version: v, error: b.errors }); console.log(`showcase ${v}: build refused: ${b.errors.join("; ")}`); continue; }
      const file = path.join(work, `cyrus_worldgen-${v}.zip`);
      writeFileSync(file, b.pack.zip);
      const t0 = Date.now();
      const r = await fly({ version: v, datapacks: [{ name: "cyrus_worldgen", localPath: file }], rcon: SHOWCASE_RCON, keepDir: true, world: { generateStructures: true }, timeouts: { bootSec: 240, totalSec: 600 } }, `showcase ${v}`);
      const wall = Date.now() - t0;
      const h = harvest(r.report.runId);
      const ev = r.report.checks.find((c) => c.id === "rcon_checks")?.evidence ?? [];
      const perf = { crystal: pollTime(ev, "crystal"), flat: pollTime(ev, "flat"), nether: pollTime(ev, "nether") };
      console.log(`showcase ${v}: ${describeSummary(r.summary)} | boot ${r.report.bootMs} ms, peak ${Math.round((r.report.peakRssKb ?? 0) / 1024)} MB | 25 chunks: noise ${perf.crystal.approxMs} ms, flat ${perf.flat.approxMs} ms, nether ${perf.nether.approxMs} ms | after-Done problems ${h.afterDoneProblems.length}`);
      out.push({
        flight: "showcase", version: v, packSha256: b.pack.sha256, packBytes: b.pack.bytes, format: b.pack.format, cost: b.pack.worldgen?.cost, status: r.report.status, overall: r.summary.overall, success: r.summary.success,
        bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, flightWallMs: wall, runId: r.report.runId, paper: r.report.engine?.paper, jdk: r.report.engine?.jdk?.version, perf, log: h,
        checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.id === "rcon_checks" ? c.evidence.filter((e) => !/-poll-\d+ /.test(e) || /: ok/.test(e)).slice(0, 60) : c.evidence.slice(0, 30) })),
      });
      save();
    }
    if (which === "all" || which === "broken") for (const v of versions.filter((x) => x === "1.21.11" || x === "26.2" || x === "1.21.1")) {
      const files = brokenWorldgenFiles(v);
      const stat = validatePackFiles(files, v, { worldgen: true });
      const perFile = files.filter((f) => f.path !== "pack.mcmeta").map((f) => ({ path: f.path, rejected: stat.errors.some((e) => e.startsWith(f.path)), errors: stat.errors.filter((e) => e.startsWith(f.path)).slice(0, 4) }));
      const file = path.join(work, `cyrus_wgbroken-${v}.zip`);
      writeFileSync(file, zip(files.map((f) => ({ path: f.path, data: Buffer.from(f.text) }))));
      const r = await fly({ version: v, datapacks: [{ name: "cyrus_wgbroken", localPath: file }], rcon: [{ id: "dims", command: "execute in nx_broken02:nowhere run forceload query", required: false }], keepDir: true, timeouts: { bootSec: 180, totalSec: 420 } }, `broken ${v}`);
      const h = harvest(r.report.runId);
      const boot = r.report.checks.find((c) => c.id === "boot_done"), logc = r.report.checks.find((c) => c.id === "startup_log_clean");
      console.log(`broken ${v}: validator rejects ${perFile.filter((x) => x.rejected).length}/${perFile.length} files; server ${describeSummary(r.summary)}; boot ${boot?.status}; log ${logc?.status}`);
      out.push({
        flight: "broken-raw", version: v, validator: { ok: stat.ok, perFile }, status: r.report.status, overall: r.summary.overall, runId: r.report.runId,
        serverRejected: boot?.status === "fail" || logc?.status === "fail", agree: !stat.ok && (boot?.status === "fail" || logc?.status === "fail"), log: h,
        checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 30) })),
      });
      save();
    }
  } finally { rmSync(work, { recursive: true, force: true }); }
  if (oi <= 0) console.log(JSON.stringify(out, null, 1));
}
if (require.main === module) main().catch((e) => { console.error(e); process.exit(1); });

