describe("capability router + build-request routing", () => {
  const mc = getAdapter("minecraft")!;
  const spec = (text: string) => { const r = validateModSpec({ schemaVersion: 1, game: "minecraft", target: { version: "1.21.11" }, namespace: NS, summary: text, routes: ["plugin"], requirements: [{ id: "REQ-1", text, priority: "must" }], install: { side: "server", restartRequired: true } }, { adapterFor: () => mc }); assert.ok(r.ok, JSON.stringify(r)); return r.ok ? r.spec : null!; };
  it("data-driven requests route to dataPack (planned until the host switches it on)", () => {
    const d = routeSpec(spec("Add custom crafting recipes and chest loot tables"), mc);
    assert.deepEqual(d.routes, ["plugin", "dataPack"]);
    assert.deepEqual(d.planned, ["dataPack"]);
    assert.equal(d.buildableNow, false);
    const on = routeWithDataPack(spec("Add custom crafting recipes and chest loot tables"), { env: { CYRUS_DATAPACK_STUDIO: "1" } })!;
    assert.deepEqual(on.available, ["plugin", "dataPack"]);
    assert.equal(on.label, "plugin+dataPack");
    assert.equal(on.buildableNow, true);
    assert.ok(on.limits.some((l) => /vanilla items/.test(l.message)));
    const fn = routeWithDataPack(spec("A data pack function that runs every tick"), { env: { CYRUS_DATAPACK_STUDIO: "1" } })!;
    assert.ok(fn.matchedRules.includes("datapack_function") && fn.limits.some((l) => /allowlist/.test(l.message)));
    const en = routeWithDataPack(spec("A new enchantment for swords"), { env: { CYRUS_DATAPACK_STUDIO: "1" } })!;
    assert.ok(en.limits.some((l) => /restarts once/.test(l.message)));
    const wg = routeWithDataPack(spec("Add a crystal biome"), { env: { CYRUS_DATAPACK_STUDIO: "1" } })!;
    assert.equal(wg.limits.find((l) => l.id === "worldgen")!.severity, "warn");
    assert.deepEqual(routeSpec(spec("Give players a coin when they join"), mc).routes, ["plugin"]);
  });
  it("build-request decision: off decides nothing; worldgen alone never routes; versions without an emitter say why", () => {
    const base = { text: "custom crafting recipes for my server", mcVersion: "1.21.11", on: true };
    assert.deepEqual(decideDataPackRoute({ ...base, on: false }), { route: false, matched: [], notices: [], limits: [] });
    assert.equal(decideDataPackRoute(base).route, true);
    assert.deepEqual(decideDataPackRoute(base).matched, ["datapack_recipe"]);
    assert.equal(decideDataPackRoute({ ...base, text: "a crystal biome with new structures" }).route, false);
    assert.equal(decideDataPackRoute({ ...base, text: "say hi", explicit: ["datapack"] }).route, true);
    assert.equal(decideDataPackRoute({ ...base, text: "say hi", existing: true }).route, true);
    const r = decideDataPackRoute({ ...base, mcVersion: "26.3" });
    assert.equal(r.route, false); assert.match(r.notices[0], /aren't available for Minecraft 26\.3/);
    assert.deepEqual(matchDataPackRules("creepers drop diamonds when killed"), [], "a vanilla drop change is a plugin listener, not a data pack");
    assert.ok(hasDatapacks({ assets: { datapacks: [{}] } }) && !hasDatapacks({ assets: {} }) && !hasDatapacks(null));
  });
  it("resolveBuildAssets: data packs are not plan-gated (no plan lookup), byte-identical when off", async () => {
    let tierCalls = 0;
    const deps = { tierOf: async () => { tierCalls++; return "free"; }, projectForRootBuild: async () => ({ id: "cp00000000000000000001", namespace: NS }), createProject: async () => ({ id: "cpx", namespace: NS }) };
    const off = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text: "custom crafting recipes", mcVersion: "1.21.11" }, { ...deps, dataPackStudioOn: () => false });
    assert.deepEqual(off, { plan: null, service: null, meta: null });
    const on = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text: "custom crafting recipes", mcVersion: "1.21.11" }, { ...deps, dataPackStudioOn: () => true });
    assert.deepEqual(on.service, { texture: false, sound: false, namespace: NS, datapack: true });
    assert.equal(tierCalls, 0, "no plan lookup for a data pack");
    assert.deepEqual(on.meta!.datapack, { route: true, matched: ["datapack_recipe"], limits: ["Recipes make vanilla items (with a custom name and lore if you like); a data pack cannot add new item types."] });
    const tex = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text: "custom textures", mcVersion: "1.21.11" }, { ...deps, dataPackStudioOn: () => true });
    assert.deepEqual(tex.service, null, "free plan: no textures, and no data pack asked for");
    assert.equal(tierCalls, 1);
    const both = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text: "custom textures and custom crafting recipes", mcVersion: "1.21.11" }, { ...deps, dataPackStudioOn: () => true });
    assert.deepEqual(both.service, { texture: false, sound: false, namespace: NS, datapack: true }, "the texture is refused by the plan, the data pack is not");
    assert.ok(both.meta!.notices.length === 1);
    const meta = readCyrusMeta({ assets: both.meta });
    assert.deepEqual(meta.assets!.datapack, both.meta!.datapack);
  });
});

