export type AssetRequestDeps = {
  /** The account's plan tier (token economy). Throwing = unknown = fail closed. */
  tierOf: (userId: string) => Promise<string>;
  projectForRootBuild: (rootBuildId: string) => Promise<ProjectRef | null>;
  createProject: (input: { userId: string; game: string; rootBuildId: string; title?: string | null }) => Promise<ProjectRef>;
  /** Sound slice: may customer builds use the owner's sound library (licence confirmed)? Default: CYRUS_SOUND_LIBRARY_CLEARED=1. */
  soundLibraryCleared?: () => boolean;
  /** Data pack studio switch (default: CYRUS_DATAPACK_STUDIO=1). Data packs are not plan-gated. */
  dataPackStudioOn?: () => boolean;
  /** R3: is the creature pipeline switched on? Default: CYRUS_CREATURES=1 (fail closed). */
  creaturesEnabled?: () => boolean;
};

export type AssetRequestInput = {
  userId: string;
  /** The chain root: the new build's own id for a fresh build, base.rootBuildId ?? base.id for a change. */
  rootBuildId: string;
  change: boolean;
  /** body.assets from the client: a REQUEST only, never a permission. */
  explicit?: unknown;
  /** The prompt (fresh) or the change request (change). */
  text: string;
  mcVersion: string;
  /** Asset kinds the mod already has (the base build's stored result), so a change can keep editing them. */
  existing?: BuildAssetKind[];
  /** The base build already ships data packs (lib/cyrus/datapack/route.ts hasDatapacks). */
  existingDatapack?: boolean;
  title?: string | null;
};

export type AssetRequestResult = { plan: BuildAssetPlan | null; service: SvcAssets | null; meta: CyrusAssetMeta | null };

const NONE: AssetRequestResult = { plan: null, service: null, meta: null };

export async function resolveBuildAssets(input: AssetRequestInput, deps: AssetRequestDeps): Promise<AssetRequestResult> {
  const requested = requestedAssetKinds({ explicit: input.explicit, text: input.text, existing: input.existing });
  // Cyrus R2: the data pack route (capability router rules, not plan-gated). Off -> decides nothing (byte-identical).
  const dp = decideDataPackRoute({ text: input.text, explicit: input.explicit, existing: input.existingDatapack, mcVersion: input.mcVersion, on: (deps.dataPackStudioOn ?? (() => dataPackStudioOn()))() });
  const dpMeta = dp.route || dp.notices.length ? { datapack: { route: dp.route, matched: dp.matched, limits: dp.limits } } : {};
  if (!requested.length && !dp.route && !dp.notices.length) return NONE;
  let plan: BuildAssetPlan | null = null;
  let meta: CyrusAssetMeta;
  if (requested.length) {
    let tier: unknown = null;
    try { tier = await deps.tierOf(input.userId); } catch { tier = null; } // unknown token state: fail closed
    plan = planBuildAssets({ plan: tier, requested, mcVersion: input.mcVersion, change: input.change, existing: input.existing, creaturesOn: (deps.creaturesEnabled ?? (() => process.env.CYRUS_CREATURES === "1"))() });
    meta = { requested, allowed: BUILD_ASSET_KINDS.filter((k) => plan!.allowed[k]), notices: [...plan.notices, ...dp.notices], ...dpMeta };
  } else meta = { requested: [], allowed: [], notices: [...dp.notices], ...dpMeta };
  if ((!plan || !anyAllowed(plan.allowed)) && !dp.route) return { plan, service: null, meta };
  let project: ProjectRef | null = null;
  try {
    project = (await deps.projectForRootBuild(input.rootBuildId)) ?? (await deps.createProject({ userId: input.userId, game: "minecraft", rootBuildId: input.rootBuildId, title: input.title ?? null }));
  } catch {
    // A racing create (root_taken) means it exists now; anything else: no namespace, so no assets (fail closed).
    project = await deps.projectForRootBuild(input.rootBuildId).catch(() => null);
  }
  if (!project) {
    const msg = dp.route && !(plan && anyAllowed(plan.allowed))
      ? "Cyrus couldn't set up this mod's project right now, so it builds the plugin without the data pack. Try again later."
      : "Cyrus couldn't set up this mod's asset project right now, so it builds the plugin without custom assets. Try again later.";
    return { plan: plan ? { ...plan, allowed: { texture: false, sound: false, creature: false } } : null, service: null, meta: { ...meta, allowed: [], notices: [...meta.notices, msg], ...(dp.route ? { datapack: { route: false, matched: dp.matched, limits: dp.limits } } : {}) } };
  }
  const texture = !!plan?.allowed.texture, sound = !!plan?.allowed.sound;
  return {
    plan,
    // `library` only rides along with sound and `datapack` only when routed, so texture-only requests stay byte-identical
    service: { texture, sound, namespace: project.namespace, ...(sound ? { library: (deps.soundLibraryCleared ?? (() => process.env.CYRUS_SOUND_LIBRARY_CLEARED === "1"))() } : {}), ...(plan?.allowed.creature ? { creature: true as const } : {}), ...(dp.route ? { datapack: true as const } : {}) },
    meta: { ...meta, projectId: project.id, namespace: project.namespace },
  };
}

