  // API jars are installed and verified (defence in depth; the portal decided the plan gate). Absent = byte-identical.
  if (raw.creature !== undefined) {
    let creature = raw.creature === true;
    if (creature && !creatureVersions.has(mcVersion)) { creature = false; notes.push(`creatures are off: Minecraft ${mcVersion} has no animated creature support on this builder`); }
