describe("generated build-service copy == TypeScript", () => {
  it("the bundle and the JSON Schema file are current", async () => {
    const { datapackArtifacts } = await import("../scripts/cyrus/build-datapack-artifacts");
    for (const [rel, text] of Object.entries(await datapackArtifacts())) assert.equal(fs.readFileSync(path.join(ROOT, rel), "utf8"), text, `${rel} is stale: npx tsx scripts/cyrus/build-datapack-artifacts.ts`);
  });
  it("same validation and the same pack bytes on the shared inputs (showcase per version, broken specs, the function corpus, the service example)", () => {
    const inputs: { spec: unknown; version: string; namespace: string }[] = V6.map((v) => ({ spec: SHOWCASE, version: v, namespace: NS }));
    const corpus = JSON.parse(fs.readFileSync(path.join(FX, "function-corpus.json"), "utf8")).cases as { version?: string; fns: FnInput[] }[];
    for (const c of corpus) inputs.push({ spec: { schemaVersion: 1, name: "corpus", description: "corpus", resources: c.fns.map((f) => ({ type: "function", id: f.id, commands: f.commands.map((x) => x.replace(/^REPEAT:\d+:/, "").replace(/NS:/g, `${NS}:`)), ...(f.runOn ? { runOn: f.runOn } : {}) })) }, version: c.version ?? "1.21.11", namespace: NS });
    inputs.push({ spec: JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/datapack-example.json"), "utf8")), version: "1.21.11", namespace: "nx_abcd1234" });
    inputs.push({ spec: { ...SHOWCASE, resources: "nope" }, version: "26.2", namespace: NS }, { spec: null, version: "26.2", namespace: NS }, { spec: SHOWCASE, version: "26.3", namespace: NS });
    for (const i of inputs) {
      const ts = validateDataPackSpec(i.spec, i), js = DPJS.validateDataPackSpec(i.spec, i);
      assert.equal(JSON.stringify(js), JSON.stringify(ts));
      const tb = buildDataPack(i.spec, i), jb = DPJS.buildDataPack(i.spec, i);
      assert.equal(jb.ok, tb.ok);
      if (tb.ok && jb.ok) assert.equal(jb.pack.sha256, tb.pack.sha256);
    }
  });
  it("prompt section: present only when routed, limits match", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    assert.equal(P.systemPrompt("1.21.11", {}).includes("DATA PACK (allowed"), false);
    assert.equal(P.systemPrompt("1.21.11", { datapack: true }).includes("DATA PACK (allowed"), true);
    assert.equal(P.systemPrompt("1.21.11", { textures: true }), P.systemPrompt("1.21.11", { textures: true, datapack: false }), "texture builds byte-identical");
    assert.match(P.DATAPACK_SECTION, new RegExp(`At most ${DATAPACK_LIMITS.maxFiles} files`));
