// Cyrus R4 worldgen (pure): per-version features, the NBT writer vs the independent reader, the structure template
// compiler, the worldgen spec + caps + adversarial corpus, per-version emitters with golden hashes, the worldgen file
// validator (incl. the raw broken files flown on node-2), TS == generated JS, router / build request / prompt,
// delivery + sync. Real servers: test/cyrus-worldgen-real.ts (node-2 Test Flight, run by hand).
//   tsx --test test/cyrus-worldgen.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { gunzipSync } from "node:zlib";
import { buildDataPack, emitFiles } from "../lib/cyrus/datapack/emit";
import { validateDataPackSpec, needsRestart, type DataPackSpec } from "../lib/cyrus/datapack/spec";
import { validatePackFiles } from "../lib/cyrus/datapack/validate";
import { dataPackFeatures } from "../lib/cyrus/datapack/versions";
import { crc32, gzipStored, nbtGet, nbtToJs, readNbt, writeNbt, nCompound, nInt, nList, nStr, type Nbt } from "../lib/cyrus/datapack/worldgen/nbt";
import { compileTemplate, templateShapeIssues } from "../lib/cyrus/datapack/worldgen/template";
import { blockStateProblems, blockStates, worldgenFeatures } from "../lib/cyrus/datapack/worldgen/versions";
import { featureCycle, hasWorldgen } from "../lib/cyrus/datapack/worldgen/check";
import { WORLDGEN_LIMITS, type DpStructureTemplate } from "../lib/cyrus/datapack/worldgen/spec";
import { decideDataPackRoute, hasWorldgenDatapacks, routeWithDataPack, WORLDGEN_LIMIT_MESSAGE, worldgenOn } from "../lib/cyrus/datapack/route";
import { deliverDataPack, planDataPackDelivery, rebuildForDelivery } from "../lib/cyrus/datapack/deliver";
import { checkReturnedDatapacks } from "../lib/cyrus/datapack/sync";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { getAdapter } from "../lib/cyrus/adapters";
import { validateModSpec } from "../lib/cyrus/engine-core/spec";
import { brokenWorldgenFiles } from "./cyrus-worldgen-real";

const ROOT = path.join(__dirname, "..");
const FX = path.join(ROOT, "test/fixtures/cyrus-worldgen");
const NS = "nx_worldg01";
const V6 = ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"];
const SHOWCASE: DataPackSpec = JSON.parse(fs.readFileSync(path.join(FX, "showcase.json"), "utf8"));
const clone = <T>(x: T): T => JSON.parse(JSON.stringify(x));
const CTX = (v: string) => ({ version: v, namespace: NS, worldgen: true });
const files = (v: string) => { const b = buildDataPack(SHOWCASE, CTX(v)); assert.ok(b.ok, JSON.stringify(!b.ok && b.errors)); return b.ok ? new Map(b.pack.files.map((f) => [f.path, f])) : new Map(); };
const json = (m: Map<string, { text: string }>, p: string) => JSON.parse(m.get(p)!.text);

describe("worldgen versions (derived from the real jars)", () => {
