    const f = (v: string) => { const r = worldgenFeatures(v); assert.ok(r.ok, v); return r.ok ? r.features : null!; };
    assert.deepEqual(V6.map((v) => f(v).dataVersion), [3955, 4189, 4440, 4671, 4790, 4903]);
    assert.deepEqual(V6.map((v) => f(v).carvers), ["map", "list", "list", "list", "list", "list"]);
    assert.deepEqual(V6.map((v) => f(v).biome), ["effects", "effects", "effects", "attributes", "attributes", "attributes"]);
    assert.deepEqual(V6.map((v) => f(v).music), ["single", "weighted", "weighted", "weighted", "weighted", "weighted"]);
    assert.deepEqual(V6.map((v) => f(v).dryFoliage), [false, false, true, true, true, true]);
    assert.deepEqual(V6.map((v) => f(v).dimensionType), ["classic", "classic", "classic", "attributes", "attributes", "attributes"]);
    assert.deepEqual(V6.map((v) => f(v).worldClock), [false, false, false, false, true, true]);
    assert.deepEqual(V6.map((v) => f(v).patch), ["random_patch", "random_patch", "random_patch", "random_patch", "placement", "placement"]);
    assert.deepEqual(V6.map((v) => f(v).treeDirt), ["dirt_provider", "dirt_provider", "dirt_provider", "dirt_provider", "below_trunk_provider", "below_trunk_provider"]);
    assert.deepEqual(V6.map((v) => f(v).lakePredicates), [false, false, false, false, false, true]);
    for (const v of V6) assert.deepEqual(f(v).noise.overworld, { minY: -64, height: 384 });
    assert.equal(worldgenFeatures("26.3").ok, false);
    assert.equal(worldgenFeatures("1.20.4").ok, false);
  });
  it("block state tables: real properties per version", () => {
    assert.deepEqual(blockStates("26.2").get("oak_log"), { axis: ["x", "y", "z"] });
    assert.deepEqual(blockStateProblems("minecraft:oak_log", { axis: "y" }, "1.21.1"), []);
    assert.match(blockStateProblems("minecraft:oak_log", { axis: "w" }, "1.21.1")[0], /axis=w is not allowed/);
    assert.match(blockStateProblems("minecraft:stone", { lit: "true" }, "26.2")[0], /has no block state property "lit"/);
    assert.ok(blockStates("1.21.1").get("chest")!.facing.includes("south"));
  });
});

describe("NBT writer vs the independent reader", () => {
  const sample = (): Nbt => nCompound([
    ["b", { t: "byte", v: -5 }], ["s", { t: "short", v: 31000 }], ["i", nInt(-123456789)], ["l", { t: "long", v: -9007199254740993n }],
    ["f", { t: "float", v: 1.5 }], ["d", { t: "double", v: Math.PI }], ["str", nStr("Grüße \u0000 \u{1F600} ⛏")], ["empty", nList("int", [])],
    ["li", nList("int", [nInt(1), nInt(2), nInt(3)])], ["nested", nCompound([["deep", nList("compound", [nCompound([["x", nStr("y")]])])]])],
    ["ia", { t: "intArray", v: [1, -2, 3] }], ["ba", { t: "byteArray", v: [1, -1, 127] }], ["la", { t: "longArray", v: [1n, -2n] }],
  ]);
  it("round trip of every tag type (modified UTF-8, empty lists, nesting)", () => {
    const raw = writeNbt(sample());
    const back = readNbt(raw);
    assert.equal(back.name, "");
    assert.deepEqual(back.root, { ...sample(), v: (sample() as { v: [string, Nbt][] }).v.map(([k, v]) => [k, k === "empty" ? { t: "list", of: "end", v: [] } : v]) });
    assert.equal(nbtToJs(nbtGet(back.root, "str")!), "Grüße \u0000 \u{1F600} ⛏");
    assert.ok(raw.includes(Buffer.from([0xc0, 0x80])), "NUL is written as C0 80 (Java modified UTF-8)");
  });
  it("stored gzip: deterministic, real gunzip reads it, CRC + size trailer", () => {
    const raw = writeNbt(sample());
    const g1 = gzipStored(raw), g2 = gzipStored(Buffer.from(raw));
    assert.ok(g1.equals(g2));
    assert.deepEqual(gunzipSync(g1), raw);
    assert.equal(g1.readUInt32LE(g1.length - 8), crc32(raw));
    assert.deepEqual(readNbt(g1).root, readNbt(raw).root);
    const big = Buffer.alloc(200000, 7); assert.deepEqual(gunzipSync(gzipStored(big)), big, "several stored blocks");
  });
  it("the reader refuses broken input", () => {
    const raw = writeNbt(sample());
    assert.throws(() => readNbt(raw.subarray(0, raw.length - 3)), /truncated/);
    assert.throws(() => readNbt(Buffer.concat([raw, Buffer.from([0])])), /trailing/);
    assert.throws(() => readNbt(Buffer.from([8, 0, 0])), /root is not a compound/);
    assert.throws(() => readNbt(Buffer.from([10, 0, 0, 99, 0, 1, 97])), /bad NBT tag/);
    assert.throws(() => readNbt(Buffer.from([10, 0, 0, 9, 0, 1, 97, 3, 0x7f, 0xff, 0xff, 0xff])), /bad NBT length/);
    let deep: Nbt = nInt(1); for (let i = 0; i < 40; i++) deep = nCompound([["x", deep]]);
    assert.throws(() => readNbt(writeNbt(deep as Nbt)), /too deep/);
    assert.throws(() => writeNbt(nCompound([["a", nInt(1)], ["a", nInt(2)]])), /duplicate/);
    assert.throws(() => writeNbt(nList("int", [nInt(1), nStr("x")])), /root must be a compound/);
  });
});

describe("structure template compiler", () => {
  const T = (): DpStructureTemplate => clone((SHOWCASE.resources.find((r) => r.type === "structure_template") as { template: DpStructureTemplate }).template);
  it("compiles to a vanilla-shaped structure file (read back with the reference reader)", () => {
    const c = compileTemplate(T(), 4903);
    const r = readNbt(c.nbt).root as Nbt;
    const js = nbtToJs(r) as { DataVersion: number; size: number[]; palette: { Name: string; Properties?: Record<string, string> }[]; blocks: { pos: number[]; state: number; nbt?: Record<string, string> }[]; entities: unknown[] };
    assert.equal(js.DataVersion, 4903);
    assert.deepEqual(js.size, [7, 5, 7]);
    assert.deepEqual(js.entities, []);
    assert.equal(js.blocks.length, c.blocks);
    assert.equal(c.blocks, 7 * 7 * 5 - 16 - 8 - 4, "the 28 '.' cells are structure void (not stored)");
    assert.deepEqual(js.palette.map((p) => p.Name), ["minecraft:stone_bricks", "minecraft:mossy_cobblestone", "minecraft:air", "minecraft:glowstone", "minecraft:chest"]);
    const chest = js.blocks.find((b) => js.palette[b.state].Name === "minecraft:chest")!;
    assert.deepEqual(chest.pos, [3, 1, 3]);
    assert.deepEqual(chest.nbt, { LootTable: `${NS}:chests/ruin`, id: "minecraft:chest" });
    assert.equal(js.blocks[js.blocks.length - 1], chest, "block entities last (vanilla order)");
    assert.deepEqual(js.palette[4].Properties, { facing: "south" });
    assert.ok(js.blocks.every((b) => b.pos.every((x, k) => x >= 0 && x < js.size[k])));
    assert.deepEqual(c.loot, [`${NS}:chests/ruin`]);
  });
  it("deterministic, and the DataVersion is the only per-version difference", () => {
    assert.ok(compileTemplate(T(), 4671).nbt.equals(compileTemplate(T(), 4671).nbt));
    assert.notEqual(compileTemplate(T(), 4671).raw.toString("hex"), compileTemplate(T(), 4903).raw.toString("hex"));
    assert.equal(compileTemplate(T(), 4671).raw.length, compileTemplate(T(), 4903).raw.length);
  });
  it("shape issues", () => {
    const t = T(); t.layers.pop();
    assert.ok(templateShapeIssues(t).some((i) => /5 layers/.test(i.message)));
    const u = T(); u.layers[1][2] = "MaaaaM";
    assert.ok(templateShapeIssues(u).some((i) => /has 6/.test(i.message)));
    const w = T(); w.layers[0][0] = "SSSSSSZ";
    assert.ok(templateShapeIssues(w).some((i) => /"Z" is not in the palette/.test(i.message)));
    const x = T(); x.palette.S.loot = `${NS}:chests/ruin`;
    assert.ok(templateShapeIssues(x).some((i) => /can carry a loot table/.test(i.message)));
    const y = T(); y.palette.Q = { block: "minecraft:dirt" };
    assert.ok(templateShapeIssues(y).some((i) => /never used/.test(i.message)));
    assert.throws(() => compileTemplate(t, 1), /template/);
  });
});

describe("worldgen spec validation", () => {
  it("the showcase is valid on every pinned version; worldgen is refused unless the route enabled it (fail closed)", () => {
    for (const v of V6) {
      const r = validateDataPackSpec(SHOWCASE, CTX(v));
      assert.ok(r.ok, `${v}: ${JSON.stringify(!r.ok && r.errors)}`);
      if (r.ok) { assert.equal(r.worldgen!.cost.class, "low"); assert.deepEqual(r.worldgen!.dimensions, [`${NS}:crystal`, `${NS}:flatland`]); assert.ok(r.checks.some((c) => c.id === "worldgen" && c.status !== "fail")); }
    }
    const off = validateDataPackSpec(SHOWCASE, { version: "26.2", namespace: NS });
    assert.ok(!off.ok && off.errors[0].code === "worldgen_off");
    assert.equal(needsRestart(SHOWCASE), true);
    assert.equal(hasWorldgen(SHOWCASE), true);
  });
  it("packs without world generation keep their R2 report (no worldgen check id)", () => {
    const plain = { schemaVersion: 1, name: "plain", description: "p", resources: [{ type: "function", id: "hi", commands: ["say hi"] }] };
    const r = validateDataPackSpec(plain, { version: "26.2", namespace: NS });
    assert.ok(r.ok); assert.ok(!r.checks.some((c) => c.id === "worldgen")); assert.equal("worldgen" in r, false);
  });

  // adversarial corpus: take the showcase, break exactly one thing, expect exactly that error code (and the version)
  const R = (s: DataPackSpec, type: string, id: string) => s.resources.find((r) => r.type === type && (r as { id: string }).id === id) as Record<string, any>;
  const CASES: { name: string; mutate: (s: DataPackSpec) => void; code: string; version?: string }[] = [
    { name: "vanilla biome in the dimension", mutate: (s) => { R(s, "dimension", "crystal").dimension.generator.biomes.biomes[0].biome = "minecraft:plains"; }, code: "own_only" },
    { name: "undefined own biome", mutate: (s) => { R(s, "dimension", "crystal").dimension.generator.biomes.biomes[0].biome = `${NS}:nope`; }, code: "unresolved_ref" },
    { name: "foreign namespace", mutate: (s) => { R(s, "biome", "crystal_plains").biome.features.push({ step: "lakes", feature: "other:lake" }); }, code: "foreign_namespace" },
    { name: "unknown vanilla placed feature", mutate: (s) => { R(s, "biome", "crystal_plains").biome.features.push({ step: "lakes", feature: "minecraft:lake_lavaa" }); }, code: "unknown_vanilla_id" },
    { name: "a 1.21.x placed feature gone in 26.1", mutate: (s) => { R(s, "biome", "crystal_plains").biome.features.push({ step: "vegetal_decoration", feature: "minecraft:patch_grass_plain_x" }); }, code: "unknown_vanilla_id" },
    { name: "unknown block", mutate: (s) => { R(s, "configured_feature", "amethyst_ore").feature.targets[0].block = "minecraft:rubyy_ore"; }, code: "unknown_vanilla_id" },
    { name: "own block", mutate: (s) => { R(s, "configured_feature", "amethyst_ore").feature.targets[0].block = `${NS}:ruby_ore`; }, code: "own_block" },
    { name: "command block in a template", mutate: (s) => { R(s, "structure_template", "ruin").template.palette.G.block = "minecraft:command_block"; }, code: "denied_block" },
    { name: "spawner in a feature", mutate: (s) => { R(s, "configured_feature", "small_lake").feature.barrier = "minecraft:spawner"; }, code: "denied_block" },
    { name: "bad block state value", mutate: (s) => { R(s, "structure_template", "ruin").template.palette.C.properties.facing = "up"; }, code: "block_state" },
    { name: "bad block state property", mutate: (s) => { R(s, "configured_feature", "crystal_tree").feature.trunk.properties = { lit: "true" }; }, code: "block_state" },
    { name: "separation >= spacing", mutate: (s) => { R(s, "structure_set", "ruins").structureSet.separation = 8; }, code: "separation" },
    { name: "template row too short", mutate: (s) => { R(s, "structure_template", "ruin").template.layers[2][1] = "Maaa"; }, code: "template_shape" },
    { name: "template larger than 48", mutate: (s) => { R(s, "structure_template", "ruin").template.size = [49, 5, 7]; }, code: "schema" },
    { name: "palette over 32 entries", mutate: (s) => { const p = R(s, "structure_template", "ruin").template.palette; for (let i = 0; i < 30; i++) p[String.fromCharCode(48 + i)] = { block: "minecraft:dirt" }; }, code: "template_shape" },
    { name: "chest loot table not in the pack", mutate: (s) => { R(s, "structure_template", "ruin").template.palette.C.loot = `${NS}:chests/missing`; }, code: "unresolved_ref" },
    { name: "terrain taller than the dimension type", mutate: (s) => { R(s, "dimension_type", "crystal").dimensionType.minY = 0; R(s, "dimension_type", "crystal").dimensionType.height = 256; }, code: "noise_range" },
    { name: "dimension above y 320", mutate: (s) => { R(s, "dimension_type", "crystal").dimensionType.minY = -32; }, code: "dimension_height" },
    { name: "minY not a multiple of 16", mutate: (s) => { R(s, "dimension_type", "crystal").dimensionType.minY = -60; }, code: "schema" },
    { name: "flat layers thicker than the dimension", mutate: (s) => { R(s, "dimension", "flatland").dimension.generator.layers.push({ block: "minecraft:stone", height: 64 }, { block: "minecraft:stone", height: 64 }); }, code: "flat_height" },
    { name: "feature order cycle", mutate: (s) => { const f = R(s, "biome", "amethyst_hills").biome.features; f.push({ step: "underground_ores", feature: "minecraft:ore_iron_middle" }); }, code: "feature_order_cycle" },
    { name: "a boss as a natural spawn", mutate: (s) => { R(s, "biome", "crystal_plains").biome.spawns.push({ category: "monster", entity: "minecraft:ender_dragon", weight: 1, min: 1, max: 1 }); }, code: "not_spawnable" },
    { name: "too many attempts per feature", mutate: (s) => { R(s, "placed_feature", "crystal_flowers").placed.placement[0].count = 64; }, code: "feature_attempts" },
    { name: "a structure in a vanilla biome", mutate: (s) => { R(s, "structure", "ruin").structure.biomes.push("minecraft:plains"); }, code: "own_only" },
    { name: "a structure set with a vanilla structure", mutate: (s) => { R(s, "structure_set", "ruins").structureSet.structures.push({ structure: "minecraft:igloo" }); }, code: "own_only" },
    { name: "missing template", mutate: (s) => { R(s, "structure", "ruin").structure.template = `${NS}:nope`; }, code: "unresolved_ref" },
    { name: "unknown particle in 1.21.1", mutate: (s) => { R(s, "biome", "amethyst_hills").biome.particle.type = "firefly"; }, code: "unknown_vanilla_id", version: "1.21.1" },
    { name: "unknown sound event", mutate: (s) => { R(s, "biome", "crystal_plains").biome.music.sound = "minecraft:music.overworld.crystal"; }, code: "unknown_vanilla_id" },
    { name: "17 biomes", mutate: (s) => { const b = R(s, "biome", "crystal_plains"); for (let i = 0; i < 15; i++) s.resources.push({ ...clone(b), id: `extra_${i}` } as never); }, code: "worldgen_count" },
    { name: "too many attempts per biome", mutate: (s) => { for (let i = 0; i < 6; i++) { s.resources.push({ type: "placed_feature", id: `ore_${i}`, placed: { feature: `${NS}:amethyst_ore`, placement: [{ kind: "count", count: 64 }, { kind: "count", count: 4 }, { kind: "in_square" }, { kind: "biome" }] } } as never); R(s, "biome", "amethyst_hills").biome.features.unshift({ step: "raw_generation", feature: `${NS}:ore_${i}` }); } }, code: "biome_attempts" },
    { name: "estimated cost above the ceiling", mutate: (s) => { R(s, "configured_feature", "amethyst_ore").feature.size = 32; R(s, "dimension", "crystal").dimension.generator.terrain = "amplified"; for (let i = 0; i < 4; i++) { s.resources.push({ type: "placed_feature", id: `ore_${i}`, placed: { feature: `${NS}:amethyst_ore`, placement: [{ kind: "count", count: 64 }, { kind: "count", count: 4 }, { kind: "in_square" }, { kind: "biome" }] } } as never); R(s, "biome", "amethyst_hills").biome.features.unshift({ step: "raw_generation", feature: `${NS}:ore_${i}` }); } }, code: "worldgen_cost" },
    { name: "worldgen kind with an unknown field", mutate: (s) => { R(s, "biome", "crystal_plains").biome.surfaceRule = "x"; }, code: "schema" },
  ];
  for (const c of CASES) it(`refuses: ${c.name}`, () => {
    const s = clone(SHOWCASE); c.mutate(s);
    const r = validateDataPackSpec(s, CTX(c.version ?? "26.2"));
    assert.ok(!r.ok, "must fail");
    if (!r.ok) assert.ok(r.errors.some((e) => e.code === c.code), `${c.code} expected, got ${JSON.stringify(r.errors.map((e) => `${e.code}: ${e.message}`))}`);
  });
  it("warnings: unused biome, structure without a set, duplicate climate point, no dimension", () => {
    const s = clone(SHOWCASE);
    s.resources.push({ ...clone(R(s, "biome", "amethyst_hills")), id: "lonely" } as never);
    s.resources.push({ type: "structure", id: "ruin2", structure: { template: `${NS}:ruin`, biomes: [`${NS}:crystal_plains`] } } as never);
    const r = validateDataPackSpec(s, CTX("26.2"));
    assert.ok(r.ok);
    const codes = r.warnings.map((w) => w.code);
    assert.ok(codes.includes("unused_biome") && codes.includes("no_structure_set"), JSON.stringify(codes));
    const nod = clone(SHOWCASE); nod.resources = nod.resources.filter((x) => x.type !== "dimension");
    const r2 = validateDataPackSpec(nod, CTX("26.2"));
    assert.ok(r2.warnings.some((w) => w.code === "no_dimension"));
  });
  it("featureCycle finds a two-biome order conflict", () => {
    const b = (fs: string[]) => ({ type: "biome", id: "x", biome: { features: fs.map((f) => ({ step: "underground_ores", feature: f })) } }) as never;
    assert.deepEqual(featureCycle([b(["a:1", "a:2"]), b(["a:2", "a:1"])])?.sort(), ["a:1", "a:2"]);
    assert.equal(featureCycle([b(["a:1", "a:2"]), b(["a:1", "a:3", "a:2"])]), null);
  });
});

describe("per-version emitters (golden hashes = the flown packs)", () => {
  const GOLDEN: Record<string, string> = JSON.parse(fs.readFileSync(path.join(FX, "golden.json"), "utf8")).showcase;
  it("golden pack hashes per version, same bytes twice, restart apply", () => {
    for (const v of V6) {
      const a = buildDataPack(SHOWCASE, CTX(v)), b = buildDataPack(clone(SHOWCASE), CTX(v));
      assert.ok(a.ok && b.ok, v);
      if (a.ok && b.ok) { assert.equal(a.pack.sha256, b.pack.sha256); assert.equal(a.pack.sha256, GOLDEN[v], `${v} golden`); assert.equal(a.pack.apply, "restart"); assert.ok(a.pack.checks.every((c) => c.status !== "fail")); }
    }
  });
  it("biomes: effects (int colours) before 1.21.11, environment attributes + #rrggbb after; carvers map before 1.21.2; music single / weighted", () => {
    const b1 = json(files("1.21.1"), `data/${NS}/worldgen/biome/crystal_plains.json`);
    assert.deepEqual(b1.carvers, { air: ["minecraft:cave"] });
    assert.equal(b1.effects.sky_color, 0x9ec9ff); assert.equal(b1.effects.music.sound, "minecraft:music.overworld.cherry_grove");
    assert.equal("dry_foliage_color" in b1.effects, false, "dry foliage only from 1.21.5");
    const b4 = json(files("1.21.4"), `data/${NS}/worldgen/biome/crystal_plains.json`);
    assert.deepEqual(b4.carvers, ["minecraft:cave"]); assert.ok(Array.isArray(b4.effects.music)); assert.equal(b4.effects.music[0].weight, 1);
    const b8 = json(files("1.21.8"), `data/${NS}/worldgen/biome/crystal_plains.json`);
    assert.equal(b8.effects.dry_foliage_color, 0xa08060);
    const b11 = json(files("1.21.11"), `data/${NS}/worldgen/biome/crystal_plains.json`);
    assert.deepEqual(Object.keys(b11.effects).sort(), ["dry_foliage_color", "foliage_color", "grass_color", "water_color"]);
    assert.equal(b11.effects.water_color, "#3fd0e4"); assert.equal(b11.attributes["minecraft:visual/sky_color"], "#9ec9ff");
    assert.equal(b11.attributes["minecraft:audio/background_music"].default.sound, "minecraft:music.overworld.cherry_grove");
    const h11 = json(files("1.21.11"), `data/${NS}/worldgen/biome/amethyst_hills.json`);
    assert.deepEqual(h11.attributes["minecraft:visual/ambient_particles"], [{ particle: { type: "minecraft:white_ash" }, probability: 0.01 }]);
    assert.equal(h11.attributes["minecraft:audio/ambient_sounds"].loop, "minecraft:ambient.basalt_deltas.loop");
  });
  it("dimension types: classic fields before 1.21.11, attributes after, has_ender_dragon_fight false from 26.1", () => {
    const d1 = json(files("1.21.8"), `data/${NS}/dimension_type/crystal.json`);
    assert.equal(d1.effects, "minecraft:overworld"); assert.equal(d1.bed_works, true); assert.equal("attributes" in d1, false);
    const e1 = json(files("1.21.8"), `data/${NS}/dimension_type/flat_night.json`);
    assert.equal(e1.fixed_time, 6000); assert.equal(e1.effects, "minecraft:the_end");
    const d11 = json(files("1.21.11"), `data/${NS}/dimension_type/crystal.json`);
    assert.equal("bed_works" in d11, false); assert.equal(d11.timelines, "#minecraft:in_overworld"); assert.equal(d11.attributes["minecraft:gameplay/bed_rule"].can_sleep, "when_dark");
    assert.equal("has_ender_dragon_fight" in d11, false);
    const e26 = json(files("26.2"), `data/${NS}/dimension_type/flat_night.json`);
    assert.equal(e26.has_ender_dragon_fight, false, "a custom end-like dimension never spawns a dragon"); assert.equal(e26.skybox, "end"); assert.equal(e26.has_fixed_time, true); assert.equal(e26.default_clock, "minecraft:the_end");
  });
  it("features: random_patch before 26.1, simple_block + count/random_offset/filter placement from 26.1; tree dirt; lake predicates 26.2", () => {
    const p11 = files("1.21.11");
    assert.equal(json(p11, `data/${NS}/worldgen/configured_feature/crystal_flowers.json`).type, "minecraft:random_patch");
    assert.equal(json(p11, `data/${NS}/worldgen/placed_feature/crystal_flowers.json`).placement.length, 4);
    assert.ok(json(p11, `data/${NS}/worldgen/configured_feature/crystal_tree.json`).config.dirt_provider);
    const p26 = files("26.1.2");
