describe("worldgen file validator", () => {
  it("every emitted showcase file passes its version and fails a version with the other format", () => {
    for (const v of V6) { const r = validatePackFiles([...files(v).values()], v, { worldgen: true }); assert.ok(r.ok, `${v}: ${r.errors.slice(0, 5).join(" | ")}`); assert.deepEqual(r.notChecked, []); }
    const old = [...files("1.21.4").values()].filter((f) => f.path !== "pack.mcmeta");
    const r = validatePackFiles([{ path: "pack.mcmeta", text: [...files("26.2").values()].find((f) => f.path === "pack.mcmeta")!.text }, ...old], "26.2", { worldgen: true });
    assert.ok(!r.ok);
    assert.ok(r.errors.some((e) => /effects has the key "sky_color", which Minecraft 26.2 does not know/.test(e)));
    assert.ok(r.errors.some((e) => /must be a "#rrggbb" string/.test(e)));
    assert.ok(r.errors.some((e) => /random_patch does not exist in Minecraft 26.2/.test(e)));
    assert.ok(r.errors.some((e) => /dimension type has the key "ultrawarm"/.test(e)));
  });
  it("the raw broken files flown on node-2 are each rejected (1.21.1, 1.21.11, 26.2)", () => {
    for (const v of ["1.21.1", "1.21.11", "26.2"]) {
      const fl = brokenWorldgenFiles(v);
      const r = validatePackFiles(fl, v, { worldgen: true });
      for (const f of fl.filter((x) => x.path !== "pack.mcmeta" && !(v === "1.21.1" && /old_style/.test(x.path)))) assert.ok(r.errors.some((e) => e.startsWith(f.path)), `${v} ${f.path}: ${r.errors.join(" | ")}`);
    }
  });
  it("structure files: unreadable, out-of-range positions, too new DataVersion", () => {
    const fail = (data: Buffer, v = "26.2") => validatePackFiles([{ path: "pack.mcmeta", text: [...files(v).values()].find((f) => f.path === "pack.mcmeta")!.text }, { path: `data/${NS}/structure/x.nbt`, text: "", data }], v, { worldgen: true });
    assert.match(fail(Buffer.from([0x1f, 0x8b, 8, 0, 1, 2])).errors[0], /not a readable structure file/);
    const bad = writeNbt(nCompound([["DataVersion", nInt(4903)], ["size", nList("int", [nInt(1), nInt(1), nInt(1)])], ["palette", nList("compound", [nCompound([["Name", nStr("minecraft:stone")]])])], ["blocks", nList("compound", [nCompound([["pos", nList("int", [nInt(5), nInt(0), nInt(0)])], ["state", nInt(3)]])])], ["entities", nList("compound", [])]]));
    assert.ok(fail(gzipStored(bad)).errors.some((e) => /outside the size or point at a missing palette row/.test(e)));
    const tpl = files("26.2").get(`data/${NS}/structure/ruin.nbt`)!.data!;
    assert.ok(fail(tpl, "1.21.11").errors.some((e) => /DataVersion 4903 is newer than Minecraft 1.21.11/.test(e)));
  });
  it("without { worldgen } (imports) worldgen files stay not_checked (R2 behaviour)", () => {
    const r = validatePackFiles([...files("26.2").values()], "26.2");
    assert.ok(r.notChecked.some((p) => p.endsWith("crystal_plains.json")));
  });
});

describe("generated build-service copy == TypeScript (worldgen inputs)", () => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const DPJS = require(path.join(ROOT, "services/modbuilder/datapack-spec.js"));
  it("same validation and the same pack bytes (showcase per version, the corpus cases, the service example, worldgen off)", () => {
