    const s = clone(SHOWCASE); (s.resources.find((r) => r.type === "structure_set") as { structureSet: { separation: number } }).structureSet.separation = 9;
    inputs.push({ spec: s, ...CTX("1.21.11") });
    for (const i of inputs) {
