      const tb = buildDataPack(i.spec, i), jb = DPJS.buildDataPack(i.spec, i);
      assert.equal(jb.ok, tb.ok);
      if (tb.ok && jb.ok) assert.equal(jb.pack.sha256, tb.pack.sha256);
