  });
  it("the service example builds on every version", () => {
    const ex = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/worldgen-example.json"), "utf8"));
    for (const v of V6) { const b = buildDataPack(ex, { version: v, namespace: "nx_abcd1234", worldgen: true }); assert.ok(b.ok, `${v}: ${!b.ok && b.errors.join("; ")}`); }
  });
  it("prompt: WORLD GENERATION only with datapack + worldgen; the data pack section is byte-identical", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    assert.equal(P.systemPrompt("26.2", { datapack: true }), P.systemPrompt("26.2", { datapack: true, worldgen: false }));
    assert.equal(P.systemPrompt("26.2", { datapack: true }).includes("WORLD GENERATION (allowed"), false);
    assert.equal(P.systemPrompt("26.2", { worldgen: true }).includes("WORLD GENERATION (allowed"), false, "never without the data pack section");
    const on = P.systemPrompt("26.2", { datapack: true, worldgen: true });
