describe("router, build request, delivery, sync", () => {
  const mc = getAdapter("minecraft")!;
  const spec = (text: string) => { const r = validateModSpec({ schemaVersion: 1, game: "minecraft", target: { version: "1.21.11" }, namespace: NS, summary: text, routes: ["plugin"], requirements: [{ id: "REQ-1", text, priority: "must" }], install: { side: "server", restartRequired: true } }, { adapterFor: () => mc }); assert.ok(r.ok); return r.ok ? r.spec : null!; };
  const base = { text: "a crystal biome with new structures in its own dimension", mcVersion: "26.2", on: true };
  it("flag off: exactly the R2 behaviour (worldgen alone never routes; the router keeps its warning)", () => {
    assert.equal(worldgenOn({ CYRUS_DATAPACK_STUDIO: "1" }), false);
    assert.equal(worldgenOn({ CYRUS_WORLDGEN: "1" }), false, "needs the studio too");
    assert.deepEqual(decideDataPackRoute(base), { route: false, matched: [], notices: [], limits: [] });
    const r = routeWithDataPack(spec("Add a crystal biome"), { env: { CYRUS_DATAPACK_STUDIO: "1" } })!;
    assert.match(r.limits.find((l) => l.id === "worldgen")!.message, /not built into Cyrus yet/);
  });
  it("flag on: biomes / dimensions / structures route to the worldgen part with the honest limits", () => {
    const d = decideDataPackRoute({ ...base, worldgen: true });
    assert.equal(d.route, true); assert.equal(d.worldgen, true); assert.deepEqual(d.matched, ["worldgen"]);
    assert.ok(d.limits.includes(WORLDGEN_LIMIT_MESSAGE));
    assert.match(WORLDGEN_LIMIT_MESSAGE, /restart/); assert.match(WORLDGEN_LIMIT_MESSAGE, /NEW chunks/); assert.match(WORLDGEN_LIMIT_MESSAGE, /teleport or command/);
    assert.ok(WORLDGEN_LIMIT_MESSAGE.length <= 300, "fits the stored limit line");
    const mixed = decideDataPackRoute({ ...base, text: "custom crafting recipes and a new dimension", worldgen: true });
    assert.deepEqual(mixed.matched.sort(), ["datapack_recipe", "worldgen"]);
    const plain = decideDataPackRoute({ ...base, text: "custom crafting recipes", worldgen: true });
    assert.equal("worldgen" in plain, false, "non-worldgen decisions are unchanged");
    assert.equal(decideDataPackRoute({ ...base, text: "make the recipe cheaper", existing: true, existingWorldgen: true, worldgen: true }).worldgen, true, "a change keeps its worldgen");
    const r = routeWithDataPack(spec("Add a crystal biome"), { env: { CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1" } })!;
    assert.equal(r.limits.find((l) => l.id === "worldgen")!.message, WORLDGEN_LIMIT_MESSAGE);
    assert.ok(hasWorldgenDatapacks({ assets: { datapacks: [{ worldgen: true }] } }) && !hasWorldgenDatapacks({ assets: { datapacks: [{}] } }));
  });
  it("build request: service.worldgen only when routed; not plan-gated; off = byte-identical", async () => {
    let tierCalls = 0;
    const deps = { tierOf: async () => { tierCalls++; return "free"; }, projectForRootBuild: async () => ({ id: "cp00000000000000000001", namespace: NS }), createProject: async () => ({ id: "cpx", namespace: NS }), dataPackStudioOn: () => true };
    const inp = { userId: "u", rootBuildId: "b", change: false, text: "a new dimension with crystal biomes", mcVersion: "26.2" };
    const off = await resolveBuildAssets(inp, { ...deps, worldgenOn: () => false });
    assert.deepEqual(off, { plan: null, service: null, meta: null });
    const on = await resolveBuildAssets(inp, { ...deps, worldgenOn: () => true });
    assert.deepEqual(on.service, { texture: false, sound: false, namespace: NS, datapack: true, worldgen: true });
    assert.equal(on.meta!.datapack!.worldgen, true);
    assert.equal(tierCalls, 0);
    const recipes = await resolveBuildAssets({ ...inp, text: "custom crafting recipes" }, { ...deps, worldgenOn: () => true });
    assert.deepEqual(recipes.service, { texture: false, sound: false, namespace: NS, datapack: true });
  });
  it("delivery: restart + new-chunks + teleport notes; skipped when worldgen is off; never a reload", async () => {
    const plan = planDataPackDelivery({ namespace: NS, name: "crystal_realm", apply: "restart", worldgen: { dimensions: [`${NS}:crystal`] } });
    assert.deepEqual(plan.commands, []);
    assert.ok(plan.notes.some((n) => /restarts the server once/.test(n)) && plan.notes.some((n) => /Only NEW chunks/.test(n)) && plan.notes.some((n) => /teleport command/.test(n)));
    const b = buildDataPack(SHOWCASE, CTX("26.2")); assert.ok(b.ok); if (!b.ok) return;
    const reb = rebuildForDelivery({ spec: SHOWCASE, version: "26.2", packSha256: b.pack.sha256, worldgen: true }, NS);
    assert.ok(reb.ok && reb.sha256 === b.pack.sha256 && reb.apply === "restart"); if (!reb.ok) return;
    assert.deepEqual(reb.worldgen, { dimensions: [`${NS}:crystal`, `${NS}:flatland`] });
    assert.equal(rebuildForDelivery({ spec: SHOWCASE, version: "26.2", packSha256: b.pack.sha256 }, NS).ok, false, "without the recorded worldgen flag the spec does not build");
    const placed: string[] = [];
    const placer = { place: async (x: { files: { target: string }[] }) => { placed.push(x.files[0].target); }, remove: async () => {} } as never;
    const input = { projectId: "p", revisionId: "r", namespace: NS, name: "crystal_realm", version: "26.2", zip: reb.zip, sha256: reb.sha256, apply: "restart" as const, worldgen: reb.worldgen };
    const off = await deliverDataPack(input, { placer, env: { CYRUS_DATAPACK_DELIVERY_REAL: "1" } });
    assert.ok(!off.ok && off.skipped && /world generation is switched off/.test(off.reason));
    const bad = await deliverDataPack({ ...input, apply: "reload" }, { placer, env: { CYRUS_DATAPACK_DELIVERY_REAL: "1", CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1" } });
    assert.ok(!bad.ok && !bad.skipped);
    let consoleCalls = 0;
    const ok = await deliverDataPack(input, { placer, runConsole: async () => { consoleCalls++; }, env: { CYRUS_DATAPACK_DELIVERY_REAL: "1", CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1" } });
    assert.ok(ok.ok && ok.restartRequired); assert.equal(consoleCalls, 0, "no reload for world generation"); assert.equal(placed.length, 1);
  });
  it("portal sync: worldgen packs are re-validated with the portal's switch (off = dropped)", () => {
    const svc = [{ name: "crystal_realm", path: "assets/datapack/crystal_realm.json", sha256: "x", spec: SHOWCASE }];
    const off = checkReturnedDatapacks(svc, { namespace: NS, mcVersion: "26.2" });
    assert.equal(off.ok.length, 0); assert.match(off.dropped[0].reason, /world generation resources/);
    const on = checkReturnedDatapacks(svc, { namespace: NS, mcVersion: "26.2", worldgen: true });
    assert.equal(on.ok.length, 1); assert.equal(on.ok[0].pack.apply, "restart"); assert.ok(on.ok[0].pack.worldgen);
  });
});

