      const tpl = (spec.resources as { type: string; template?: unknown }[]).find((r) => r.type === "structure_template")!.template as never;
      for (const v of versions) for (const n of NAMES) {
        const buf = readFileSync(path.join(dir, v, `${n}.nbt`));
        const r = readNbt(buf);
        const keys = r.root.t === "compound" ? r.root.v.map(([k]) => k).sort() : [];
        const again = readNbt(gzipStored(writeNbt(r.root, r.name)));
        const ours = readNbt(compileTemplate(tpl, 0).nbt).root;
        const ourKeys = ours.t === "compound" ? ours.v.map(([k]) => k).sort() : [];
        const blocks = nbtGet(r.root, "blocks"), palette = nbtGet(r.root, "palette") ?? nbtGet(r.root, "palettes");
